def _session_has_afc_marker(session_name: str) -> bool:
    return "AFC" in (session_name or "").upper()


def _sync_trainee_afc_medical_requirement(trainee: Dict[str, Any], session_name: str) -> bool:
    required = _session_has_afc_marker(session_name)
    trainee["afc_medical_required"] = required
    return required


def _trainee_requires_afc_medical_cert(trainee: Optional[Dict[str, Any]]) -> bool:
    if not isinstance(trainee, dict):
        return False
    if bool(trainee.get("afc_medical_required")):
        return True
    return _session_has_afc_marker(str(trainee.get("session_name") or ""))


def _subtract_months(iso_date: str, months: int) -> str:
    try:
        source = datetime.date.fromisoformat(str(iso_date or "").strip())
    except Exception:
        return ""
    month_index = source.month - months
    year = source.year + (month_index - 1) // 12
    month = (month_index - 1) % 12 + 1
    day = min(source.day, calendar.monthrange(year, month)[1])
    return datetime.date(year, month, day).isoformat()

def required_docs_for_training(training_type: str, trainee: Optional[Dict[str, Any]] = None) -> List[Dict[str, Any]]:
    tt = (training_type or "").strip().upper()
    docs = list(REQUIRED_DOCS["COMMON"])

    # Pour les parcours dirigeant (initial / VAE),
    # ne pas demander le justificatif CNAPS à l'inscription.
    if tt in {"DIRIGEANT INITIAL", "DIRIGEANT VAE"}:
        docs = [d for d in docs if d.get("key") != "cnaps_doc"]

    if tt == "A3P":
        docs += list(REQUIRED_DOCS["A3P_ONLY"])
    if tt in {"DIRIGEANT INITIAL", "DIRIGEANT VAE"}:
        docs += list(REQUIRED_DOCS["DIRIGEANT_CANDIDATE_SHEET"])
    if tt.startswith("DIRIGEANT"):
        docs += list(REQUIRED_DOCS["DIRIGEANT_DIPLOMA"])
        if bool((trainee or {}).get("no_bac_diploma")):
            docs += list(REQUIRED_DOCS["DIRIGEANT_NO_BAC_PREREQUIS"])
    if tt == "DIRIGEANT INITIAL":
        docs += list(REQUIRED_DOCS["DIRIGEANT_INITIAL_ONLY"])
    if tt == "DIRIGEANT VAE":
        docs += list(REQUIRED_DOCS["DIRIGEANT_VAE_ONLY"])
    if _trainee_requires_afc_medical_cert(trainee):
        docs += list(REQUIRED_DOCS["AFC_SSIAP_MEDICAL_CERT"])
    return docs


def _is_dirigeant_candidate_sheet_training(training_type: str) -> bool:
    return (training_type or "").strip().upper() in {"DIRIGEANT INITIAL", "DIRIGEANT VAE"}


def _is_adef_training(training_type: str) -> bool:
    tt = (training_type or "").strip().upper()
    return "A3P" in tt or "APS" in tt

def ensure_documents_schema_for_trainee(t: Dict[str, Any], training_type: str) -> bool:
    """
    S'assure que t["documents"] contient tous les docs requis pour la formation,
    sans écraser fichiers/statuts existants. Supprime l'ancien doc 'dom' (domicile).
    """
    required = required_docs_for_training(training_type, t)
    existing = t.get("documents") or []
    changed = False

    # index existant
    by_key = {d.get("key"): d for d in existing if isinstance(d, dict) and d.get("key")}

    out = []
    for rd in required:
        k = rd["key"]
        if k in by_key:
            d = by_key[k]
            if not d.get("label"):
                d["label"] = rd["label"]; changed = True
            if "accept" not in d:
                d["accept"] = rd.get("accept", ""); changed = True
            if "status" not in d:
                d["status"] = "NON DÉPOSÉ"; changed = True
            if "comment" not in d:
                d["comment"] = ""; changed = True
            if "file" not in d:
                d["file"] = ""; changed = True
            if "files" not in d or not isinstance(d.get("files"), list):
                d["files"] = []
                changed = True
            out.append(d)
        else:
            out.append({
                "key": k,
                "label": rd["label"],
                "accept": rd.get("accept", ""),
                "status": "NON DÉPOSÉ",
                "comment": "",
                "file": "",
                "files": [],
            })
            changed = True

    complement_doc = by_key.get("complementary_documents")
    if complement_doc:
        legacy_tokens = []
        legacy_files = complement_doc.get("files") if isinstance(complement_doc.get("files"), list) else []
        legacy_tokens.extend(x for x in legacy_files if isinstance(x, str) and x.strip())
        legacy_file = (complement_doc.get("file") or "").strip()
        if legacy_file and legacy_file not in legacy_tokens:
            legacy_tokens.insert(0, legacy_file)
        if legacy_tokens:
            current_tokens = t.get("scotia_complementary_documents")
            if not isinstance(current_tokens, list):
                current_tokens = []
            for token in legacy_tokens:
                if token not in current_tokens:
                    current_tokens.append(token)
            t["scotia_complementary_documents"] = current_tokens
        # Ne jamais afficher cette entrée dans admin/public : elle est SCOTIA uniquement.
        changed = True

    # 🔥 on vire dom (plus utilisé)
    if "dom" in by_key:
        changed = True

    t["documents"] = out
    return changed


def _ensure_livret2_document_entry(t: Dict[str, Any]) -> Dict[str, Any]:
    """Garantit la présence du document technique livret_2 pour les uploads publics VAE."""
    docs = t.get("documents")
    if not isinstance(docs, list):
        docs = []
        t["documents"] = docs

    existing = next((d for d in docs if isinstance(d, dict) and d.get("key") == "livret_2"), None)
    if existing:
        if "files" not in existing or not isinstance(existing.get("files"), list):
            existing["files"] = []
        if "file" not in existing:
            existing["file"] = ""
        if "status" not in existing:
            existing["status"] = "NON DÉPOSÉ"
        if "accept" not in existing:
            existing["accept"] = "application/pdf,image/jpeg,image/png"
        if "label" not in existing:
            existing["label"] = "Livret 2"
        return existing

    livret2_doc = {
        "key": "livret_2",
        "label": "Livret 2",
        "accept": "application/pdf,image/jpeg,image/png",
        "status": "NON DÉPOSÉ",
        "comment": "",
        "file": "",
        "files": [],
    }
    docs.append(livret2_doc)
    return livret2_doc


def _ensure_complementary_documents_entry(t: Dict[str, Any]) -> List[str]:
    """Garantit une liste privée SCOTIA pour les documents complémentaires VAE."""
    tokens = t.get("scotia_complementary_documents")
    if not isinstance(tokens, list):
        tokens = []
        t["scotia_complementary_documents"] = tokens

    # Migration défensive d'une ancienne entrée documents, sans l'exposer admin/public.
    docs = t.get("documents") if isinstance(t.get("documents"), list) else []
    legacy_doc = next((d for d in docs if isinstance(d, dict) and d.get("key") == "complementary_documents"), None)
    if legacy_doc:
        legacy_files = legacy_doc.get("files") if isinstance(legacy_doc.get("files"), list) else []
        for token in legacy_files:
            if isinstance(token, str) and token.strip() and token not in tokens:
                tokens.append(token)
        legacy_file = (legacy_doc.get("file") or "").strip()
        if legacy_file and legacy_file not in tokens:
            tokens.insert(0, legacy_file)
    return tokens


def _scotia_complementary_documents_new_expected(t: Dict[str, Any]) -> bool:
    return (
        (t.get("scotia_status") or "").strip() == "complement_requested"
        and (t.get("scotia_complementary_documents_review_status") or "").strip() == "complement_documents_new_expected"
        and not _scotia_has_added_documents(t)
    )


def _public_complementary_documents_upload_expected(t: Dict[str, Any]) -> bool:
    return _scotia_complementary_documents_new_expected(t)


def _ensure_public_complementary_documents_upload_entry(t: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    if not _public_complementary_documents_upload_expected(t):
        return None

    docs = t.get("documents")
    if not isinstance(docs, list):
        docs = []
        t["documents"] = docs

    entry = next((d for d in docs if isinstance(d, dict) and d.get("key") == "complementary_documents"), None)
    if not isinstance(entry, dict):
        entry = {
            "key": "complementary_documents",
            "label": REQUIRED_DOCS["DIRIGEANT_VAE_COMPLEMENT"]["label"],
            "accept": REQUIRED_DOCS["DIRIGEANT_VAE_COMPLEMENT"].get("accept", ""),
            "status": "A CONTRÔLER",
            "comment": "",
            "file": "",
            "files": [],
        }
        docs.append(entry)

    tokens = [x for x in _ensure_complementary_documents_entry(t) if isinstance(x, str) and x.strip()]
    entry["files"] = tokens
    entry["file"] = tokens[0] if tokens else ""
    entry["status"] = "A CONTRÔLER" if tokens else "NON DÉPOSÉ"
    entry.setdefault("comment", "")
    entry["label"] = REQUIRED_DOCS["DIRIGEANT_VAE_COMPLEMENT"]["label"]
    entry["accept"] = REQUIRED_DOCS["DIRIGEANT_VAE_COMPLEMENT"].get("accept", "")
    return entry


def _sync_complementary_document_tokens_from_document(t: Dict[str, Any], doc: Optional[Dict[str, Any]]) -> None:
    if not isinstance(doc, dict):
        return
    tokens: List[str] = []
    files = doc.get("files") if isinstance(doc.get("files"), list) else []
    for token in files:
        if isinstance(token, str) and token.strip() and token not in tokens:
            tokens.append(token)
    file_token = (doc.get("file") or "").strip()
    if file_token and file_token not in tokens:
        tokens.insert(0, file_token)
    if tokens:
        t["scotia_complementary_documents"] = tokens

def allowed_doc_keys_for_training(training_type: str, trainee: Optional[Dict[str, Any]] = None) -> set:
    keys = {d["key"] for d in required_docs_for_training(training_type, trainee)}
    if (training_type or "").strip().upper() == "DIRIGEANT VAE":
        keys.add("livret_2")
        keys.add("complementary_documents")
    return keys


PROFESSIONAL_EXPERIENCE_SHEET_START_DATE = datetime.date(2026, 6, 8)


def _professional_experience_sheet_is_required(
    training_type: str,
    training_start_date: Any = "",
) -> bool:
    """Require the sheet for VAE or a formation starting after 8 June 2026."""
    if "VAE" in (training_type or "").strip().upper():
        return True
    start_datetime = _parse_iso_datetime(str(training_start_date or ""))
    if not start_datetime:
        return False
    return start_datetime.date() > PROFESSIONAL_EXPERIENCE_SHEET_START_DATE


def _professional_experience_sheet_is_submitted(trainee: Dict[str, Any]) -> bool:
    return isinstance(trainee.get("professional_experience_sheet"), dict) and bool(trainee["professional_experience_sheet"])


def _professional_experience_sheet_is_validated(trainee: Dict[str, Any]) -> bool:
    if not _professional_experience_sheet_is_submitted(trainee):
        return False
    status = str(trainee["professional_experience_sheet"].get("status") or "").strip().upper()
    return status in {"CONFORME", "VALIDATED"}


def dossier_is_complete(trainee: Dict[str, Any], training_type: str, training_start_date: Any = "") -> bool:
    """
    Complet si TOUS les docs requis sont CONFORME,
    sauf permis si trainee a coché no_permis=True (A3P).
    La fiche d'expérience professionnelle est également requise et validée
    pour les parcours VAE et les formations commençant après le 8 juin 2026.
    """
    docs = trainee.get("documents") or []
    if not docs:
        return False

    by_key = {d.get("key"): d for d in docs if isinstance(d, dict)}

    tt = (training_type or "").strip().upper()
    no_permis = bool(trainee.get("no_permis"))  # checkbox "je n'ai pas le permis"

    for rd in required_docs_for_training(training_type, trainee):
        k = rd["key"]

        # permis optionnel si no_permis
        if tt == "A3P" and k == "permis" and no_permis:
            continue

        d = by_key.get(k)
        if not d:
            return False

        st = (d.get("status") or "").strip().upper()
        if st != "CONFORME":
            return False

    if _professional_experience_sheet_is_required(training_type, training_start_date):
        return _professional_experience_sheet_is_validated(trainee)

    return True


def required_docs_are_deposited(trainee: Dict[str, Any], training_type: str, training_start_date: Any = "") -> bool:
    """Vrai si tous les documents requis sont déposés (peu importe leur conformité)."""
    docs = trainee.get("documents") or []
    if not docs:
        return False

    by_key = {d.get("key"): d for d in docs if isinstance(d, dict)}
    tt = (training_type or "").strip().upper()
    no_permis = bool(trainee.get("no_permis"))

    for rd in required_docs_for_training(training_type, trainee):
        k = rd["key"]

        if tt == "A3P" and k == "permis" and no_permis:
            continue

        # En parcours DIRIGEANT VAE, la fiche d'entretien pré-requis ne doit
        # pas bloquer le déverrouillage de l'étape 1 (livret 1) côté public.
        if tt == "DIRIGEANT VAE" and k == "prerequis_interview_sheet":
            continue

        d = by_key.get(k)
        if not d:
            return False

        # La fiche candidat (DIRIGEANT VAE) est un formulaire HTML sauvegardé,
        # pas forcément un upload de fichier binaire.
        if k == "candidate_info_sheet":
            st = (d.get("status") or "").strip().upper()
            candidate_sheet_saved = bool(trainee.get("candidate_sheet_saved_at") or trainee.get("candidate_sheet"))
            if st in {"A CONTRÔLER", "A CONTROLER", "CONFORME", "NON CONFORME"}:
                continue
            if candidate_sheet_saved and st not in {"", "NON DÉPOSÉ", "NON DEPOSE"}:
                continue
            return False

        files = d.get("files") if isinstance(d.get("files"), list) else []
        has_files = any(f for f in files)
        has_file = bool((d.get("file") or "").strip())
        if not (has_files or has_file):
            return False

    if _professional_experience_sheet_is_required(training_type, training_start_date):
        return _professional_experience_sheet_is_submitted(trainee)

    return True


import re

PRE_CAR_PATTERNS = (
    re.compile(r"^(PRE|CAR)-(?:\d{3}-)?\d{4}-\d{2}-\d{2}-\d{11}$"),
    re.compile(r"^\d{4}-\d{7}-(PRE|CAR)-[A-Z0-9]{2}-\d{7}$"),
)

CNAPS_PRE_IN_TEXT_PATTERN = re.compile(
    r"(?:\b(?:PRE|CAR)\b[\s:\-]*)?((?:\d{4}[\s\-]?\d{7}[\s\-]?(?:PRE|CAR)[\s\-]?[A-Z0-9]{2}[\s\-]?\d{7})|(?:(?:PRE|CAR)[\s\-]?(?:\d{3}[\s\-]?)?\d{4}[\s\-]?\d{2}[\s\-]?\d{2}[\s\-]?\d{11}))",
    re.IGNORECASE,
)


def _normalize_pre_car(value: str) -> str:
    normalized = (value or "").strip().upper().replace(" ", "")
    compact = re.sub(r"[^A-Z0-9]", "", normalized)

    m = re.match(r"^(\d{4})(\d{7})(PRE|CAR)([A-Z0-9]{2})(\d{7})$", compact)
    if m:
        return f"{m.group(1)}-{m.group(2)}-{m.group(3)}-{m.group(4)}-{m.group(5)}"

    return normalized


def _is_valid_pre_car(value: str) -> bool:
    normalized = _normalize_pre_car(value)
    return any(pattern.match(normalized) for pattern in PRE_CAR_PATTERNS)


def _normalize_person_name(value: str) -> str:
    raw = str(value or "").strip()
    if not raw:
        return ""
    cleaned = unicodedata.normalize("NFD", raw)
    cleaned = "".join(ch for ch in cleaned if unicodedata.category(ch) != "Mn")
    cleaned = re.sub(r"[^A-Za-z\-\s]", " ", cleaned)
    return " ".join(cleaned.upper().split())


def _extract_pre_from_text(raw_text: str) -> str:
    if not raw_text:
        return ""
    for match in CNAPS_PRE_IN_TEXT_PATTERN.finditer(raw_text.upper()):
        candidate = _normalize_pre_car(match.group(1) or "")
        if _is_valid_pre_car(candidate):
            return candidate
    return ""


def _extract_pre_from_compact_text(compact_text: str) -> str:
    if not compact_text:
        return ""

    upper = re.sub(r"[^A-Z0-9]", "", compact_text.upper())
    for pat in (
        re.compile(r"(\d{4}\d{7}(?:PRE|CAR)[A-Z0-9]{2}\d{7})"),
        re.compile(r"((?:PRE|CAR)(?:\d{3})?\d{4}\d{2}\d{2}\d{11})"),
    ):
        m = pat.search(upper)
        if not m:
            continue
        candidate = _normalize_pre_car(m.group(1) or "")
        if _is_valid_pre_car(candidate):
            return candidate
    return ""


def _extract_name_from_cnaps_text(raw_text: str) -> Tuple[str, str]:
    if not raw_text:
        return "", ""

    text = raw_text.replace("\r", "\n")
    compact = re.sub(r"\s+", " ", text)

    # Cas le plus fiable: "numéro <PRE/CAR> est délivrée à Prénom NOM..."
    # (présent en Article 1 des décisions CNAPS).
    delivery_with_number_match = re.search(
        r"num[ée]ro\s+[A-Z0-9\-\s]{8,}\s+est\s+d[ée]livr[ée]e?\s+[àa]\s+([^,;\n]+?)(?:,\s*n[ée]\(e\)|\s+n[ée]\(e\)|,\s+pour\b|\s+pour\b|[.;])",
        compact,
        re.IGNORECASE,
    )
    if delivery_with_number_match:
        name_block = " ".join((delivery_with_number_match.group(1) or "").strip().split())
        tokens = re.findall(r"[A-Za-zÀ-ÖØ-öø-ÿ][A-Za-zÀ-ÖØ-öø-ÿ\-']*", name_block)
        if len(tokens) >= 2:
            first_name = tokens[0]
            last_name = " ".join(tokens[1:])
            return _normalize_person_name(last_name), _normalize_person_name(first_name)

    # Cas métier observé : "... est délivrée à Prénom NOM, né(e)..."
    delivery_match = re.search(
        r"est\s+d[ée]livr[ée]e?\s+[àa]\s+([^,;\n]+?)(?:,\s*n[ée]\(e\)|\s+n[ée]\(e\)|,\s+pour\b|\s+pour\b|[.;])",
        compact,
        re.IGNORECASE,
    )
    if delivery_match:
        name_block = " ".join((delivery_match.group(1) or "").strip().split())
        tokens = re.findall(r"[A-Za-zÀ-ÖØ-öø-ÿ][A-Za-zÀ-ÖØ-öø-ÿ\-']*", name_block)
        if len(tokens) >= 2:
            first_name = tokens[0]
            last_name = " ".join(tokens[1:])
            return _normalize_person_name(last_name), _normalize_person_name(first_name)

    # Variante observée: "... demande présentée ... par Prénom NOM, né(e)..."
    requested_by_match = re.search(
        r"\bpar\s+([^,;\n]+?)(?:,\s*n[ée]\(e\)|\s+n[ée]\(e\)|,\s+en\s+vue\b|\s+en\s+vue\b|[.;])",
        compact,
        re.IGNORECASE,
    )
    if requested_by_match:
        name_block = " ".join((requested_by_match.group(1) or "").strip().split())
        tokens = re.findall(r"[A-Za-zÀ-ÖØ-öø-ÿ][A-Za-zÀ-ÖØ-öø-ÿ\-']*", name_block)
        if len(tokens) >= 2:
            first_name = tokens[0]
            last_name = " ".join(tokens[1:])
            return _normalize_person_name(last_name), _normalize_person_name(first_name)

    patterns = [
        re.compile(r"\bNOM\s*[:\-]\s*([A-Za-zÀ-ÖØ-öø-ÿ\-\s']{2,})\b"),
        re.compile(r"\bPR[ÉE]NOM\s*[:\-]\s*([A-Za-zÀ-ÖØ-öø-ÿ\-\s']{2,})\b"),
    ]

    last_name = ""
    first_name = ""
    for pat in patterns:
        m = pat.search(compact)
        if not m:
            continue
        value = " ".join((m.group(1) or "").strip().split())
        if "PR" in pat.pattern:
            first_name = value
        else:
            last_name = value

    if last_name and first_name:
        return _normalize_person_name(last_name), _normalize_person_name(first_name)

    # Cas CNAPS fréquent: "Mickaël BOUCHEZ" (prénom puis nom en majuscules)
    cap_name = re.search(
        r"\b([A-ZÀ-ÖØ-Þ][a-zà-öø-ÿ][A-Za-zÀ-ÖØ-öø-ÿ\-']*)\s+([A-ZÀ-ÖØ-Þ][A-ZÀ-ÖØ-Þ\-']{1,})\b",
        compact,
    )
    if cap_name:
        return _normalize_person_name(cap_name.group(2)), _normalize_person_name(cap_name.group(1))

    fallback = re.search(
        r"\b(?:M\.?|MME|MONSIEUR|MADAME)\s+([A-Za-zÀ-ÖØ-öø-ÿ\-']{2,})\s+([A-Za-zÀ-ÖØ-öø-ÿ\-']{2,})\b",
        compact,
        re.IGNORECASE,
    )
    if fallback:
        a = _normalize_person_name(fallback.group(1))
        b = _normalize_person_name(fallback.group(2))
        # On privilégie NOM, PRENOM ; la résolution backend testera aussi l'ordre inversé.
        return a, b

    return "", ""


def _find_cnaps_trainee_match(
    trainees_index: Dict[Tuple[str, str], List[Dict[str, Any]]],
    trainees_by_last_name: Dict[str, List[Dict[str, Any]]],
    last_name: str,
    first_name: str,
) -> Optional[Dict[str, Any]]:
    direct = trainees_index.get((last_name, first_name)) or []
    if direct:
        return direct[0]

    swapped = trainees_index.get((first_name, last_name)) or []
    if swapped:
        return swapped[0]

    # Fallback demandé métier: recherche uniquement par NOM.
    # Si plusieurs stagiaires partagent le même nom, on préfère quand même
    # celui qui matche le prénom si l'information existe, sinon le premier.
    by_last_name = trainees_by_last_name.get(last_name) or []
    if not by_last_name:
        return None

    normalized_first = _normalize_person_name(first_name)
    if normalized_first:
        for entry in by_last_name:
            trainee = entry.get("trainee") or {}
            trainee_first = _normalize_person_name(trainee.get("first_name", ""))
            if trainee_first == normalized_first:
                return entry

    return by_last_name[0]


def _find_cnaps_trainee_match_in_text(
    trainees_by_last_name: Dict[str, List[Dict[str, Any]]],
    raw_text: str,
    first_name: str = "",
) -> Optional[Dict[str, Any]]:
    normalized_text = _normalize_person_name(raw_text)
    if not normalized_text:
        return None

    haystack = f" {normalized_text} "
    candidates: List[Dict[str, Any]] = []
    for last_name, entries in trainees_by_last_name.items():
        last_clean = _normalize_person_name(last_name)
        if not last_clean:
            continue
        if f" {last_clean} " in haystack:
            candidates.extend(entries)

    if not candidates:
        return None

    normalized_first = _normalize_person_name(first_name)
    if normalized_first:
        for entry in candidates:
            trainee = entry.get("trainee") or {}
            trainee_first = _normalize_person_name(trainee.get("first_name", ""))
            if trainee_first == normalized_first:
                return entry

    if len(candidates) == 1:
        return candidates[0]

    # Ambigu sans prénom fiable: on refuse l'auto-association.
    return None


def _cnaps_pending_imports(data: Dict[str, Any]) -> List[Dict[str, Any]]:
    pending = data.get("cnaps_pending_imports")
    if not isinstance(pending, list):
        pending = []
        data["cnaps_pending_imports"] = pending
    return pending


def _find_cnapsv3_identifier_for_pending(data: Dict[str, Any], last_name: str, first_name: str) -> Dict[str, str]:
    target_last = _normalize_person_name(last_name or "")
    target_first = _normalize_person_name(first_name or "")
    if not target_last or not target_first:
        return {"request_id": "", "dossier_id": ""}

    bucket = data.get("notifications_cnaps_pre_relances") or []
    if not isinstance(bucket, list):
        return {"request_id": "", "dossier_id": ""}

    for item in bucket:
        if not isinstance(item, dict):
            continue
        meta = item.get("meta") or {}
        if not isinstance(meta, dict):
            continue

        first = _normalize_person_name(meta.get("first_name") or "")
        last = _normalize_person_name(meta.get("last_name") or "")
        if first != target_first or last != target_last:
            continue

        request_id = str(meta.get("cnapsv3_request_id") or "").strip()
        dossier_id = str(meta.get("cnapsv3_dossier_id") or "").strip()
        return {"request_id": request_id, "dossier_id": dossier_id}

    return {"request_id": "", "dossier_id": ""}


def _find_pending_trainee_email(data: Dict[str, Any], last_name: str, first_name: str) -> str:
    target_last = _normalize_person_name(last_name or "")
    target_first = _normalize_person_name(first_name or "")
    if not target_last or not target_first:
        return ""

    for session_obj in data.get("sessions", []):
        trainees = _session_trainees_list(session_obj)
        for trainee in trainees:
            trainee_last = _normalize_person_name(trainee.get("last_name", ""))
            trainee_first = _normalize_person_name(trainee.get("first_name", ""))
            if trainee_last != target_last or trainee_first != target_first:
                continue
            return str(trainee.get("email") or "").strip()

    return ""


def _store_cnaps_pending_pdf(file_bytes: bytes, original_filename: str) -> str:
    target_dir = os.path.join(UPLOADS_DIR, "cnaps_pending")
    os.makedirs(target_dir, exist_ok=True)

    ext = _safe_ext(original_filename or "") or ".pdf"
    if ext != ".pdf":
        ext = ".pdf"

    filename = f"{uuid.uuid4().hex[:10]}{ext}"
    full_path = os.path.join(target_dir, filename)
    with open(full_path, "wb") as f:
        f.write(file_bytes or b"")
    return _tokenize_path(full_path)


def _attach_cnaps_to_trainee(
    trainee: Dict[str, Any],
    training_type: str,
    pre_number: str,
    file_token: str,
    history_label: str,
    training_start_date: Any = "",
) -> None:
    ensure_documents_schema_for_trainee(trainee, training_type)

    trainee["pre_number"] = pre_number

    docs = trainee.get("documents") or []
    cnaps_doc = next((d for d in docs if d.get("key") == "cnaps_doc"), None)
    if not cnaps_doc:
        cnaps_doc = {
            "key": "cnaps_doc",
            "label": "Autorisation CNAPS ou Carte professionnelle CNAPS (en cours de validité)",
            "accept": "application/pdf",
            "file": "",
            "files": [],
            "status": "NON DÉPOSÉ",
            "comment": "",
        }
        docs.append(cnaps_doc)
        trainee["documents"] = docs

    cnaps_doc["files"] = [file_token]
    cnaps_doc["file"] = file_token
    cnaps_doc["status"] = "A CONTRÔLER"

    trainee["updated_at"] = _now_iso()
    trainee["dossier_status"] = "complete" if dossier_is_complete_total(trainee, training_type, training_start_date) else "incomplete"
    append_trainee_history_event(trainee, history_label, f"PRE/CAR : {pre_number}", "action")


def _apply_pending_cnaps_imports_for_trainee(data: Dict[str, Any], session_obj: Dict[str, Any], trainee: Dict[str, Any]) -> int:
    pending = _cnaps_pending_imports(data)
    if not pending:
        return 0

    trainee_last = _normalize_person_name(trainee.get("last_name", ""))
    trainee_first = _normalize_person_name(trainee.get("first_name", ""))
    if not trainee_last or not trainee_first:
        return 0

    applied = 0
    remaining = []
    for item in pending:
        item_last = _normalize_person_name(item.get("last_name", ""))
        item_first = _normalize_person_name(item.get("first_name", ""))
        same_order = (item_last == trainee_last and item_first == trainee_first)
        swapped_order = (item_last == trainee_first and item_first == trainee_last)
        if not (same_order or swapped_order):
            remaining.append(item)
            continue

        pre_number = _normalize_pre_car(item.get("pre_number", ""))
        file_token = (item.get("file_token") or "").strip()
        if not file_token or not _is_valid_pre_car(pre_number):
            remaining.append(item)
            continue

        _attach_cnaps_to_trainee(
            trainee,
            _session_get(session_obj, "training_type", ""),
            pre_number,
            file_token,
            "Import PRE CNAPS auto-associé",
            _session_get(session_obj, "date_start", ""),
        )
        trainee["cnaps_import_merged_once"] = True
        trainee["cnaps_import_merged_at"] = _now_iso()
        applied += 1

    data["cnaps_pending_imports"] = remaining
    return applied

def infos_is_complete(t: Dict[str, Any]) -> bool:
    # Champs obligatoires
    required = [
        "birth_date",
        "birth_city",
        "birth_country",
        "nationality",
        "address",
        "zip_code",
        "city",
    ]
    for k in required:
        if not (t.get(k) or "").strip():
            return False

    # Sécu : 15 chiffres
    secu_digits = re.sub(r"\D+", "", (t.get("carte_vitale") or ""))
    if len(secu_digits) != 15:
        return False

    # PRE/CAR : format strict PRE-013-2029-07-25-20240908920 ou CAR-013-2029-07-25-20240908920
    if not _is_valid_pre_car(t.get("pre_number") or ""):
        return False

    return True


def infos_is_complete_without_pre(t: Dict[str, Any]) -> bool:
    """Version de complétude infos sans exigence PRE/CAR."""
    required = [
        "birth_date",
        "birth_city",
        "birth_country",
        "nationality",
        "address",
        "zip_code",
        "city",
    ]
    for k in required:
        if not (t.get(k) or "").strip():
            return False

    secu_digits = re.sub(r"\D+", "", (t.get("carte_vitale") or ""))
    return len(secu_digits) == 15


def infos_is_complete_for_training(t: Dict[str, Any], training_type: str) -> bool:
    """
    Vérifie la complétude des informations selon le parcours.

    - Parcours standards : règles existantes (infos + sécu + PRE/CAR).
    - DIRIGEANT VAE : accepte aussi la fiche candidat complétée,
      qui ne contient pas les champs sécu/PRE.
    """
    tt = (training_type or "").strip().upper()

    # Pour VTC et parcours dirigeant hors VAE, le champ PRE/CAR n'est pas demandé.
    if "VTC" in tt or ("DIRIGEANT" in tt and tt != "DIRIGEANT VAE"):
        return infos_is_complete_without_pre(t)

    if tt != "DIRIGEANT VAE":
        base_complete = infos_is_complete(t)
        if not base_complete:
            return False
        if tt == "A3P":
            return (t.get("tshirt_size") or "").strip().upper() in TSHIRT_SIZES
        return True

    # Si les champs standards sont tous OK, on est complet aussi.
    if infos_is_complete(t):
        return True

    sheet = t.get("candidate_sheet")
    if not isinstance(sheet, dict):
        return False

    required_sheet_fields = [
        "birth_date",
        "birth_city",
        "country",
        "nationality",
        "address",
        "postal_code",
        "city",
    ]
    return all(str(sheet.get(k) or "").strip() for k in required_sheet_fields)

def dossier_is_complete_total(trainee: Dict[str, Any], training_type: str, training_start_date: Any = "") -> bool:
    # ✅ complet seulement si infos OK + tous docs CONFORME
    # ✅ OU si forçage admin
    if trainee.get("force_dossier_complete"):
        return True
    return infos_is_complete_for_training(trainee, training_type) and dossier_is_complete(trainee, training_type, training_start_date)


