PUBLIC_VAE_DESP_SESSION_NAME = "VAE DESP 2026"


def find_session_by_name(data: Dict[str, Any], session_name: str) -> Optional[Dict[str, Any]]:
    target = (session_name or "").strip().lower()
    if not target:
        return None
    for s in data.get("sessions", []):
        if (_session_get(s, "name", "") or "").strip().lower() == target:
            return s
    return None

@app.get("/")
def home():
    return redirect(url_for("admin_wedof_requests"))


@app.get("/test-positionnement")
def positioning_test_public():
    return render_template(
        "positioning_test_public.html",
        sections=positioning_test_public_sections(),
        total_questions=POSITIONING_TEST_TOTAL,
        total_over_20=20,
    )


@app.get("/positioning_test_public.html")
def positioning_test_public_legacy():
    return redirect(url_for("positioning_test_public"), code=301)


@app.get("/vae-desp")
def public_vae_desp_form():
    return render_template("public_vae_desp_form.html")


@app.get("/vae-desp/confirmation")
def public_vae_desp_confirmation():
    token = (request.args.get("token") or "").strip()
    trainee_space_url = url_for("public_vae_desp_form")

    if token:
        data = load_data()
        _, trainee = find_session_and_trainee_by_token(data, token)
        if trainee:
            trainee_space_url = url_for("public_trainee_space", token=token)

    return render_template(
        "public_vae_desp_confirmation.html",
        trainee_space_url=trainee_space_url,
    )


@app.post("/vae-desp")
def public_vae_desp_submit():
    payload = request.get_json(silent=True) or request.form
    last_name = normalize_last_name(payload.get("last_name") or "")
    first_name = normalize_first_name(payload.get("first_name") or "")
    birth_date = (payload.get("birth_date") or "").strip()
    email = (payload.get("email") or "").strip()
    email_confirm = (payload.get("email_confirm") or "").strip()
    phone = (payload.get("phone") or "").strip()
    eligibility_confirmed = payload.get("eligibility_confirmed")
    eligibility_confirmed = True if eligibility_confirmed in (True, "true", "1", 1, "yes", "on") else False

    if not all([last_name, first_name, birth_date, email, email_confirm, phone]):
        return jsonify({"ok": False, "error": "missing_fields"}), 400
    if email.lower() != email_confirm.lower():
        return jsonify({"ok": False, "error": "email_mismatch"}), 400
    if not eligibility_confirmed:
        return jsonify({"ok": False, "error": "eligibility_required"}), 400

    data = load_data()
    target_session = find_session_by_name(data, PUBLIC_VAE_DESP_SESSION_NAME)
    if not target_session:
        return jsonify({"ok": False, "error": "session_not_found"}), 404

    trainee_id = "TRN-" + uuid.uuid4().hex[:8].upper()
    public_token = uuid.uuid4().hex
    training_type = _session_get(target_session, "training_type", "")
    default_price = default_training_price(training_type)

    trainee = {
        "id": trainee_id,
        "personal_id": trainee_id,
        "last_name": last_name,
        "first_name": first_name,
        "birth_date": birth_date,
        "birth_city": "",
        "email": email,
        "phone": phone,
        "vtc_cmar_id": "",
        "address": "",
        "zip_code": "",
        "city": "",
        "comment": "Inscription via formulaire public VAE DESP",
        "cnaps": "INCONNU",
        "convention_status": "soon",
        "test_fr_status": "soon",
        "dossier_status": "incomplete",
        "financement_status": "soon",
        "training_price": default_price if default_price is not None else "",
        "cpf_amount": "",
        "personal_amount": "",
        "other_amount": "",
        "vae_status": "soon",
        "hosting_status": "",
        "public_token": public_token,
        "tshirt_size": "",
        "no_permis": False,
        "no_bac_diploma": False,
        "force_dossier_complete": False,
        "professional_experience_sheet_required": True,
        "vtc_cm_login": "",
        "vtc_cm_password": "",
        "vtc_cm_submitted_at": "",
        "vtc_cm_reminder_sent_at": "",
        "vtc_cm_reminder_email_ok": False,
        "vtc_cm_reminder_sms_ok": False,
        "vtc_cm_reminder_copy_email_ok": False,
        "exam_fees_paid": False,
        "exam_fees_paid_at": "",
        "elearning_link": "",
        "elearning_link_sent_at": "",
        "elearning_link_email_ok": False,
        "elearning_link_sms_ok": False,
        "vtc_book_sent_at": "",
        "documents": [],
        "created_at": _now_iso(),
        "phone_followups": [],
        "public_hide_popup": False,
        "ssiap_exam_date": "",
    }

    _sync_trainee_afc_medical_requirement(trainee, _session_get(target_session, "name", ""))
    ensure_documents_schema_for_trainee(trainee, training_type)
    trainee["dossier_status"] = "complete" if dossier_is_complete_total(trainee, training_type, _session_get(target_session, "date_start", "")) else "incomplete"

    trainees = _session_trainees_list(target_session)
    trainees.insert(0, trainee)
    target_session["trainees"] = trainees
    target_session.pop("stagiaires", None)

    add_admin_notification(
        data,
        f"🔔 Nouvelle demande de VAE {first_name} {last_name}",
        {
            "kind": "public_vae_desp_request",
            "session_id": target_session.get("id") or "",
            "session_name": target_session.get("name") or "",
            "trainee_id": trainee_id,
            "first_name": first_name,
            "last_name": last_name,
            "comment": "Demande issue du formulaire public VAE DESP",
        },
    )
    save_data(data)

    _send_vae_admin_notification(
        "Nouvelle demande via le formulaire public VAE DESP",
        trainee=trainee,
        session_obj=target_session,
        details={
            "origine": "Formulaire public VAE DESP",
            "date_naissance": birth_date,
            "session_name": target_session.get("name") or "",
            "session_id": target_session.get("id") or "",
            "trainee_id": trainee_id,
        },
    )

    link = f"{PUBLIC_STUDENT_PORTAL_BASE.rstrip('/')}/espace/{public_token}"
    subject, html, sms = build_dirigeant_vae_onboarding_email_sms(first_name, link)
    email_ok = brevo_send_email(email, subject, html, trainee=trainee) if email else False
    sms_ok = brevo_send_sms(phone, sms) if phone else False

    return jsonify(
        {
            "ok": True,
            "email_ok": bool(email_ok),
            "sms_ok": bool(sms_ok),
            "redirect_url": url_for("public_vae_desp_confirmation", token=public_token),
        }
    )




def _all_scotia_items(data: Dict[str, Any], include_archived: bool = False) -> List[Dict[str, Any]]:
    def _is_truthy(value: Any) -> bool:
        return value in (True, "true", "1", 1, "yes", "on", "True")

    def _scotia_log_visibility(level: str, message: str, payload: Dict[str, Any]) -> None:
        log = app.logger.warning if level == "warning" else app.logger.info
        log("[SCOTIA_VISIBILITY] %s payload=%s", message, payload)

    items: List[Dict[str, Any]] = []
    for s in data.get("sessions", []):
        training_type = (_session_get(s, "training_type", "") or "").strip().upper()
        session_is_vae = "VAE" in training_type
        for t in _session_trainees_list(s):
            action_dates = t.get("vae_action_dates") if isinstance(t.get("vae_action_dates"), dict) else {}
            livret_1_sent_at = (action_dates.get("livret_1_transmitted_scotia") or t.get("livret_1_transmitted_scotia") or t.get("livret_1_transmitted_scotia_at") or "").strip()
            livret_2_sent_at = (action_dates.get("livret_2_transmitted_scotia") or t.get("livret_2_transmitted_scotia") or t.get("livret_2_transmitted_scotia_at") or "").strip()
            attestation_recevabilite_imported_at = (action_dates.get("attestation_recevabilite_imported_at") or "").strip()
            sent_at = livret_2_sent_at or livret_1_sent_at
            force_scotia_visibility = _is_truthy(t.get("scotia_force_visible"))
            stored_scotia_status = (t.get("scotia_status") or "").strip()
            raw_vae_status = t.get("vae_status")
            raw_vae_status_label = t.get("vae_status_label")
            vae_status_key = vae_status_view(raw_vae_status or raw_vae_status_label)["key"]
            inferred_vae_status_key = _infer_vae_status_from_action_dates(action_dates)
            if inferred_vae_status_key is not None and VAE_STATUS_RANK.get(inferred_vae_status_key, -1) > VAE_STATUS_RANK.get(vae_status_key, -1):
                vae_status_key = inferred_vae_status_key
            livret_1_validated_or_later = VAE_STATUS_RANK.get(vae_status_key, -1) >= VAE_STATUS_RANK["livret_1_validated"]
            certified_vae = vae_status_key == "certified"
            visibility_payload = {
                "session_id": str(s.get("id") or ""),
                "session_name": _session_get(s, "name", ""),
                "training_type": training_type,
                "session_is_vae": session_is_vae,
                "trainee_id": str(t.get("id") or ""),
                "trainee_name": _format_trainee_name(t.get("first_name", ""), t.get("last_name", "")),
                "raw_vae_status": raw_vae_status or "",
                "raw_vae_status_label": raw_vae_status_label or "",
                "effective_vae_status": vae_status_key,
                "inferred_vae_status": inferred_vae_status_key or "",
                "action_dates_keys": sorted(str(k) for k, v in action_dates.items() if v),
                "livret_1_sent_at": livret_1_sent_at,
                "livret_2_sent_at": livret_2_sent_at,
                "sent_at": sent_at,
                "force_scotia_visibility": force_scotia_visibility,
                "livret_1_validated_or_later": livret_1_validated_or_later,
                "certified_vae": certified_vae,
                "stored_scotia_status": stored_scotia_status,
                "scotia_hidden": _is_truthy(t.get("scotia_hidden")),
            }
            should_log_non_vae_exclusion = (
                livret_1_validated_or_later
                or bool(action_dates)
                or bool((raw_vae_status or "").strip() and (raw_vae_status or "").strip() != "soon")
                or bool((raw_vae_status_label or "").strip())
                or "VAE" in (_session_get(s, "name", "") or "").upper()
            )
            archive_category = ""
            if certified_vae:
                archive_category = "certified"
            elif stored_scotia_status == "non_recevable":
                archive_category = "non-recevable"
            elif (
                stored_scotia_status == "recevable"
                and (t.get("scotia_livret_2_status") or "").strip() == "livret_2_ok"
            ) or vae_status_key == "livret_2_validated":
                archive_category = "l2-validated"

            if certified_vae and not include_archived:
                _scotia_log_visibility("info", "excluded: certified_vae", visibility_payload)
                continue
            if stored_scotia_status == "non_recevable" and not include_archived:
                _scotia_log_visibility("info", "excluded: non_recevable", visibility_payload)
                continue
            if _is_truthy(t.get("scotia_hidden")) and not force_scotia_visibility and not sent_at and not livret_1_validated_or_later:
                _scotia_log_visibility("warning", "excluded: scotia_hidden", visibility_payload)
                continue
            # Les sessions non-VAE n'alimentent pas Scotia par défaut,
            # sauf en cas de propulsion manuelle depuis l'admin stagiaire.
            if not session_is_vae and not force_scotia_visibility:
                if should_log_non_vae_exclusion:
                    _scotia_log_visibility("warning", "excluded: session_not_vae", visibility_payload)
                continue
            if not sent_at and not force_scotia_visibility and not livret_1_validated_or_later and not (include_archived and archive_category):
                _scotia_log_visibility("warning", "excluded: no_transmission_no_force_no_validated_livret1", visibility_payload)
                continue
            included_reason = "forced" if force_scotia_visibility else ("vae_status_livret_1_validated_or_later" if livret_1_validated_or_later and not sent_at else "scotia_transmission_date")
            if _is_truthy(t.get("scotia_hidden")):
                included_reason = f"{included_reason}_despite_scotia_hidden"
            _scotia_log_visibility("info", f"included: {included_reason}", visibility_payload)
            deliverables = t.get("deliverables") or {}
            has_attestation_recevabilite = bool((deliverables.get("attestation_recevabilite") or "").strip())
            livret_2_token = (deliverables.get("livret_2") or "").strip()
            livret_2_imported_at = (action_dates.get("livret_2_imported_at") or "").strip()
            if livret_2_token and not livret_2_imported_at:
                livret_2_imported_at = (action_dates.get("livret_2_received") or "").strip()
            if has_attestation_recevabilite and not attestation_recevabilite_imported_at:
                attestation_recevabilite_imported_at = (action_dates.get("livret_1_validated") or "").strip()
            docs_view = []
            prerequis_interview_sheet_token = ""
            complementary_document_tokens = _ensure_complementary_documents_entry(t)
            added_document_groups = _ensure_scotia_added_documents_entry(t)
            for d in (t.get("documents") or []):
                token = (d.get("file") or "").strip()
                files = d.get("files") if isinstance(d.get("files"), list) else []
                file_tokens = [x for x in files if isinstance(x, str) and x.strip()]
                if token and token not in file_tokens:
                    file_tokens.insert(0, token)
                if not prerequis_interview_sheet_token and d.get("key") == "prerequis_interview_sheet":
                    prerequis_interview_sheet_token = file_tokens[0] if file_tokens else token
                if d.get("key") == "complementary_documents":
                    complementary_document_tokens = file_tokens
                docs_view.append({
                    "key": d.get("key"),
                    "label": d.get("label") or d.get("key"),
                    "file": token,
                    "file_tokens": file_tokens,
                })

            latest_vae = _vae_find_latest_for_trainee(str(t.get("id") or ""))
            vae_justificatifs = latest_vae.get("justificatifs_experience") if isinstance(latest_vae, dict) and isinstance(latest_vae.get("justificatifs_experience"), list) else []

            item_data = {
                "session_id": str(s.get("id") or ""),
                "session_name": _session_get(s, "name", ""),
                "trainee_id": str(t.get("id") or ""),
                "scotia_anchor": _scotia_dossier_anchor(str(s.get("id") or ""), str(t.get("id") or "")),
                "first_name": (t.get("first_name") or "").strip(),
                "last_name": (t.get("last_name") or "").strip(),
                "email": (t.get("email") or "").strip(),
                "phone": (t.get("phone") or "").strip(),
                "vae_sent_at": sent_at,
                "livret_1_sent_at": livret_1_sent_at,
                "livret_2_sent_at": livret_2_sent_at,
                "scotia_force_visible": force_scotia_visibility,
                "scotia_status": (stored_scotia_status or ("recevable" if livret_1_validated_or_later else "")).strip(),
                "scotia_processed_at": (t.get("scotia_processed_at") or "").strip(),
                "scotia_comment": (t.get("scotia_comment") or "").strip(),
                "scotia_livret_2_status": (t.get("scotia_livret_2_status") or "").strip(),
                "scotia_livret_2_processed_at": (t.get("scotia_livret_2_processed_at") or "").strip(),
                "documents": docs_view,
                "prerequis_interview_sheet": prerequis_interview_sheet_token,
                "complementary_documents": complementary_document_tokens,
                "complementary_documents_received_at": (action_dates.get("complementary_documents_received") or "").strip(),
                "scotia_complementary_documents_review_status": (t.get("scotia_complementary_documents_review_status") or "").strip(),
                "scotia_complementary_documents_reviewed_at": (t.get("scotia_complementary_documents_reviewed_at_label") or _format_scotia_comment_added_at(t.get("scotia_complementary_documents_reviewed_at") or "")).strip(),
                "added_document_groups": added_document_groups,
                "scotia_thread_comments": _scotia_thread_comments_for_display(t),
                "scotia_unread_thread_summary": _scotia_unread_thread_summary(t),
                "deliverables": deliverables,
                "attestation_recevabilite_imported_at": attestation_recevabilite_imported_at,
                "livret_2_imported_at": livret_2_imported_at,
                "candidate_sheet_available": bool(t.get("candidate_sheet_saved_at") or t.get("candidate_sheet")),
                "vae_dossier_id": str((latest_vae or {}).get("id") or ""),
                "vae_justificatifs": vae_justificatifs,
                "vae_status_key": vae_status_key,
                "vae_status_label": vae_status_view(vae_status_key)["label"],
                "scotia_archive_category": archive_category,
                "is_scotia_archive": bool(archive_category),
            }
            item_data["scotia_dashboard_category"] = _scotia_dashboard_category(item_data)
            items.append(item_data)
    def _scotia_sort_key(item: Dict[str, Any]):
        sent_at_raw = item.get("vae_sent_at") or ""
        parsed_dt = _parse_iso_datetime(sent_at_raw)
        if not parsed_dt and sent_at_raw:
            for fmt in ("%d/%m/%Y %H:%M:%S", "%d/%m/%Y %H:%M", "%d/%m/%Y"):
                try:
                    parsed_dt = datetime.datetime.strptime(sent_at_raw, fmt)
                    break
                except Exception:
                    continue
        sent_at_ts = parsed_dt.timestamp() if parsed_dt else 0
        return (
            sent_at_ts,
            (item.get("last_name") or "").upper(),
            (item.get("first_name") or "").upper(),
        )

    items.sort(key=_scotia_sort_key, reverse=True)
    return items


def _find_session_trainee(data: Dict[str, Any], session_id: str, trainee_id: str):
    s = find_session(data, session_id)
    if not s:
        return None, None, None
    trainees = _session_trainees_list(s)
    t = next((x for x in trainees if str(x.get("id") or "") == str(trainee_id)), None)
    return s, trainees, t


def _scotia_comment_author_label(username: str) -> str:
    normalized = (username or "").strip().lower()
    if normalized in SCOTIA_COMMENT_AUTHOR_LABELS:
        return SCOTIA_COMMENT_AUTHOR_LABELS[normalized]
    return "Scotia"


def _scotia_comment_party_from_label(label: str) -> str:
    normalized = unicodedata.normalize("NFKD", (label or "").strip().lower())
    normalized = "".join(ch for ch in normalized if not unicodedata.combining(ch))
    if "integrale" in normalized or "academy" in normalized:
        return "integrale"
    return "scotia"


def _scotia_comment_party_label(party: str) -> str:
    return "Intégrale Academy" if party == "integrale" else "SCOTIA"


def _current_scotia_comment_author_label() -> str:
    if not has_request_context():
        return "Scotia"
    if session.get("admin_logged_in"):
        return "Intégrale Academy"
    return _scotia_comment_author_label(str(session.get("scotia_username") or ""))


def _current_scotia_comment_party() -> str:
    if not has_request_context():
        return "scotia"
    if session.get("admin_logged_in"):
        return "integrale"
    return _scotia_comment_party_from_label(_current_scotia_comment_author_label())


def _scotia_comment_can_mark_read(entry: Dict[str, Any]) -> bool:
    if entry.get("read_at"):
        return False
    if not has_request_context():
        return False
    if session.get("admin_logged_in"):
        return (
            str(entry.get("author_party") or "") != "integrale"
            or str(entry.get("source") or "") == "scotia_dashboard"
        )
    return str(entry.get("author_party") or "") != _current_scotia_comment_party()


def _format_scotia_comment_added_at(value: str) -> str:
    s = (value or "").strip()
    if not s:
        return ""
    normalized = s.replace("Z", "+00:00")
    try:
        dt = datetime.datetime.fromisoformat(normalized)
    except Exception:
        return history_datetime(s).replace(" ", " à ", 1)
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=datetime.timezone.utc)
    paris_dt = dt.astimezone(ZoneInfo("Europe/Paris"))
    return paris_dt.strftime("%d/%m/%Y à %Hh%M")


def _now_paris_label() -> str:
    return datetime.datetime.now(ZoneInfo("Europe/Paris")).strftime("%d/%m/%Y à %Hh%M")


def _mark_complementary_documents_to_control(t: Dict[str, Any]) -> None:
    t["scotia_complementary_documents_review_status"] = ""
    t["scotia_complementary_documents_reviewed_at"] = ""
    t["scotia_complementary_documents_reviewed_at_label"] = ""

def _scotia_legacy_comment_id(content: str, author_label: str, created_at: str) -> str:
    raw = f"{created_at}|{author_label}|{content}".encode("utf-8", errors="ignore")
    return hashlib.sha1(raw).hexdigest()[:16]


def _format_scotia_comment_read_at(value: str) -> str:
    s = (value or "").strip()
    if not s:
        return ""
    normalized = s.replace("Z", "+00:00")
    try:
        dt = datetime.datetime.fromisoformat(normalized)
    except Exception:
        return fr_date(s)
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=datetime.timezone.utc)
    paris_dt = dt.astimezone(ZoneInfo("Europe/Paris"))
    return paris_dt.strftime("%d/%m/%Y")


def _ensure_scotia_thread_comments_entry(t: Dict[str, Any]) -> List[Dict[str, Any]]:
    comments = t.get("scotia_thread_comments")
    if not isinstance(comments, list):
        comments = []
        t["scotia_thread_comments"] = comments
        return comments

    cleaned_comments: List[Dict[str, Any]] = []
    for entry in comments:
        if not isinstance(entry, dict):
            continue
        content = str(entry.get("content") or entry.get("comment") or "").strip()
        if not content:
            continue
        created_at = str(entry.get("created_at") or entry.get("at") or "").strip() or _now_iso()
        author_label = str(entry.get("author_label") or "").strip()
        if not author_label:
            author_label = _scotia_comment_author_label(str(entry.get("author_email") or entry.get("author") or ""))
        author_party = str(entry.get("author_party") or "").strip() or _scotia_comment_party_from_label(author_label)
        comment_id = str(entry.get("id") or "").strip() or _scotia_legacy_comment_id(content, author_label, created_at)
        cleaned_entry = {
            "id": comment_id,
            "content": content,
            "author_label": author_label,
            "author_party": author_party,
            "created_at": created_at,
        }
        source = str(entry.get("source") or "").strip()
        if source:
            cleaned_entry["source"] = source
        read_at = str(entry.get("read_at") or "").strip()
        if read_at:
            read_by_party = str(entry.get("read_by_party") or "").strip() or ("integrale" if author_party == "scotia" else "scotia")
            cleaned_entry.update({
                "read_at": read_at,
                "read_by_party": read_by_party,
                "read_by_label": str(entry.get("read_by_label") or "").strip() or _scotia_comment_party_label(read_by_party),
            })
        cleaned_comments.append(cleaned_entry)
    if len(cleaned_comments) != len(comments) or cleaned_comments != comments:
        t["scotia_thread_comments"] = cleaned_comments
    return t["scotia_thread_comments"]


def _scotia_thread_comments_for_display(t: Dict[str, Any]) -> List[Dict[str, Any]]:
    return [
        {
            **entry,
            "created_at_label": _format_scotia_comment_added_at(str(entry.get("created_at") or "")),
            "read_at_label": _format_scotia_comment_read_at(str(entry.get("read_at") or "")),
            "can_mark_read": _scotia_comment_can_mark_read(entry),
            "can_delete": has_request_context(),
        }
        for entry in _ensure_scotia_thread_comments_entry(t)
    ]


def _scotia_unread_thread_summary(t: Dict[str, Any]) -> Dict[str, Any]:
    current_party = _current_scotia_comment_party()
    unread = []
    for entry in _ensure_scotia_thread_comments_entry(t):
        if entry.get("read_at"):
            continue
        author_party = str(entry.get("author_party") or "")
        source = str(entry.get("source") or "")
        if author_party != current_party or (current_party == "integrale" and source == "scotia_dashboard"):
            unread.append(entry)
    if not unread:
        return {}
    author_party = str(unread[-1].get("author_party") or "scotia")
    count = len(unread)
    return {
        "count": count,
        "author_label": _scotia_comment_party_label(author_party),
        "label": f"{count} message{'s' if count > 1 else ''} {_scotia_comment_party_label(author_party)} à consulter",
    }


def _scotia_dossier_anchor(session_id: str, trainee_id: str) -> str:
    safe_session_id = quote(str(session_id or ""), safe="")
    safe_trainee_id = quote(str(trainee_id or ""), safe="")
    return f"dossier-{safe_session_id}-{safe_trainee_id}"


def _scotia_dossier_url(session_id: str, trainee_id: str) -> str:
    return f"{PUBLIC_BASE_URL.rstrip('/')}/scotia#{_scotia_dossier_anchor(session_id, trainee_id)}"


def _scotia_comment_notification_name(trainee: Dict[str, Any]) -> str:
    first_name = normalize_first_name(str(trainee.get("first_name") or "").strip())
    last_name = normalize_last_name(str(trainee.get("last_name") or "").strip())
    return " ".join(part for part in (last_name, first_name) if part).strip() or "ce candidat"


def _send_scotia_thread_comment_notification(
    session_obj: Dict[str, Any],
    trainee: Dict[str, Any],
    comment: str,
    *,
    session_id: str,
    trainee_id: str,
) -> bool:
    if not SCOTIA_NOTIFICATION_EMAIL:
        return False

    candidate_name = _scotia_comment_notification_name(trainee)
    dossier_url = _scotia_dossier_url(session_id, trainee_id)
