@app.post('/api/scotia/sessions/<session_id>/stagiaires/<trainee_id>/thread-comments')
@scotia_login_required
def api_scotia_thread_comment(session_id: str, trainee_id: str):
    data = load_data()
    s, trainees, t = _find_session_trainee(data, session_id, trainee_id)
    if not s or not t:
        return jsonify({"ok": False, "error": "trainee_not_found"}), 404

    payload = request.get_json(silent=True) or {}
    content = (payload.get('comment') or payload.get('content') or '').strip()
    if not content:
        return jsonify({"ok": False, "error": "empty_comment"}), 400
    if len(content) > 2000:
        return jsonify({"ok": False, "error": "comment_too_long"}), 400

    created_at = _now_iso()
    author_label = _current_scotia_comment_author_label()
    entry = _append_scotia_thread_comment(t, content, author_label, created_at, "scotia_dashboard")
    if (_session_get(s, "training_type", "") or "").strip().upper() == "DIRIGEANT VAE":
        _add_vae_live_notification(
            s,
            t,
            f"Commentaire {author_label}",
            actor="scotia",
            details=content,
            kind="scotia_thread_comment",
        )
    email_ok = _send_scotia_thread_comment_notification(
        s,
        t,
        content,
        session_id=session_id,
        trainee_id=trainee_id,
    )
    t['updated_at'] = created_at

    s['trainees'] = trainees
    s.pop('stagiaires', None)
    save_data(data)

    return jsonify({
        "ok": True,
        "comment": {
            **_json_scotia_thread_comment(entry),
        },
        "email_ok": email_ok,
    })


