def _notify_scotia_complementary_documents(t: Dict[str, Any], s: Dict[str, Any], file_count: int, source_label: str) -> bool:
    trainee_display_name = _format_trainee_name(t.get("first_name", ""), t.get("last_name", ""))
    session_name = _session_get(s, "name", "") or str(s.get("id") or "")
    today_fr = fr_date(datetime.datetime.utcnow().strftime("%Y-%m-%d"))
    comment = (t.get("scotia_comment") or "").strip()
    comment_html = f"<p><strong>Commentaire SCOTIA :</strong><br>{html.escape(comment).replace(chr(10), '<br>')}</p>" if comment else ""
    subject = "Documents complémentaires déposés (VAE)"
    html_body = mail_layout(f"""
    <h2 style="margin:0 0 12px 0;color:#0f172a;">📎 Documents complémentaires déposés</h2>
    <p>Des documents complémentaires viennent d'être déposés depuis {html.escape(source_label)}.</p>
    <p><strong>Stagiaire :</strong> {html.escape(trainee_display_name or "—")}</p>
    <p><strong>Email :</strong> {html.escape((t.get("email") or "").strip() or "—")}</p>
    <p><strong>Téléphone :</strong> {html.escape((t.get("phone") or "").strip() or "—")}</p>
    <p><strong>Session :</strong> {html.escape(session_name or "—")}</p>
    <p><strong>Nombre de fichier(s) :</strong> {file_count}</p>
    <p><strong>Date :</strong> {today_fr}</p>
    {comment_html}
    """)
    return brevo_send_email(
        "scotiaformation@gmail.com",
        subject,
        html_body,
        cc_emails=["clement@integraleacademy.com"],
        trainee=t,
    )


def _append_complementary_documents(session_id: str, trainee_id: str, t: Dict[str, Any], incoming_files: List[Any], storage_area: str) -> int:
    target = _ensure_complementary_documents_entry(t)
    accepted_exts = {".pdf", ".jpg", ".jpeg", ".png", ".webp"}
    files_to_store = [f for f in incoming_files if f and getattr(f, "filename", "")]
    if not files_to_store:
        return 0
    for f in files_to_store:
        if _safe_ext(f.filename) not in accepted_exts:
            return 0

    stored_count = 0
    for f in files_to_store:
        stored = _store_file(session_id, trainee_id, storage_area, f)
        token = _tokenize_path(stored)
        target.append(token)
        stored_count += 1

    t["scotia_complementary_documents"] = [x for x in target if x]
    if not isinstance(t.get("vae_action_dates"), dict):
        t["vae_action_dates"] = {}
    t["vae_action_dates"]["complementary_documents_received"] = _now_paris_label()
    _mark_complementary_documents_to_control(t)
    t["updated_at"] = _now_iso()
    return stored_count


def _ensure_scotia_added_documents_entry(t: Dict[str, Any]) -> List[Dict[str, Any]]:
    """Garantit les groupes de documents ajoutés manuellement depuis SCOTIA."""
    groups = t.get("scotia_added_documents")
    if not isinstance(groups, list):
        groups = []
        t["scotia_added_documents"] = groups

    cleaned_groups: List[Dict[str, Any]] = []
    changed = False
    for group in groups:
        if not isinstance(group, dict):
            changed = True
            continue
        date_label = (group.get("date") or "").strip()
        files = group.get("files") if isinstance(group.get("files"), list) else []
        tokens = [x.strip() for x in files if isinstance(x, str) and x.strip()]
        if not date_label or not tokens:
            changed = True
            continue
        cleaned_groups.append({"date": date_label, "files": tokens})
        if cleaned_groups[-1] != group:
            changed = True

    if changed or cleaned_groups != groups:
        t["scotia_added_documents"] = cleaned_groups
    return cleaned_groups


def _scotia_added_document_token_exists(t: Dict[str, Any], token: str) -> bool:
    token = (token or "").strip()
    if not token:
        return False
    for group in _ensure_scotia_added_documents_entry(t):
        files = group.get("files") if isinstance(group.get("files"), list) else []
        if token in [x for x in files if isinstance(x, str)]:
            return True
    return False


def _append_scotia_added_documents(session_id: str, trainee_id: str, t: Dict[str, Any], incoming_files: List[Any]) -> int:
    accepted_exts = {".pdf", ".jpg", ".jpeg", ".png", ".webp", ".doc", ".docx", ".zip"}
    files_to_store = [f for f in incoming_files if f and getattr(f, "filename", "")]
    if not files_to_store:
        return 0
    for f in files_to_store:
        if _safe_ext(f.filename) not in accepted_exts:
            return 0

    today_label = datetime.date.today().strftime("%d/%m/%Y")
    groups = _ensure_scotia_added_documents_entry(t)
    target_group = next((g for g in groups if (g.get("date") or "").strip() == today_label), None)
    if not target_group:
        target_group = {"date": today_label, "files": []}
        groups.insert(0, target_group)

    stored_count = 0
    for f in files_to_store:
        stored = _store_file(session_id, trainee_id, "scotia_added_documents", f)
        token = _tokenize_path(stored)
        target_group.setdefault("files", []).append(token)
        stored_count += 1

    t["scotia_added_documents"] = groups
    if (t.get("scotia_status") or "").strip() == "complement_requested":
        _mark_complementary_documents_to_control(t)
    t["updated_at"] = _now_iso()
    return stored_count


def _remove_scotia_added_document_token(t: Dict[str, Any], token: str) -> bool:
    token = (token or "").strip()
    if not token:
        return False

    groups = _ensure_scotia_added_documents_entry(t)
    removed = False
    kept_groups: List[Dict[str, Any]] = []
    for group in groups:
        files = group.get("files") if isinstance(group.get("files"), list) else []
        filtered_files = [x for x in files if not (isinstance(x, str) and x == token)]
        if len(filtered_files) != len(files):
            removed = True
        if filtered_files:
            kept_groups.append({"date": (group.get("date") or "").strip(), "files": filtered_files})

    if removed:
        t["scotia_added_documents"] = kept_groups
        t["updated_at"] = _now_iso()
    return removed


def _remove_complementary_document_token(t: Dict[str, Any], token: str) -> bool:
    """Retire un document complémentaire des listes SCOTIA et historiques."""
    token = (token or "").strip()
    if not token:
        return False

    removed = False

    scotia_tokens = t.get("scotia_complementary_documents")
    if isinstance(scotia_tokens, list):
        filtered_scotia_tokens = [x for x in scotia_tokens if not (isinstance(x, str) and x == token)]
        if len(filtered_scotia_tokens) != len(scotia_tokens):
            t["scotia_complementary_documents"] = filtered_scotia_tokens
            removed = True

    docs = t.get("documents") if isinstance(t.get("documents"), list) else []
    for doc in docs:
        if not isinstance(doc, dict) or doc.get("key") != "complementary_documents":
            continue

        files = doc.get("files") if isinstance(doc.get("files"), list) else []
        filtered_files = [x for x in files if not (isinstance(x, str) and x == token)]
        if len(filtered_files) != len(files):
            doc["files"] = filtered_files
            removed = True

        if (doc.get("file") or "").strip() == token:
            doc["file"] = filtered_files[0] if filtered_files else ""
            removed = True

        if removed and not filtered_files and not (doc.get("file") or "").strip():
            doc["status"] = "NON DÉPOSÉ"

    if removed:
        remaining = []
        scotia_remaining = t.get("scotia_complementary_documents")
        if isinstance(scotia_remaining, list):
            remaining.extend([x for x in scotia_remaining if isinstance(x, str) and x.strip()])
        for doc in docs:
            if isinstance(doc, dict) and doc.get("key") == "complementary_documents":
                doc_files = doc.get("files") if isinstance(doc.get("files"), list) else []
                remaining.extend([x for x in doc_files if isinstance(x, str) and x.strip()])
                doc_file = (doc.get("file") or "").strip()
                if doc_file:
                    remaining.append(doc_file)
        if not remaining:
            _mark_complementary_documents_to_control(t)
            if isinstance(t.get("vae_action_dates"), dict):
                t["vae_action_dates"].pop("complementary_documents_received", None)
        t["updated_at"] = _now_iso()

    return removed


@app.post('/scotia/sessions/<session_id>/stagiaires/<trainee_id>/complements/upload')
@scotia_login_required
def scotia_upload_complementary_documents(session_id: str, trainee_id: str):
    data = load_data()
    s, trainees, t = _find_session_trainee(data, session_id, trainee_id)
    if not s or not t:
        abort(404)

    if (t.get("scotia_status") or "").strip() != "complement_requested":
        return redirect(url_for('scotia_dashboard'))

    files = request.files.getlist('files') or request.files.getlist('file')
    try:
        stored_count = _append_complementary_documents(session_id, trainee_id, t, files, 'public_documents')
    except Exception:
        stored_count = 0
    if stored_count:
        s['trainees'] = trainees
        s.pop('stagiaires', None)
        save_data(data)
        _notify_scotia_complementary_documents(t, s, stored_count, "l'espace SCOTIA")
    return redirect(url_for('scotia_dashboard'))


