@app.get('/scotia/vae/<dossier_id>/justificatifs/<doc_id>')
@scotia_login_required
def scotia_vae_justificatif_download(dossier_id: str, doc_id: str):
    data = _vae_load_all()
    dossier = _vae_find_dossier(data, dossier_id)
    if not dossier:
        abort(404)

    justificatifs = dossier.get('justificatifs_experience') if isinstance(dossier.get('justificatifs_experience'), list) else []
    entry = next((x for x in justificatifs if str((x or {}).get('id') or '') == str(doc_id)), None)
    if not entry:
        abort(404)

    token = str((entry or {}).get('token') or '').strip()
    if not token:
        abort(404)
    fp = _detokenize_path(token)
    if not os.path.exists(fp):
        abort(404)
    return send_file(fp, as_attachment=False)


@app.get("/admin/sessions")
@admin_login_required
def admin_sessions():
    data = load_data()
    wedof_new_requests_count = sum(1 for item in _load_wedof_webhooks() if not bool(item.get("processed")))
    out_sessions = []
    current_year = datetime.date.today().year
    dashboard_start = datetime.date(current_year, 1, 1)
    dashboard_end = datetime.date(current_year, 12, 31)
    yearly_training_counts = {
        "APS": 0,
        "VTC": 0,
        "DIRIGEANT": 0,
        "VAE": 0,
        "A3P": 0,
        "SSIAP": 0,
    }

    def _parse_iso_date(raw_value: Any) -> Optional[datetime.date]:
        raw = (raw_value or "").strip()
        if not raw:
            return None
        try:
            return datetime.datetime.strptime(raw[:10], "%Y-%m-%d").date()
        except (ValueError, TypeError):
            return None

    def _dashboard_training_label(training_type: str) -> Optional[str]:
        raw = (training_type or "").strip().upper()
        if raw.startswith("APS"):
            return "APS"
        if raw.startswith("A3P"):
            return "A3P"
        if raw.startswith("SSIAP"):
            return "SSIAP"
        if "VTC" in raw:
            return "VTC"
        if raw.startswith("DIRIGEANT") and "VAE" in raw:
            return "VAE"
        if raw.startswith("DIRIGEANT"):
            return "DIRIGEANT"
        if "VAE" in raw:
            return "VAE"
        return None

    for s in data.get("sessions", []):
        if _is_wedof_leads_session(s):
            continue

        session_start = _parse_iso_date(_session_get(s, "date_start", ""))
        dashboard_label = _dashboard_training_label(_session_get(s, "training_type", ""))
        if dashboard_label:
            trainees_for_dashboard = _session_trainees_list(s)
            for trainee in trainees_for_dashboard:
                trainee_created_at = _parse_iso_date(trainee.get("created_at"))
                in_dashboard_year = False
                if trainee_created_at:
                    in_dashboard_year = dashboard_start <= trainee_created_at <= dashboard_end
                elif session_start:
                    in_dashboard_year = dashboard_start <= session_start <= dashboard_end

                if not in_dashboard_year:
                    continue

                if dashboard_label == "VAE":
                    vae_status_key = (trainee.get("vae_status") or "").strip().lower()
                    vae_status_label = (trainee.get("vae_status_label") or "").strip().lower()
                    if vae_status_key == "certified" or "certification obtenue" in vae_status_label:
                        yearly_training_counts[dashboard_label] += 1
                else:
                    yearly_training_counts[dashboard_label] += 1

        if bool(s.get("archived")):
            continue

        trainees = _session_trainees_list(s)
        st = compute_stats(s)

        # ✅ docs fin de formation : nb de stagiaires COMPLETS / nb stagiaires
        done_total = 0
        for t in trainees:
            _, _, ok = deliverables_progress(t)
            if ok:
                done_total += 1

        public_logged_in_total = sum(
            1 for t in trainees if bool(t.get("public_has_logged_in"))
        )
        # Le compteur "Inscriptions CMAR" doit suivre l'état affiché dans la colonne
        # "Inscription CMAR" de la liste stagiaires VTC (basé sur exam_fees_paid).
        cmar_registered_total = sum(
            1 for t in trainees if bool(t.get("exam_fees_paid"))
        )
        cash_payment_total = 0.0
        cash_payment_trainees = 0
        cash_payment_items = []
        for t in trainees:
            if not t.get("cash_payment_enabled"):
                continue
            if bool(t.get("cash_payment_settled")):
                continue
            try:
                trainee_cash_amount = float(str(t.get("cash_payment_amount") or "").replace(",", ".").strip() or "0")
            except (TypeError, ValueError):
                trainee_cash_amount = 0.0
            if trainee_cash_amount <= 0:
                continue
            cash_payment_trainees += 1
            cash_payment_items.append({
                "trainee_id": t.get("id"),
                "trainee_name": _format_trainee_name(t.get("first_name", ""), t.get("last_name", "")),
                "amount": round(trainee_cash_amount, 2),
            })
            cash_payment_total += trainee_cash_amount
        cash_payment_alert_key = f"{cash_payment_trainees}:{round(cash_payment_total, 2):.2f}"
        show_cash_payment_alert = (
            cash_payment_trainees > 0
            and cash_payment_total > 0
        )

        total_total = len(trainees)
        dossier_complete_total = 0
        for t in trainees:
            if dossier_is_complete_total(t, _session_get(s, "training_type", ""), _session_get(s, "date_start", "")):
                dossier_complete_total += 1
        session_dossier_complete = (total_total > 0 and dossier_complete_total == total_total)

        jury_entries = _session_jury_entries(s)
        jury_notified = bool(s.get("juries_notified_at") or s.get("jury_notified_at"))
        jury_counts = {"pending": 0, "present": 0, "absent": 0}
        for jury in jury_entries:
            status_raw = jury.get("status") or jury.get("state") or jury.get("response")
            status_key = _normalize_jury_status(status_raw)
            if status_key:
                jury_counts[status_key] += 1
                jury_notified = True
            if jury.get("notified_at") or jury.get("notified"):
                jury_notified = True

        date_start_raw = _session_get(s, "date_start", "")
        date_end_raw = _session_get(s, "date_end", "")
        today = datetime.date.today()
        status_key = "upcoming"
        try:
            dt_start = datetime.datetime.strptime(date_start_raw[:10], "%Y-%m-%d").date()
        except (ValueError, TypeError):
            dt_start = None
        try:
            dt_end = datetime.datetime.strptime(date_end_raw[:10], "%Y-%m-%d").date()
        except (ValueError, TypeError):
            dt_end = None

        if dt_end and dt_end < today:
            status_key = "ended"
        elif dt_start and dt_start <= today:
            status_key = "ongoing"

        status_label = {
            "ongoing": "Formation en cours",
            "upcoming": "Prochainement",
            "ended": "Terminée",
        }[status_key]

        training_type_raw = (_session_get(s, "training_type", "") or "").strip().upper()
        if training_type_raw.startswith("APS"):
            _sync_aps_period_dates(s)
            training_type_class = "aps"
        elif training_type_raw.startswith("A3P"):
            training_type_class = "a3p"
        elif training_type_raw.startswith("SSIAP"):
            training_type_class = "ssiap"
        elif "VTC" in training_type_raw:
            training_type_class = "vtc"
        elif training_type_raw.startswith("DIRIGEANT"):
            training_type_class = "dirigeant"
        else:
            training_type_class = "other"

        out_sessions.append({
            "id": s.get("id"),
            "name": _session_get(s, "name", ""),
            "training_type": _session_get(s, "training_type", ""),
            "date_start": _session_get(s, "date_start", ""),
            "date_end": _session_get(s, "date_end", ""),
            "exam_date": _session_get(s, "exam_date", ""),
            "exam_theory_date": _session_get(s, "exam_theory_date", ""),
            "exam_practice_date": _session_get(s, "exam_practice_date", ""),
            "practice_training_date": _session_get(s, "practice_training_date", ""),
            "aps_remote_start": _session_get(s, "aps_remote_start", ""),
            "aps_remote_end": _session_get(s, "aps_remote_end", ""),
            "aps_in_person_start": _session_get(s, "aps_in_person_start", ""),
            "aps_in_person_end": _session_get(s, "aps_in_person_end", ""),
            "total": st["total"],
            "session_is_conform": st["session_is_conform"],
            "session_dossier_complete": session_dossier_complete,

            # ✅ new
            "deliverables_done": done_total,
            "deliverables_total": total_total,
            "public_logged_in_total": public_logged_in_total,
            "cmar_registered_total": cmar_registered_total,
            "cash_payment_total": round(cash_payment_total, 2),
            "cash_payment_trainees": cash_payment_trainees,
            "cash_payment_items": cash_payment_items,
            "show_cash_payment_alert": show_cash_payment_alert,
            "cash_payment_alert_key": cash_payment_alert_key,
            "status_label": status_label,
            "status_key": status_key,
            "training_type_class": training_type_class,
            "jury_notified": jury_notified,
            "jury_pending": jury_counts["pending"],
            "jury_present": jury_counts["present"],
            "jury_absent": jury_counts["absent"],
            "aps_elearning_enabled": bool(s.get("aps_elearning_enabled")),
            "exclude_from_sales_tracking": bool(s.get("exclude_from_sales_tracking")),
        })

    response = make_response(render_template(
        "admin_sessions.html",
        sessions=out_sessions,
        formation_types=FORMATION_TYPES,
        dashboard_year=current_year,
        yearly_training_counts=yearly_training_counts,
        wedof_new_requests_count=wedof_new_requests_count,
    ))
    response.headers["Cache-Control"] = "no-store, no-cache, must-revalidate, max-age=0"
    response.headers["Pragma"] = "no-cache"
    return response


