SALES_TRACKING_MONTH_LABELS = [
    "Janvier",
    "Février",
    "Mars",
    "Avril",
    "Mai",
    "Juin",
    "Juillet",
    "Août",
    "Septembre",
    "Octobre",
    "Novembre",
    "Décembre",
]


def _sales_tracking_bucket(data: Dict[str, Any]) -> Dict[str, Any]:
    bucket = data.setdefault("sales_tracking", {})
    if not isinstance(bucket, dict):
        bucket = {}
        data["sales_tracking"] = bucket
    objectives = bucket.setdefault("objectives", {})
    if not isinstance(objectives, dict):
        bucket["objectives"] = {}
    return bucket


def _sales_training_label(training_type: str) -> str:
    raw = (training_type or "").strip().upper()
    if raw.startswith("APS"):
        return "APS"
    if raw.startswith("A3P"):
        return "A3P"
    if "VTC" in raw:
        return "VTC"
    if raw.startswith("DIRIGEANT") and "INITIAL" in raw:
        return "DIRIGEANT INITIAL"
    if raw.startswith("DIRIGEANT") and "VAE" in raw:
        return "DIRIGEANT VAE"
    if raw.startswith("DIRIGEANT"):
        return "DIRIGEANT"
    return (training_type or "AUTRE").strip() or "AUTRE"


def _parse_positive_int(raw_value: Any) -> int:
    text = str(raw_value or "").strip()
    if not text:
        return 0
    cleaned = re.sub(r"[^\d]", "", text)
    if not cleaned:
        return 0
    try:
        parsed = int(cleaned)
    except (ValueError, TypeError):
        return 0
    return max(parsed, 0)


def _parse_flexible_date(raw_value: Any) -> Optional[datetime.date]:
    raw = str(raw_value or "").strip()
    if not raw:
        return None
    parsed_dt = _parse_iso_datetime(raw)
    if parsed_dt:
        return parsed_dt.date()
    for fmt in ("%d/%m/%Y", "%d-%m-%Y", "%Y-%m-%d"):
        try:
            return datetime.datetime.strptime(raw[:10], fmt).date()
        except (ValueError, TypeError):
            continue
    return None


def _sales_training_unit_price(training_type: str, training_label: str) -> int:
    label_key = (training_label or "").strip().upper()
    type_key = (training_type or "").strip().upper()
    price_map = {
        "APS": 1650,
        "A3P": 4200,
        "DIRIGEANT INITIAL": 4300,
        "DIRIGEANT": 4300,
        "DIRIGEANT VAE": 3800,
        "VTC": 1500,
        "CHAUFFEUR VTC": 1500,
    }
    if label_key in price_map:
        return price_map[label_key]
    if type_key in price_map:
        return price_map[type_key]
    return default_training_price(training_type) or 0


def _sales_trainee_display_name(trainee: Dict[str, Any]) -> str:
    first_name = str(
        trainee.get("first_name")
        or trainee.get("prenom")
        or ""
    ).strip()
    last_name = str(
        trainee.get("last_name")
        or trainee.get("nom")
        or ""
    ).strip()
    display_name = _format_trainee_name(first_name, last_name)
    if display_name:
        return display_name

    fallback_name = str(trainee.get("name") or "").strip()
    if fallback_name:
        return fallback_name
    return "Stagiaire"


def _sales_trainee_item(trainee: Dict[str, Any], session_id: str) -> Dict[str, str]:
    trainee_id = str(trainee.get("id") or "").strip()
    trainee_url = ""
    if session_id and trainee_id:
        trainee_url = url_for("admin_trainee_page", session_id=session_id, trainee_id=trainee_id)
    return {
        "name": _sales_trainee_display_name(trainee),
        "url": trainee_url,
    }


def _build_sales_tracking_metrics(data: Dict[str, Any], selected_year: int) -> Dict[str, Any]:
    today = datetime.date.today()
    yesterday = today - datetime.timedelta(days=1)
    week_start = today - datetime.timedelta(days=today.weekday())

    monthly_rows: List[Dict[str, Any]] = []
    for month_index, month_name in enumerate(SALES_TRACKING_MONTH_LABELS, start=1):
        monthly_rows.append({
            "month_index": month_index,
            "month_name": month_name,
            "inscriptions": 0,
            "revenue": 0,
            "trainings": {},
            "objective": 0,
        })

    today_revenue = 0
    today_inscriptions = 0
    yesterday_revenue = 0
    yesterday_inscriptions = 0
    week_revenue = 0
    week_inscriptions = 0
    today_sales_names: List[Dict[str, str]] = []
    yesterday_sales_names: List[Dict[str, str]] = []
    week_sales_names: List[Dict[str, str]] = []
    sale_markers: List[str] = []
    annual_trainings_map: Dict[str, Dict[str, Any]] = {}

    for session in data.get("sessions", []):
        if bool(session.get("exclude_from_sales_tracking")):
            continue
        if _is_wedof_leads_session(session):
            continue
        session_id = str(session.get("id") or "")
        training_type_raw = _session_get(session, "training_type", "")
        trainees = _session_trainees_list(session)
        training_label = _sales_training_label(training_type_raw)
        unit_price = _sales_training_unit_price(training_type_raw, training_label)

        for trainee in trainees:
            if bool(trainee.get("exclude_from_sales_tracking")):
                continue
            anchor_date = _parse_flexible_date(trainee.get("created_at") or "")
            if training_label == "DIRIGEANT VAE":
                vae_status_key = vae_status_view(trainee.get("vae_status") or trainee.get("vae_status_label"))["key"]
                if vae_status_key != "certified":
                    continue
                action_dates = trainee.get("vae_action_dates") if isinstance(trainee.get("vae_action_dates"), dict) else {}
                anchor_date = _parse_flexible_date(action_dates.get("diplome_obtenu"))
                if not anchor_date:
                    continue

            if not anchor_date:
                continue

            adjusted_tracking_price = _parse_positive_int(trainee.get("sales_tracking_amount"))
            if adjusted_tracking_price > 0:
                training_price = adjusted_tracking_price
            else:
                training_price = unit_price if unit_price > 0 else _parse_positive_int(trainee.get("training_price"))
            trainee_ref = str(trainee.get("id") or trainee.get("email") or trainee.get("nom") or trainee.get("name") or "")
            sale_markers.append(f"{session_id}|{trainee_ref}|{anchor_date.isoformat()}|{training_price}")
            trainee_item = _sales_trainee_item(trainee, session_id)

            if anchor_date == today:
                today_revenue += training_price
                today_inscriptions += 1
                today_sales_names.append(trainee_item)
            if anchor_date == yesterday:
                yesterday_revenue += training_price
                yesterday_inscriptions += 1
                yesterday_sales_names.append(trainee_item)
            if week_start <= anchor_date <= today:
                week_revenue += training_price
                week_inscriptions += 1
                week_sales_names.append(trainee_item)

            if anchor_date.year != selected_year:
                continue

            month_index = anchor_date.month
            if month_index < 1 or month_index > 12:
                continue

            month_row = monthly_rows[month_index - 1]
            month_row["inscriptions"] += 1
            month_row["revenue"] += training_price

            training_metrics = month_row["trainings"].setdefault(training_label, {
                "label": training_label,
                "inscriptions": 0,
                "training_price": training_price,
                "revenue": 0,
                "trainees": [],
            })
            training_metrics["inscriptions"] += 1
            training_metrics["revenue"] += training_price
            training_metrics.setdefault("trainees", []).append(trainee_item)
            if training_metrics.get("training_price", 0) <= 0 and training_price > 0:
                training_metrics["training_price"] = training_price

            annual_training_metrics = annual_trainings_map.setdefault(training_label, {
                "label": training_label,
                "inscriptions": 0,
                "training_price": training_price,
                "revenue": 0,
                "trainees": [],
            })
            annual_training_metrics["inscriptions"] += 1
            annual_training_metrics["revenue"] += training_price
            annual_training_metrics.setdefault("trainees", []).append(trainee_item)
            if annual_training_metrics.get("training_price", 0) <= 0 and training_price > 0:
                annual_training_metrics["training_price"] = training_price

    objectives = data.get("sales_tracking", {}).get("objectives", {})
    year_objectives = objectives.get(str(selected_year), {}) if isinstance(objectives, dict) else {}
    annual_objective = _parse_positive_int(year_objectives.get("annual") if isinstance(year_objectives, dict) else 0)
    monthly_objectives = year_objectives.get("months", {}) if isinstance(year_objectives, dict) else {}
    if not isinstance(monthly_objectives, dict):
        monthly_objectives = {}

    for month_row in monthly_rows:
        month_row["objective"] = _parse_positive_int(monthly_objectives.get(str(month_row["month_index"])))
        month_row["trainings"] = sorted(
            month_row["trainings"].values(),
            key=lambda row: row["revenue"],
            reverse=True,
        )
        objective_value = month_row["objective"]
        month_row["progress_ratio"] = (month_row["revenue"] / objective_value) if objective_value > 0 else 0

    annual_revenue = sum(month["revenue"] for month in monthly_rows)
    annual_inscriptions = sum(month["inscriptions"] for month in monthly_rows)
    annual_progress_ratio = (annual_revenue / annual_objective) if annual_objective > 0 else 0
    annual_trainings = sorted(
        annual_trainings_map.values(),
        key=lambda row: row["revenue"],
        reverse=True,
    )
    for training_row in annual_trainings:
        revenue_value = float(training_row.get("revenue") or 0)
        training_row["revenue_ratio"] = (revenue_value / annual_revenue) if annual_revenue > 0 else 0

    return {
        "selected_year": selected_year,
        "annual_objective": annual_objective,
        "annual_revenue": annual_revenue,
        "annual_inscriptions": annual_inscriptions,
        "annual_progress_ratio": annual_progress_ratio,
        "annual_trainings": annual_trainings,
        "monthly_rows": monthly_rows,
        "today_revenue": today_revenue,
        "today_inscriptions": today_inscriptions,
        "today_sales_names": today_sales_names,
        "yesterday_revenue": yesterday_revenue,
        "yesterday_inscriptions": yesterday_inscriptions,
        "yesterday_sales_names": yesterday_sales_names,
        "week_revenue": week_revenue,
        "week_inscriptions": week_inscriptions,
        "week_sales_names": week_sales_names,
        "today_iso": today.isoformat(),
        "yesterday_iso": yesterday.isoformat(),
        "week_start_iso": week_start.isoformat(),
        "sales_count": len(sale_markers),
        "sales_signature": "|".join(sorted(sale_markers)),
    }


