def _afc_bucket(data: Dict[str, Any]) -> Dict[str, Any]:
    bucket = data.setdefault("afc", {})
    if not isinstance(bucket.get("candidates"), list):
        bucket["candidates"] = []
    for candidate in bucket["candidates"]:
        if isinstance(candidate, dict):
            candidate.setdefault("presence_afc", False)
            candidate.setdefault("date_icop", "")
    if not isinstance(bucket.get("mail_templates"), dict):
        bucket["mail_templates"] = {}
    mt = bucket["mail_templates"]
    if not (mt.get("retained") or "").strip():
        mt["retained"] = AFC_DEFAULT_MAIL_TEMPLATE_RETAINED
    if not (mt.get("rejected") or "").strip():
        mt["rejected"] = AFC_DEFAULT_MAIL_TEMPLATE_REJECTED
    if not (mt.get("convocation_subject") or "").strip():
        mt["convocation_subject"] = AFC_DEFAULT_CONVOCATION_EMAIL_SUBJECT
    if not (mt.get("convocation_email") or "").strip():
        mt["convocation_email"] = AFC_DEFAULT_CONVOCATION_EMAIL_TEMPLATE
    if not (mt.get("convocation_sms") or "").strip():
        mt["convocation_sms"] = AFC_DEFAULT_CONVOCATION_SMS_TEMPLATE
    if not isinstance(bucket.get("modules"), dict):
        bucket["modules"] = {}
    modules = bucket["modules"]
    for key in ("formation_technique", "remise_niveau", "soutien_personnalise", "paf"):
        modules.setdefault(key, 0)
    bucket.setdefault("dates_formation", "")
    bucket.setdefault("export_title", "Export Gestion AFC")

    changed = False
    for candidate in bucket["candidates"]:
        if "presence_afc_status" not in candidate:
            if bool(candidate.get("presence_afc")):
                candidate["presence_afc_status"] = "PRESENT"
            else:
                candidate["presence_afc_status"] = "A_CONVOQUER"
            changed = True
        status = str(candidate.get("presence_afc_status") or "").strip().upper()
        if status not in AFC_PRESENCE_STATUS_OPTIONS:
            candidate["presence_afc_status"] = "A_CONVOQUER"
            changed = True
    if changed:
        save_data(data)
    return bucket


def _afc_render_mail_template(template: str, candidate: Dict[str, Any]) -> str:
    values = {
        "nom": (candidate.get("nom") or "").strip(),
        "prenom": (candidate.get("prenom") or "").strip(),
        "motif_refus": (candidate.get("motif_refus") or "").strip(),
        "complement_refus": (
            (candidate.get("complement_refus_autre") or "").strip()
            if (candidate.get("complement_refus") or "").strip().lower() == "autre"
            else (candidate.get("complement_refus") or "").strip()
        ),
    }
    content = str(template or "")
    for key, value in values.items():
        content = content.replace("{{" + key + "}}", value)
    return content


def _afc_find_latest_positioning_score(candidate: Dict[str, Any], positioning_tests: List[Dict[str, Any]]) -> Optional[float]:
    candidate_email = str(candidate.get("email") or "").strip().lower()
    candidate_last_name = normalize_last_name(candidate.get("nom") or "")
    candidate_first_name = normalize_first_name(candidate.get("prenom") or "")

    matches: List[Dict[str, Any]] = []
    for entry in positioning_tests:
        contact = entry.get("contact") or {}
        email = str(contact.get("email") or "").strip().lower()
        last_name = normalize_last_name(contact.get("last_name") or "")
        first_name = normalize_first_name(contact.get("first_name") or "")

        email_match = bool(candidate_email and email and email == candidate_email)
        name_match = bool(
            candidate_last_name
            and candidate_first_name
            and last_name == candidate_last_name
            and first_name == candidate_first_name
        )
        if email_match or name_match:
            matches.append(entry)

    if not matches:
        return None

    matches.sort(key=lambda e: str(e.get("created_at") or ""), reverse=True)
    latest = matches[0]
    try:
        return float(latest.get("score_over_20") or 0)
    except (ValueError, TypeError):
        return None


@app.get("/admin/afc")
def admin_afc():
    data = load_data()
    bucket = _afc_bucket(data)
    candidates = bucket.get("candidates", [])
    positioning_tests = list(data.get("positioning_tests") or [])
    changed = False
    for candidate in candidates:
        candidate.setdefault("cnaps_priority", False)
        if candidate.get("cnaps_priority"):
            candidate["cnaps_status"] = "ACCEPTE"
            candidate["decision"] = "RETENU"
            candidate["motif_refus"] = ""
            candidate["complement_refus"] = ""
            candidate["complement_refus_autre"] = ""
        if not (candidate.get("cnaps_status") or "").strip():
            cnaps_status = fetch_cnaps_status_by_name(candidate.get("nom") or "", candidate.get("prenom") or "")
            if cnaps_status:
                candidate["cnaps_status"] = cnaps_status
                changed = True
        if candidate.get("cnaps_priority") and (candidate.get("cnaps_status") or "").strip().upper() != "ACCEPTE":
            candidate["cnaps_status"] = "ACCEPTE"
            changed = True
        candidate["has_positioning_test"] = _afc_find_latest_positioning_score(candidate, positioning_tests) is not None
    if changed:
        save_data(data)
    prioritized = [c for c in candidates if c.get("cnaps_priority")]
    non_prioritized = [c for c in candidates if not c.get("cnaps_priority")]
    retained = [c for c in non_prioritized if (c.get("decision") or "").strip().upper() == "RETENU"]
    others = [c for c in non_prioritized if (c.get("decision") or "").strip().upper() != "RETENU"]
    ordered_candidates = prioritized + retained + others
    return render_template(
        "admin_afc.html",
        afc=bucket,
        candidates=ordered_candidates,
        afc_presence_status_labels=AFC_PRESENCE_STATUS_LABELS,
        refusal_reasons=AFC_REFUSAL_REASONS,
        refusal_complements=AFC_REFUSAL_COMPLEMENTS,
    )


