@app.patch("/api/admin/afc/candidates/<candidate_id>")
def api_admin_afc_update_candidate(candidate_id: str):
    data = load_data()
    bucket = _afc_bucket(data)
    candidate = next((c for c in bucket["candidates"] if str(c.get("id") or "") == candidate_id), None)
    if not candidate:
        return jsonify({"ok": False, "error": "Candidat introuvable"}), 404

    payload = request.get_json(silent=True) or {}
    for field in (
        "identifiant_ft", "nom", "prenom", "email", "telephone", "decision",
        "motif_refus", "complement_refus", "complement_refus_autre", "dates_formation",
        "cnaps_status", "notification_status", "test_results_comment",
        "date_icop",
    ):
        if field in payload:
            value = str(payload.get(field) or "").strip()
            if field in {"cnaps_status", "decision", "notification_status"}:
                value = value.upper()
            candidate[field] = value

    if "decision" in payload and (candidate.get("decision") or "").strip().upper() == "RETENU":
        candidate["motif_refus"] = ""
        candidate["complement_refus"] = ""
        candidate["complement_refus_autre"] = ""

    if any(k in payload for k in ("nom", "prenom")) and not candidate.get("cnaps_priority"):
        cnaps_status = fetch_cnaps_status_by_name(candidate.get("nom") or "", candidate.get("prenom") or "")
        if cnaps_status:
            candidate["cnaps_status"] = cnaps_status

    modules = candidate.setdefault("modules", {})
    if isinstance(payload.get("modules"), dict):
        for key in ("formation_technique", "remise_niveau", "soutien_personnalise", "paf"):
            raw = payload["modules"].get(key, modules.get(key, 0))
            try:
                modules[key] = float(raw or 0)
            except (ValueError, TypeError):
                modules[key] = 0

    if "test_francais_reussi" in payload:
        candidate["test_francais_reussi"] = bool(payload.get("test_francais_reussi"))

    if "cnaps_priority" in payload:
        candidate["cnaps_priority"] = bool(payload.get("cnaps_priority"))
        if candidate["cnaps_priority"]:
            candidate["cnaps_status"] = "ACCEPTE"
            candidate["decision"] = "RETENU"
            candidate["motif_refus"] = ""
            candidate["complement_refus"] = ""
            candidate["complement_refus_autre"] = ""

    if "presence_afc" in payload:
        candidate["presence_afc"] = bool(payload.get("presence_afc"))

    if "presence_afc_status" in payload:
        old_status = str(candidate.get("presence_afc_status") or "").strip().upper()
        new_status = str(payload.get("presence_afc_status") or "").strip().upper()
        if new_status not in AFC_PRESENCE_STATUS_OPTIONS:
            return jsonify({"ok": False, "error": "Statut présence AFC invalide"}), 400
        candidate["presence_afc_status"] = new_status
        candidate["presence_afc"] = new_status == "PRESENT"
        if new_status == "ABSENT":
            candidate["decision"] = "NON RETENU"
            candidate["test_francais_reussi"] = False
            candidate["motif_refus"] = AFC_ABSENCE_REFUSAL_REASON
            candidate["complement_refus"] = ""
            candidate["complement_refus_autre"] = ""
            if (candidate.get("notification_status") or "").strip().upper() != "ENVOYEE":
                _send_afc_candidate_notification(bucket, candidate)
        if old_status != "CONVOQUE" and new_status == "CONVOQUE":
            ok, result = _send_afc_convocation_notification(bucket, candidate)
            if not ok:
                return jsonify({"ok": False, "error": result}), 500

    save_data(data)
    return jsonify({"ok": True, "candidate": candidate})


