SSIAP_DIPLOMA_TEMPLATE = os.path.join(
    os.path.dirname(os.path.abspath(__file__)),
    "templates",
    "static",
    "diplomes1.jpg",
)
SSIAP_DIPLOMA_LOCK_FILE = os.path.join(PERSIST_DIR, "ssiap_diplomas.lock")
SSIAP_DIPLOMA_NUMBER_RE = re.compile(r"^083-8323-1-(\d{4})-(\d{5})$")
SSIAP_BIRTH_DEPARTMENT_CACHE: Dict[str, str] = {}


def _normalize_department_code(value: Any) -> str:
    raw = str(value or "").strip().upper()
    if not raw:
        return ""
    parenthesized = re.search(r"\(([0-9]{2,3}|2A|2B)\)", raw)
    if parenthesized:
        return parenthesized.group(1)
    exact = re.fullmatch(r"(?:D[ÉE]PARTEMENT\s*)?([0-9]{2,3}|2A|2B)", raw)
    if exact:
        return exact.group(1)
    embedded = re.search(r"(?:^|[^0-9A-Z])(2A|2B|[0-9]{2,3})(?:$|[^0-9A-Z])", raw)
    if embedded:
        return embedded.group(1)
    postal_code = re.fullmatch(r"(?:F-)?([0-9]{5})", raw)
    if postal_code:
        code = postal_code.group(1)
        if code.startswith(("97", "98")):
            return code[:3]
        if not code.startswith("20"):
            return code[:2]
    return ""


def _normalized_commune_name(value: Any) -> str:
    normalized = unicodedata.normalize("NFKD", str(value or ""))
    normalized = "".join(char for char in normalized if not unicodedata.combining(char))
    return re.sub(r"[^A-Z0-9]+", " ", normalized.upper()).strip()


def _lookup_birth_department_code(birth_city: str) -> str:
    city = re.sub(r"\s*\(([0-9]{2,3}|2A|2B)\)\s*$", "", str(birth_city or "").strip(), flags=re.IGNORECASE)
    cache_key = _normalized_commune_name(city)
    if not cache_key:
        return ""
    if cache_key in SSIAP_BIRTH_DEPARTMENT_CACHE:
        return SSIAP_BIRTH_DEPARTMENT_CACHE[cache_key]

    department_code = ""
    try:
        response = requests.get(
            "https://geo.api.gouv.fr/communes",
            params={
                "nom": city,
                "fields": "nom,codeDepartement,codesPostaux",
                "boost": "population",
            },
            timeout=3,
        )
        response.raise_for_status()
        communes = response.json()
        if isinstance(communes, list):
            exact_matches = [
                commune for commune in communes
                if isinstance(commune, dict)
                and _normalized_commune_name(commune.get("nom")) == cache_key
            ]
            candidates = exact_matches or [commune for commune in communes if isinstance(commune, dict)]
            if candidates:
                department_code = _normalize_department_code(candidates[0].get("codeDepartement"))
    except (requests.RequestException, ValueError, TypeError):
        department_code = ""

    if department_code:
        SSIAP_BIRTH_DEPARTMENT_CACHE[cache_key] = department_code
    return department_code


def _ssiap_birth_place_label(trainee: Dict[str, Any]) -> str:
    birth_city = str(
        trainee.get("ssiap_diploma_birth_city")
        or trainee.get("birth_city")
        or trainee.get("birth_place")
        or ""
    ).strip()
    if not birth_city or re.search(r"\(([0-9]{2,3}|2A|2B)\)\s*$", birth_city, flags=re.IGNORECASE):
        return birth_city

    department_code = ""
    for field in (
        "birth_department",
        "department",
        "birth_postal_code",
        "birth_zip_code",
    ):
        department_value = trainee.get(field)
        if field == "birth_department":
            department_value = trainee.get("ssiap_diploma_birth_department") or department_value
        department_code = _normalize_department_code(department_value)
        if department_code:
            break

    birth_country = str(
        trainee.get("ssiap_diploma_birth_country") or trainee.get("birth_country") or ""
    ).strip()
    if not department_code and (not birth_country or _normalized_commune_name(birth_country) in {"FRANCE", "FR"}):
        department_code = _lookup_birth_department_code(birth_city)

    if department_code:
        trainee["birth_department"] = department_code
        return f"{birth_city} ({department_code})"
    return birth_city


def _diploma_date_fr(value: str) -> str:
    raw = str(value or "").strip()
    for date_format in ("%Y-%m-%d", "%d/%m/%Y", "%d-%m-%Y", "%Y/%m/%d"):
        try:
            return datetime.datetime.strptime(raw, date_format).strftime("%d/%m/%Y")
        except ValueError:
            continue
    return ""


SSIAP_EXAM_STATUSES = {"pending_results", "certified", "failed"}


def _ssiap_exam_status(trainee: Dict[str, Any]) -> str:
    status = str(trainee.get("ssiap_exam_status") or "pending_results").strip().lower()
    return status if status in SSIAP_EXAM_STATUSES else "pending_results"


SSIAP_DIPLOMA_FIRST_NAME_ACCENTS = {
    "clement": "Clément",
}


def _ssiap_diploma_first_name(value: Any) -> str:
    first_name = normalize_first_name(str(value or ""))
    accent_key = _normalized_token(first_name)
    return SSIAP_DIPLOMA_FIRST_NAME_ACCENTS.get(accent_key, first_name)


def _ssiap_diploma_display_name(trainee: Dict[str, Any]) -> str:
    civility = str(trainee.get("ssiap_diploma_civility") or "Monsieur").strip()
    first_name = _ssiap_diploma_first_name(
        trainee.get("ssiap_diploma_first_name") or trainee.get("first_name") or ""
    )
    last_name = normalize_last_name(
        trainee.get("ssiap_diploma_last_name") or trainee.get("last_name") or ""
    )
    return " ".join(part for part in (civility, first_name, last_name) if part).strip()


def _ssiap_diploma_exam_date(session_item: Dict[str, Any], trainee: Dict[str, Any]) -> str:
    raw = (
        str(trainee.get("ssiap_diploma_exam_date") or "").strip()
        or str(_session_get(session_item, "ssiap_exam_date", "") or "").strip()
        or str(_session_get(session_item, "exam_date", "") or "").strip()
    )
    return _diploma_date_fr(raw)


def _ssiap_diploma_photo_path(trainee: Dict[str, Any]) -> str:
    photo_token = str(trainee.get("identity_photo") or "").strip()
    if not photo_token:
        return ""
    try:
        photo_path = _detokenize_path(photo_token)
    except Exception:
        return ""
    return photo_path if os.path.exists(photo_path) else ""


def _ssiap_diploma_row(session_item: Dict[str, Any], trainee: Dict[str, Any]) -> Dict[str, str]:
    return {
        "trainee_id": str(trainee.get("id") or ""),
        "name": _ssiap_diploma_display_name(trainee),
        "birth_date": _diploma_date_fr(
            trainee.get("ssiap_diploma_birth_date") or trainee.get("birth_date") or ""
        ),
        "birth_place": _ssiap_birth_place_label(trainee),
        "exam_date": _ssiap_diploma_exam_date(session_item, trainee),
        "number": str(trainee.get("ssiap_diploma_number") or "").strip(),
        "photo_path": _ssiap_diploma_photo_path(trainee),
    }


def _next_ssiap_diploma_sequence(data: Dict[str, Any], year: int) -> int:
    highest = 0
    for session_item in data.get("sessions", []):
        for trainee in _session_trainees_list(session_item):
            match = SSIAP_DIPLOMA_NUMBER_RE.match(str(trainee.get("ssiap_diploma_number") or "").strip())
            if match and int(match.group(1)) == year:
                highest = max(highest, int(match.group(2)))

    sequences = data.setdefault("ssiap_diploma_sequences", {})
    try:
        highest = max(highest, int(sequences.get(str(year)) or 0))
    except (TypeError, ValueError):
        pass
    return highest + 1


def _release_deleted_ssiap_diploma_numbers(
    data: Dict[str, Any], deleted_trainees: List[Dict[str, Any]]
) -> None:
    deleted_years = set()
    for trainee in deleted_trainees:
        match = SSIAP_DIPLOMA_NUMBER_RE.match(
            str(trainee.get("ssiap_diploma_number") or "").strip()
        )
        if match:
            deleted_years.add(int(match.group(1)))

    if not deleted_years:
        return

    highest_by_year = {year: 0 for year in deleted_years}
    for session_item in data.get("sessions", []):
        for trainee in _session_trainees_list(session_item):
            match = SSIAP_DIPLOMA_NUMBER_RE.match(
                str(trainee.get("ssiap_diploma_number") or "").strip()
            )
            if not match:
                continue
            year = int(match.group(1))
            if year in highest_by_year:
                highest_by_year[year] = max(highest_by_year[year], int(match.group(2)))

    sequences = data.setdefault("ssiap_diploma_sequences", {})
    for year, highest in highest_by_year.items():
        if highest:
            sequences[str(year)] = highest
        else:
            sequences.pop(str(year), None)


def _delete_trainee_from_session(
    data: Dict[str, Any], session_item: Dict[str, Any], trainee_id: str
) -> bool:
    trainees = _session_trainees_list(session_item)
    deleted_trainees = [
        trainee for trainee in trainees if str(trainee.get("id") or "") == str(trainee_id)
    ]
    if not deleted_trainees:
        return False

    session_item["trainees"] = [
        trainee for trainee in trainees if str(trainee.get("id") or "") != str(trainee_id)
    ]
    session_item.pop("stagiaires", None)
    _release_deleted_ssiap_diploma_numbers(data, deleted_trainees)
    return True


def _reserve_ssiap_diploma_numbers(
    session_id: str, trainee_id: Optional[str] = None
) -> Tuple[Dict[str, Any], List[Dict[str, str]]]:
    os.makedirs(os.path.dirname(SSIAP_DIPLOMA_LOCK_FILE) or ".", exist_ok=True)
    with open(SSIAP_DIPLOMA_LOCK_FILE, "a+", encoding="utf-8") as lock_file:
        fcntl.flock(lock_file.fileno(), fcntl.LOCK_EX)
        try:
            data = load_data()
            session_item = find_session(data, session_id)
            if not session_item:
                raise LookupError("session_not_found")

            training_label = f"{_session_get(session_item, 'training_type', '')} {_session_get(session_item, 'name', '')}".upper()
            if "SSIAP" not in training_label:
                raise ValueError("Cette action est réservée aux sessions SSIAP.")

            trainees = _session_trainees_list(session_item)
            if not trainees:
                raise ValueError("Aucun stagiaire dans cette session SSIAP.")

            selected_trainees = [
                trainee for trainee in trainees if _ssiap_exam_status(trainee) == "certified"
            ]
            if trainee_id is not None:
                matching_trainees = [
                    trainee for trainee in trainees
                    if str(trainee.get("id") or "") == str(trainee_id)
                ]
                if not matching_trainees:
                    raise LookupError("trainee_not_found")
                if _ssiap_exam_status(matching_trainees[0]) != "certified":
                    raise ValueError("Le diplôme peut être généré uniquement pour un stagiaire certifié.")
                selected_trainees = matching_trainees
            if not selected_trainees:
                raise ValueError("Aucun stagiaire certifié dans cette session SSIAP.")

            exam_years = set()
            missing = []
            for trainee in selected_trainees:
                missing_fields = []
                diploma_row = _ssiap_diploma_row(session_item, trainee)
                diploma_first_name = str(
                    trainee.get("ssiap_diploma_first_name") or trainee.get("first_name") or ""
                ).strip()
                diploma_last_name = str(
                    trainee.get("ssiap_diploma_last_name") or trainee.get("last_name") or ""
                ).strip()
                if not diploma_first_name or not diploma_last_name:
                    missing_fields.append("nom ou prénom")
                if not diploma_row["birth_date"]:
                    missing_fields.append("date de naissance")
                if not diploma_row["birth_place"]:
                    missing_fields.append("lieu de naissance")
                if not diploma_row["exam_date"]:
                    missing_fields.append("date d'examen")
                else:
                    exam_years.add(int(diploma_row["exam_date"][-4:]))
                if missing_fields:
                    trainee_name = _ssiap_diploma_display_name(trainee) or str(trainee.get("id") or "Stagiaire sans nom")
                    missing.append(f"{trainee_name} ({', '.join(missing_fields)})")
            if missing:
                raise ValueError(f"Informations manquantes pour : {'; '.join(missing)}.")
            if len(exam_years) != 1:
                raise ValueError("Tous les diplômes générés en masse doivent avoir la même année d'examen.")
            year = next(iter(exam_years))

            diploma_number_counts: Dict[str, int] = {}
            for existing_session in data.get("sessions", []):
                for existing_trainee in _session_trainees_list(existing_session):
                    existing_number = str(existing_trainee.get("ssiap_diploma_number") or "").strip()
                    if existing_number:
                        diploma_number_counts[existing_number] = diploma_number_counts.get(existing_number, 0) + 1

            next_sequence = _next_ssiap_diploma_sequence(data, year)
            diploma_rows = []
            for trainee in selected_trainees:
                diploma_number = str(trainee.get("ssiap_diploma_number") or "").strip()
                match = SSIAP_DIPLOMA_NUMBER_RE.match(diploma_number)
                if (
                    not match
                    or int(match.group(1)) != year
                    or diploma_number_counts.get(diploma_number, 0) > 1
                ):
                    diploma_number = f"083-8323-1-{year}-{next_sequence:05d}"
                    next_sequence += 1
                    trainee["ssiap_diploma_number"] = diploma_number
                    trainee["ssiap_diploma_issued_at"] = _now_iso()

                diploma_rows.append(_ssiap_diploma_row(session_item, trainee))

            session_item["trainees"] = trainees
            session_item.pop("stagiaires", None)
            data.setdefault("ssiap_diploma_sequences", {})[str(year)] = next_sequence - 1
            save_data(data)
            return session_item, diploma_rows
        finally:
            fcntl.flock(lock_file.fileno(), fcntl.LOCK_UN)


def _draw_fitted_pdf_text(
    pdf_canvas,
    text: str,
    x: float,
    y: float,
    max_width: float,
    font_size: float = 23,
    min_font_size: float = 15,
    font_size_step: float = 1,
) -> None:
    size = font_size
    while (
        size > min_font_size
        and pdf_canvas.stringWidth(text, "Helvetica-Bold", size) > max_width
    ):
        size = max(min_font_size, size - font_size_step)
    pdf_canvas.setFont("Helvetica-Bold", size)
    pdf_canvas.drawString(x, y, text)


def _draw_pdf_cover_image(pdf_canvas, image_path: str, x: float, y: float, width: float, height: float) -> bool:
    if not image_path or not os.path.exists(image_path):
        return False
    from reportlab.lib.utils import ImageReader

    canvas_state_saved = False
    try:
        with Image.open(image_path) as source:
            image = ImageOps.exif_transpose(source).convert("RGB")
            image_width, image_height = image.size
            if image_width <= 0 or image_height <= 0:
                return False
            image_reader = ImageReader(image)
            scale = max(width / image_width, height / image_height)
            draw_width = image_width * scale
            draw_height = image_height * scale
            draw_x = x + (width - draw_width) / 2
            draw_y = y + (height - draw_height) / 2

            pdf_canvas.saveState()
            canvas_state_saved = True
            clip_path = pdf_canvas.beginPath()
            clip_path.rect(x, y, width, height)
            pdf_canvas.clipPath(clip_path, stroke=0, fill=0)
            pdf_canvas.drawImage(
                image_reader,
                draw_x,
                draw_y,
                width=draw_width,
                height=draw_height,
                preserveAspectRatio=True,
                mask="auto",
            )
            pdf_canvas.restoreState()
            canvas_state_saved = False
            return True
    except Exception:
        if canvas_state_saved:
            pdf_canvas.restoreState()
        return False

def _build_ssiap_diplomas_pdf(diplomas: List[Dict[str, str]]) -> BytesIO:
    from reportlab.lib.pagesizes import A4, landscape
    from reportlab.lib.units import mm
    from reportlab.lib.utils import ImageReader
    from reportlab.pdfgen import canvas

    template_width, template_height = 2000, 1414
    page_width, page_height = landscape(A4)
    scale_x = page_width / template_width
    scale_y = page_height / template_height
    output = BytesIO()
    pdf = canvas.Canvas(output, pagesize=(page_width, page_height), pageCompression=1)
    background = ImageReader(SSIAP_DIPLOMA_TEMPLATE)

    def draw_text(
        text: str,
        x: float,
        y_from_top: float,
        max_width: float,
        font_size: float = 21,
    ) -> None:
        _draw_fitted_pdf_text(
            pdf,
            text,
            x * scale_x,
            page_height - (y_from_top * scale_y),
            max_width * scale_x,
            font_size * scale_y,
            min_font_size=15 * scale_y,
            font_size_step=scale_y,
        )

    def draw_missing_title_accent() -> None:
        # The source image says “A PERSONNES”. Add the grave accent as a vector
        # overlay so the diploma reads “À PERSONNES” without modifying the JPG.
        accent = pdf.beginPath()
        accent.moveTo(1260 * scale_x, page_height - (187 * scale_y))
        accent.lineTo(1267 * scale_x, page_height - (187 * scale_y))
        accent.lineTo(1276 * scale_x, page_height - (195 * scale_y))
        accent.lineTo(1268 * scale_x, page_height - (195 * scale_y))
        accent.close()
        pdf.saveState()
        pdf.setFillColorRGB(42 / 255, 42 / 255, 42 / 255)
        pdf.drawPath(accent, fill=1, stroke=0)
        pdf.restoreState()

    for diploma in diplomas:
        pdf.drawImage(
            background,
            0,
            0,
            width=page_width,
            height=page_height,
            preserveAspectRatio=False,
        )
        draw_missing_title_accent()
        photo_width = 35 * mm
        photo_height = 45 * mm
        photo_right_margin = 5 * mm
        photo_top_margin = 12 * mm
        _draw_pdf_cover_image(
            pdf,
            str(diploma.get("photo_path") or ""),
            page_width - photo_right_margin - photo_width,
            page_height - photo_top_margin - photo_height,
            photo_width,
            photo_height,
        )
        # Coordinates are authored against the 2000 × 1414 template and scaled to physical A4 landscape.
        draw_text(diploma["exam_date"], 1445, 771, 300)
        draw_text(diploma["name"], 1080, 846, 650)
        draw_text(diploma["birth_date"], 1080, 883, 300)
        draw_text(diploma["birth_place"], 1080, 921, 650)
        draw_text(diploma["name"], 1120, 1108, 620)
        draw_text(diploma["number"], 1170, 1145, 430)
        draw_text(diploma["exam_date"], 420, 1166, 300)
        pdf.showPage()

    pdf.save()
    output.seek(0)
    return output


def _find_ssiap_trainee(session_id: str, trainee_id: str) -> Tuple[Dict[str, Any], Dict[str, Any], Dict[str, Any]]:
    data = load_data()
    session_item = find_session(data, session_id)
    if not session_item:
        raise LookupError("session_not_found")
    training_label = f"{_session_get(session_item, 'training_type', '')} {_session_get(session_item, 'name', '')}".upper()
    if "SSIAP" not in training_label:
        raise ValueError("Cette action est réservée aux sessions SSIAP.")
    trainee = next(
        (item for item in _session_trainees_list(session_item) if str(item.get("id") or "") == str(trainee_id)),
        None,
    )
    if not trainee:
        raise LookupError("trainee_not_found")
    return data, session_item, trainee


@app.get("/admin/sessions/<session_id>/trainees/<trainee_id>/ssiap-diploma")
@admin_login_required
def admin_view_ssiap_diploma(session_id: str, trainee_id: str):
    if not REPORTLAB_LIBRARY_AVAILABLE or not os.path.exists(SSIAP_DIPLOMA_TEMPLATE):
        abort(503, description="Le modèle ou le moteur PDF des diplômes est indisponible.")
    try:
        _data, session_item, trainee = _find_ssiap_trainee(session_id, trainee_id)
    except LookupError:
        abort(404)
    except ValueError as exc:
        return str(exc), 400
    if not str(trainee.get("ssiap_diploma_number") or "").strip():
        abort(404, description="Ce diplôme n'a pas encore été généré.")
    diploma = _ssiap_diploma_row(session_item, trainee)
    trainee_name = re.sub(r"[^A-Za-z0-9_-]+", "-", diploma["name"]).strip("-") or "stagiaire"
    return send_file(
        _build_ssiap_diplomas_pdf([diploma]),
        mimetype="application/pdf",
        as_attachment=False,
        download_name=f"diplome-SSIAP-{trainee_name}-{diploma['exam_date'][-4:]}.pdf",
    )


@app.post("/admin/sessions/<session_id>/trainees/<trainee_id>/ssiap-diploma-info")
@admin_login_required
@admin_write_required
def admin_update_ssiap_diploma_info(session_id: str, trainee_id: str):
    try:
        data, session_item, trainee = _find_ssiap_trainee(session_id, trainee_id)
    except LookupError:
        abort(404)
    except ValueError as exc:
        return str(exc), 400

    fields = {
        "ssiap_diploma_civility": "civility",
        "ssiap_diploma_first_name": "first_name",
        "ssiap_diploma_last_name": "last_name",
        "ssiap_diploma_birth_date": "birth_date",
        "ssiap_diploma_birth_city": "birth_city",
        "ssiap_diploma_birth_department": "birth_department",
        "ssiap_diploma_birth_country": "birth_country",
        "ssiap_diploma_exam_date": "exam_date",
    }
    for storage_key, form_key in fields.items():
        value = str(request.form.get(form_key) or "").strip()
        if storage_key == "ssiap_diploma_first_name":
            value = _ssiap_diploma_first_name(value)
        trainee[storage_key] = value

    row = _ssiap_diploma_row(session_item, trainee)
    if (
        not trainee["ssiap_diploma_first_name"]
        or not trainee["ssiap_diploma_last_name"]
        or not row["birth_date"]
        or not row["birth_place"]
        or not row["exam_date"]
    ):
        return "Le nom, le prénom, la date et le lieu de naissance ainsi que la date d'examen sont obligatoires.", 400
    session_item["trainees"] = _session_trainees_list(session_item)
    session_item.pop("stagiaires", None)
    save_data(data)
    return redirect(url_for("admin_trainees", session_id=session_id))


@app.post("/admin/sessions/<session_id>/ssiap-diplomas")
@admin_login_required
@admin_write_required
def admin_generate_ssiap_diplomas(session_id: str):
    if not REPORTLAB_LIBRARY_AVAILABLE or not os.path.exists(SSIAP_DIPLOMA_TEMPLATE):
        abort(503, description="Le modèle ou le moteur PDF des diplômes est indisponible.")
    try:
        session_item, diplomas = _reserve_ssiap_diploma_numbers(session_id)
    except LookupError:
        abort(404)
    except ValueError as exc:
        return str(exc), 400

    year = diplomas[0]["exam_date"][-4:]
    session_name = re.sub(r"[^A-Za-z0-9_-]+", "-", str(_session_get(session_item, "name", "SSIAP") or "SSIAP")).strip("-")
    response = send_file(
        _build_ssiap_diplomas_pdf(diplomas),
        mimetype="application/pdf",
        as_attachment=True,
        download_name=f"diplomes-{session_name}-{year}.pdf",
    )
    response.headers["X-SSIAP-Diploma-Numbers"] = json.dumps(
        {diploma["trainee_id"]: diploma["number"] for diploma in diplomas},
        separators=(",", ":"),
    )
    return response


@app.post("/admin/sessions/<session_id>/trainees/<trainee_id>/ssiap-diploma")
@admin_login_required
@admin_write_required
def admin_generate_ssiap_diploma(session_id: str, trainee_id: str):
    if not REPORTLAB_LIBRARY_AVAILABLE or not os.path.exists(SSIAP_DIPLOMA_TEMPLATE):
        abort(503, description="Le modèle ou le moteur PDF des diplômes est indisponible.")
    try:
        _session_item, diplomas = _reserve_ssiap_diploma_numbers(session_id, trainee_id)
    except LookupError:
        abort(404)
    except ValueError as exc:
        return str(exc), 400

    diploma = diplomas[0]
    trainee_name = re.sub(r"[^A-Za-z0-9_-]+", "-", diploma["name"]).strip("-") or "stagiaire"
    response = send_file(
        _build_ssiap_diplomas_pdf(diplomas),
        mimetype="application/pdf",
        as_attachment=True,
        download_name=f"diplome-SSIAP-{trainee_name}-{diploma['exam_date'][-4:]}.pdf",
    )
    response.headers["X-SSIAP-Diploma-Numbers"] = json.dumps(
        {diploma["trainee_id"]: diploma["number"]},
        separators=(",", ":"),
    )
    return response


