@app.get("/admin/sessions/<session_id>/trainees")
@admin_login_required
def admin_trainees(session_id: str):
    data = load_data()
    s = find_session(data, session_id)
    if not s:
        abort(404)
    if _is_wedof_leads_session(s):
        abort(404)

    # normalize session view
    session_view = {
        "id": s.get("id"),
        "name": _session_get(s, "name", ""),
        "training_type": _session_get(s, "training_type", ""),
        "date_start": _session_get(s, "date_start", ""),
        "date_end": _session_get(s, "date_end", ""),
        "exam_date": _session_get(s, "exam_date", ""),
        "exam_theory_date": _session_get(s, "exam_theory_date", ""),
        "exam_practice_date": _session_get(s, "exam_practice_date", ""),
        "practice_training_date": _session_get(s, "practice_training_date", ""),
        "ssiap_exam_date": _session_get(s, "ssiap_exam_date", ""),
        "aps_elearning_enabled": bool(s.get("aps_elearning_enabled")),
        "prospects_comment": _session_get(s, "prospects_comment", ""),
    }

    trainees = _session_trainees_list(s)
    training_type = session_view["training_type"]

    auto_refresh_external = (request.args.get("refresh_external") or "").strip() == "1"

    # normalize trainees (and optionally refresh external statuses)
    for t in trainees:
        ln = normalize_last_name(t.get("last_name") or "")
        fn = normalize_first_name(t.get("first_name") or "")
        email = (t.get("email") or "").strip().lower()
        unread_summary = _scotia_unread_thread_summary(t)
        t["scotia_unread_thread_count"] = int(unread_summary.get("count") or 0) if unread_summary else 0

        if ln:
            t["last_name"] = ln
        if fn:
            t["first_name"] = fn

        _sync_trainee_afc_medical_requirement(t, session_view["name"])
        ensure_documents_schema_for_trainee(t, training_type)
        t["dossier_status"] = "complete" if dossier_is_complete_total(t, training_type, _session_get(s, "date_start", "")) else "incomplete"

        current_cnaps = t.get("cnaps") or ""

        # ✅ si déjà validé manuellement, on ne touche pas
        if _normalize_cnaps_status(current_cnaps) != "CARTE PROFESSIONNELLE OK" and auto_refresh_external:
            if ln and fn:
                cn = fetch_cnaps_status_by_name(ln, fn)

                # ✅ n'écrase jamais avec INCONNU
                if cn:
                    cn_u = str(cn).strip().upper()
                    if cn_u not in ("INCONNU", "UNKNOWN", ""):
                        if _normalize_cnaps_status(cn_u) != _normalize_cnaps_status(current_cnaps):
                            t["cnaps"] = cn_u
                            record_cnaps_status_change(t, cn_u)

        # valeur par défaut si vide
        if not (t.get("cnaps") or "").strip():
            t["cnaps"] = "INCONNU"
            record_cnaps_status_change(t, t["cnaps"])

        # hosting only for A3P
        if session_view["training_type"] == "A3P":
            # ✅ règle anti-bug : on ne downgrade JAMAIS "reserved"
            current = (t.get("hosting_status") or "unknown").strip().lower()
            should_refresh_hosting = current != "reserved"
            _log_charles_hebergement_trace(
                "admin_trainees",
                "état local avant rendu",
                email=email,
                last_name=ln,
                first_name=fn,
                session_name=session_view["name"],
                session_date_start=session_view["date_start"],
                session_date_end=session_view["date_end"],
                current_hosting_status=current,
                auto_refresh_external=auto_refresh_external,
                should_refresh_hosting_on_render=should_refresh_hosting,
            )

            if should_refresh_hosting:
                _log_charles_hebergement_trace(
                    "admin_trainees",
                    "appel fetch_hebergement_status depuis le rendu serveur",
                    email=email,
                    last_name=ln,
                    first_name=fn,
                    session_name=session_view["name"],
                    session_date_start=session_view["date_start"],
                    session_date_end=session_view["date_end"],
                )
                hb = fetch_hebergement_status(
                    email,
                    last_name=ln,
                    first_name=fn,
                    session_name=session_view["name"],
                    session_date_start=session_view["date_start"],
                    session_date_end=session_view["date_end"],
                )
            else:
                hb = None
                _log_charles_hebergement_trace(
                    "admin_trainees",
                    "fetch_hebergement_status non appelé au rendu serveur",
                    email=email,
                    last_name=ln,
                    first_name=fn,
                    session_name=session_view["name"],
                    session_date_start=session_view["date_start"],
                    session_date_end=session_view["date_end"],
                    reason="status_local_deja_reserved",
                )

            _log_charles_hebergement_trace(
                "admin_trainees",
                "résultat fetch_hebergement_status au rendu serveur",
                email=email,
                last_name=ln,
                first_name=fn,
                session_name=session_view["name"],
                session_date_start=session_view["date_start"],
                session_date_end=session_view["date_end"],
                fetch_result=hb,
                current_hosting_status=current,
            )

            if hb == "reserved":
                t["hosting_status"] = "reserved"
            elif current == "reserved":
                # on garde reserved quoi qu'il arrive
                t["hosting_status"] = "reserved"
            else:
                # sinon on garde l'ancien si on n'a pas mieux
                t["hosting_status"] = current if current else "unknown"
            _log_charles_hebergement_trace(
                "admin_trainees",
                "valeur finale sauvegardée avant template",
                email=email,
                last_name=ln,
                first_name=fn,
                session_name=session_view["name"],
                session_date_start=session_view["date_start"],
                session_date_end=session_view["date_end"],
                final_hosting_status=t.get("hosting_status"),
            )
        else:
            t.pop("hosting_status", None)

    show_vae = (session_view["training_type"] == "DIRIGEANT VAE")
    vae_dashboard_counts = {}
    if show_vae:
        now_utc = datetime.datetime.now(datetime.timezone.utc)
        vae_dashboard_counts = {
            "no_login": 0,
            "new_vae_request_72h": 0,
            "l1_pending_transmission": 0,
            "non_recevable": 0,
        }
        for t in trainees:
            if not isinstance(t.get("vae_action_dates"), dict):
                t["vae_action_dates"] = {}
            _sync_vae_status_with_actions(t)
            created_at = _parse_iso_datetime(t.get("created_at") or "")
            if created_at and created_at.tzinfo is None:
                created_at = created_at.replace(tzinfo=datetime.timezone.utc)
            if created_at:
                created_at = created_at.astimezone(datetime.timezone.utc)
            t["is_vae_new_request_72h"] = bool(
                created_at
                and datetime.timedelta(0) <= (now_utc - created_at) <= datetime.timedelta(hours=72)
            )

            status_key = vae_status_view(t.get("vae_status") or t.get("vae_status_label"))["key"]
            livret_1_transmitted = bool(
                t["vae_action_dates"].get("livret_1_transmitted_scotia")
                or t.get("livret_1_transmitted_scotia")
                or t.get("livret_1_transmitted_scotia_at")
            )
            count_status_key = "livret_2_validated" if status_key == "financement_l2_validated" else status_key
            if status_key != "livret_1_analysis" or livret_1_transmitted:
                count_key = f"status:{count_status_key}"
                vae_dashboard_counts[count_key] = vae_dashboard_counts.get(count_key, 0) + 1
            if status_key == "livret_1_analysis" and not livret_1_transmitted:
                vae_dashboard_counts["l1_pending_transmission"] += 1
            if (t.get("scotia_status") or "").strip() == "non_recevable":
                vae_dashboard_counts["non_recevable"] += 1
            if not t.get("public_has_logged_in"):
                vae_dashboard_counts["no_login"] += 1
            if t.get("is_vae_new_request_72h"):
                vae_dashboard_counts["new_vae_request_72h"] += 1
            unread_summary = _scotia_unread_thread_summary(t)
            t["scotia_unread_thread_count"] = int(unread_summary.get("count") or 0) if unread_summary else 0

        scotia_items_by_trainee = {
            (str(item.get("session_id") or ""), str(item.get("trainee_id") or "")): item
            for item in _all_scotia_items(data, include_archived=True)
        }
        for t in trainees:
            key = (str(session_view["id"] or ""), str(t.get("id") or ""))
            t["scotia_admin_status"] = _scotia_admin_status_badge(scotia_items_by_trainee.get(key))

    # persist normalized trainees back into storage
    s["trainees"] = trainees
    s.pop("stagiaires", None)
    save_data(data)
    stats = compute_stats(s)
    show_hosting = (session_view["training_type"] == "A3P")
    is_vtc = ("VTC" in (session_view["training_type"] or "").upper())
    is_dirigeant = ("DIRIGEANT" in (session_view["training_type"] or "").upper())

    # ✅ docs fin de formation par stagiaire (pour surlignage + n/3 + étiquettes)
    for t in trainees:
        t.setdefault("deliverables", {})
        d_done, d_total, d_ok = deliverables_progress(t)
        t["deliverables_done"] = d_done
        t["deliverables_total"] = d_total
        t["deliverables_ok"] = d_ok
        t["deliverables_text"] = f"{d_done}/{d_total}"

        # ✅ étiquettes ligne (admin_trainees.html)
        dv = t.get("deliverables") or {}
        t["has_sst"] = bool((dv.get("carte_sst") or "").strip())
        t["has_attestation"] = bool((dv.get("attestation_fin_formation") or "").strip())
        t["has_diplome"] = bool((dv.get("diplome") or "").strip())

        badges = []
        if t["has_sst"]:
            badges.append("SST")
        if t["has_attestation"]:
            badges.append("ATTESTATIONS")
        if t["has_diplome"]:
            badges.append("DIPLÔME")
        t["badges"] = badges

    for t in trainees:
        if session_view["training_type"] != "A3P":
            continue
        _log_charles_hebergement_trace(
            "admin_trainees",
            "valeur envoyée au template",
            email=(t.get("email") or "").strip().lower(),
            last_name=t.get("last_name") or "",
            first_name=t.get("first_name") or "",
            session_name=session_view["name"],
            session_date_start=session_view["date_start"],
            session_date_end=session_view["date_end"],
            template_hosting_status=t.get("hosting_status"),
        )

    if show_vae:
        trainees.sort(
            key=lambda t: (
                _parse_iso_datetime(t.get("created_at") or "") or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc),
                _trainee_alpha_sort_key(t),
            ),
            reverse=True,
        )
    else:
        trainees.sort(key=_trainee_alpha_sort_key)

    return render_template(
        "admin_trainees.html",
        session=session_view,
        trainees=trainees,
        stats=stats,
        show_hosting=show_hosting,
        show_vae=show_vae,
        is_vtc=is_vtc,
        is_dirigeant=is_dirigeant,
        vae_dashboard_counts=vae_dashboard_counts,
        enums=ENUMS,
        is_adef=_is_adef_training(session_view["training_type"]),
    )


@app.get("/admin/trainees/vtc")
@admin_login_required
def admin_vtc_trainees_all():
    data = load_data()
    all_trainees = []

    for s in data.get("sessions", []):
        if _is_wedof_leads_session(s) or bool(s.get("archived")):
            continue
        training_type = _session_get(s, "training_type", "")
        if "VTC" not in (training_type or "").upper():
            continue

        session_name = _session_get(s, "name", "")
        for t in _session_trainees_list(s):
            ln = normalize_last_name(t.get("last_name") or "")
            fn = normalize_first_name(t.get("first_name") or "")
            if ln:
                t["last_name"] = ln
            if fn:
                t["first_name"] = fn

            ensure_documents_schema_for_trainee(t, training_type)
            t["dossier_status"] = "complete" if dossier_is_complete_total(t, training_type, _session_get(s, "date_start", "")) else "incomplete"

            trainee_view = dict(t)
            trainee_view["source_session_id"] = s.get("id")
            trainee_view["source_session_name"] = session_name
            trainee_view["source_session_date_start"] = _session_get(s, "date_start", "")
            trainee_view["source_session_date_end"] = _session_get(s, "date_end", "")
            all_trainees.append(trainee_view)

    for t in all_trainees:
        t.setdefault("deliverables", {})
        d_done, d_total, d_ok = deliverables_progress(t)
        t["deliverables_done"] = d_done
        t["deliverables_total"] = d_total
        t["deliverables_ok"] = d_ok
        t["deliverables_text"] = f"{d_done}/{d_total}"
        t["has_sst"] = bool((t.get("deliverables") or {}).get("carte_sst") or "")
        t["has_attestation"] = bool((t.get("deliverables") or {}).get("attestation_fin_formation") or "")
        t["has_diplome"] = bool((t.get("deliverables") or {}).get("diplome") or "")
        t["badges"] = []

    all_trainees.sort(key=lambda t: (
        (t.get("last_name") or "").strip().upper(),
        (t.get("first_name") or "").strip().upper(),
        (t.get("source_session_name") or "").strip().upper(),
    ))

    session_view = {
        "id": "__all_vtc__",
        "name": "Tous les stagiaires VTC",
        "training_type": "VTC",
        "date_start": "",
        "date_end": "",
        "exam_date": "",
        "exam_theory_date": "",
        "exam_practice_date": "",
        "practice_training_date": "",
        "ssiap_exam_date": "",
        "prospects_comment": "",
    }
    stats = compute_stats({"training_type": "VTC", "trainees": all_trainees})

    save_data(data)
    return render_template(
        "admin_trainees.html",
        session=session_view,
        trainees=all_trainees,
        stats=stats,
        show_hosting=False,
        show_vae=False,
        is_vtc=True,
        is_dirigeant=False,
        enums=ENUMS,
        is_adef=False,
        all_vtc=True,
    )


# =========================
# FICHE STAGIAIRE (HTML)
# =========================




def _easter_date(year: int) -> datetime.date:
    a = year % 19
    b = year // 100
    c = year % 100
    d = b // 4
    e = b % 4
    f = (b + 8) // 25
    g = (b - f + 1) // 3
    h = (19 * a + b - d - g + 15) % 30
    i = c // 4
    k = c % 4
    l = (32 + 2 * e + 2 * i - h - k) % 7
    m = (a + 11 * h + 22 * l) // 451
    month = (h + l - 7 * m + 114) // 31
    day = ((h + l - 7 * m + 114) % 31) + 1
    return datetime.date(year, month, day)


def _french_public_holidays(year: int) -> set[datetime.date]:
    easter = _easter_date(year)
    return {
        datetime.date(year, 1, 1),
        easter + datetime.timedelta(days=1),
        datetime.date(year, 5, 1),
        datetime.date(year, 5, 8),
        easter + datetime.timedelta(days=39),
        easter + datetime.timedelta(days=50),
        datetime.date(year, 7, 14),
        datetime.date(year, 8, 15),
        datetime.date(year, 11, 1),
        datetime.date(year, 11, 11),
        datetime.date(year, 12, 25),
    }


def _is_aps_working_day(day: datetime.date) -> bool:
    return day.weekday() < 5 and day not in _french_public_holidays(day.year)


def _next_aps_working_day(day: datetime.date) -> datetime.date:
    current = day
    while not _is_aps_working_day(current):
        current += datetime.timedelta(days=1)
    return current


def _add_aps_working_days(start_day: datetime.date, working_days: int) -> datetime.date:
    current = _next_aps_working_day(start_day)
    remaining = max(int(working_days or 1), 1)
    while True:
        if _is_aps_working_day(current):
            remaining -= 1
            if remaining <= 0:
                return current
        current += datetime.timedelta(days=1)


def _add_aps_training_hours(start_day: datetime.date, total_hours: int, *, normal_day_hours: int = 7, max_day_hours: int = 8) -> tuple[datetime.date, int]:
    current = _next_aps_working_day(start_day)
    remaining = max(int(total_hours or 0), 0)
    working_days = 0
    while remaining > 0:
        if _is_aps_working_day(current):
            working_days += 1
            if remaining <= max_day_hours:
                return current, working_days
            remaining -= normal_day_hours
        current += datetime.timedelta(days=1)
    return current, working_days


def _parse_iso_date(raw: str) -> datetime.date | None:
    value = (raw or "").strip()[:10]
    if not value:
        return None
    try:
        return datetime.datetime.strptime(value, "%Y-%m-%d").date()
    except (TypeError, ValueError):
        return None


def calculateApsPeriods(sessionStartDate: str, presentielStartDate: str = "") -> Dict[str, str]:
    start = _parse_iso_date(sessionStartDate)
    if not start:
        return {}

    distanciel_start = _next_aps_working_day(start)
    distanciel_end, distanciel_days = _add_aps_training_hours(distanciel_start, 62)
    requested_presentiel_start = _parse_iso_date(presentielStartDate)
    presentiel_start = _next_aps_working_day(requested_presentiel_start or (distanciel_end + datetime.timedelta(days=1)))
    if presentiel_start <= distanciel_end:
        presentiel_start = _next_aps_working_day(distanciel_end + datetime.timedelta(days=1))
    presentiel_end, presentiel_days = _add_aps_training_hours(presentiel_start, 113)
    exam_date = _next_aps_working_day(presentiel_end + datetime.timedelta(days=1))
    return {
        "distancielStart": distanciel_start.isoformat(),
        "distancielEnd": distanciel_end.isoformat(),
        "distancielHours": 62,
        "distancielDays": distanciel_days,
        "presentielStart": presentiel_start.isoformat(),
        "presentielEnd": presentiel_end.isoformat(),
        "presentielHours": 113,
        "presentielDays": presentiel_days,
        "examDate": exam_date.isoformat(),
    }


def _compute_aps_period_dates(date_start: str, presentiel_start: str = "") -> Dict[str, str]:
    periods = calculateApsPeriods(date_start, presentiel_start)
    if not periods:
        return {}
    return {
        "aps_remote_start": periods["distancielStart"],
        "aps_remote_end": periods["distancielEnd"],
        "aps_in_person_start": periods["presentielStart"],
        "aps_in_person_end": periods["presentielEnd"],
        "aps_in_person_hours": periods["presentielHours"],
        "aps_in_person_days": periods["presentielDays"],
        "aps_computed_exam_date": periods["examDate"],
    }


def _sync_aps_period_dates(session_obj: Dict[str, Any]) -> None:
    training_type = (_session_get(session_obj, "training_type", "") or "").strip().upper()
    if not training_type.startswith("APS"):
        for key in ("aps_remote_start", "aps_remote_end", "aps_in_person_start", "aps_in_person_end", "aps_in_person_hours", "aps_in_person_days", "aps_computed_exam_date"):
            session_obj.pop(key, None)
        return
    periods = _compute_aps_period_dates(
        _session_get(session_obj, "date_start", ""),
        _session_get(session_obj, "aps_in_person_start", ""),
    )
    if periods:
        session_obj.update(periods)
        session_obj["date_start"] = periods["aps_remote_start"]
        session_obj["date_end"] = periods["aps_in_person_end"]
        exam = _parse_iso_date(_session_get(session_obj, "exam_date", ""))
        presentiel_end = _parse_iso_date(periods["aps_in_person_end"])
        if not exam or (presentiel_end and presentiel_end >= exam):
            session_obj["exam_date"] = periods["aps_computed_exam_date"]

