def _admin_sync_trainee_to_ypareo(session_id: str, trainee_id: str):
    """Synchronize both the YPAREO person and cursus for a local trainee."""
    data = load_data()
    trainee_session = find_session(data, session_id)
    if not trainee_session:
        abort(404)

    trainee = find_trainee(trainee_session, trainee_id)
    if not trainee:
        abort(404)

    person_created = creer_apprenant_ypareo(trainee, trainee_session)
    cursus_created = trainee.get("ypareo_cursus_statut") == "Créé"
    success = bool(person_created and cursus_created)

    if success:
        message = "Données transférées vers YPAREO NEO avec succès"
        flash(message, "success")
    else:
        reason = (
            trainee.get("ypareo_cursus_erreur")
            if person_created and not cursus_created
            else trainee.get("ypareo_erreur")
        ) or "Erreur inconnue lors de la transmission"
        message = str(reason)
        flash(f"Transmission vers YPAREO NEO impossible : {message}", "error")

    trainee_session["trainees"] = _session_trainees_list(trainee_session)
    trainee_session.pop("stagiaires", None)
    save_data(data)

    if request.accept_mimetypes.best == "application/json":
        return jsonify({
            "ok": success,
            "message": "Données transférées vers YPAREO NEO avec succès" if success else "",
            "error": "" if success else message,
            "ypareo_id": trainee.get("ypareo_id") or "",
            "ypareo_cursus_id": trainee.get("ypareo_cursus_id") or "",
        }), 200 if success else 422

    return redirect(url_for("admin_trainee_page", session_id=session_id, trainee_id=trainee_id))


@app.post("/admin/sessions/<session_id>/trainees/<trainee_id>/ypareo")
@admin_login_required
@admin_write_required
def admin_send_trainee_to_ypareo(session_id: str, trainee_id: str):
    return _admin_sync_trainee_to_ypareo(session_id, trainee_id)


@app.post("/admin/sessions/<session_id>/trainees/<trainee_id>/ypareo/personne")
@admin_login_required
@admin_write_required
def admin_resend_trainee_ypareo_person(session_id: str, trainee_id: str):
    """Keep the legacy person retry URL aligned with the complete YPAREO sync."""
    return _admin_sync_trainee_to_ypareo(session_id, trainee_id)


@app.post("/admin/sessions/<session_id>/trainees/<trainee_id>/ypareo/cursus")
@admin_login_required
@admin_write_required
def admin_create_trainee_ypareo_cursus(session_id: str, trainee_id: str):
    data = load_data()
    trainee_session = find_session(data, session_id)
    if not trainee_session:
        abort(404)
    trainee = find_trainee(trainee_session, trainee_id)
    if not trainee:
        abort(404)

    id_personne = trainee.get("ypareo_id")
    if not id_personne:
        trainee["ypareo_cursus_statut"] = "Non envoyé"
        trainee["ypareo_cursus_erreur"] = "La personne doit d'abord être créée dans YPAREO"
        flash("Impossible de créer le cursus : personne YPAREO absente.", "error")
    elif creer_cursus_ypareo(id_personne, trainee, trainee_session):
        flash("Cursus créé dans YPAREO.", "success")
    else:
        flash(
            f"Création du cursus YPAREO impossible : {trainee.get('ypareo_cursus_erreur') or 'erreur inconnue'}",
            "error",
        )

    trainee_session["trainees"] = _session_trainees_list(trainee_session)
    trainee_session.pop("stagiaires", None)
    save_data(data)
    return redirect(url_for("admin_trainee_page", session_id=session_id, trainee_id=trainee_id))


@app.post("/api/trainees/import_from_image")
@admin_login_required
@admin_write_required
def api_import_trainee_from_image():
    f = request.files.get("file")
    if not f:
        return jsonify({"ok": False, "error": "missing_file"}), 400

    filename = (f.filename or "import.png").strip()
    lower = filename.lower()
    allowed = (".png", ".jpg", ".jpeg", ".webp", ".bmp")
    if not lower.endswith(allowed):
        return jsonify({"ok": False, "error": "invalid_file_type"}), 400

    file_bytes = f.read()
    if not file_bytes:
        return jsonify({"ok": False, "error": "empty_file"}), 400

    text, ocr_error = _ocr_extract_text_from_image(file_bytes, filename, f.mimetype or "")
    if not text:
        return jsonify({"ok": False, "error": "ocr_failed", "detail": ocr_error}), 422

    extracted = _extract_trainee_fields_from_ocr_text(text)
    return jsonify({"ok": True, "fields": extracted})





@app.post("/api/sessions/<session_id>/stagiaires/<trainee_id>/update")
@admin_login_required
@admin_write_required
def api_update_trainee(session_id: str, trainee_id: str):
    data = load_data()
    s = find_session(data, session_id)
    if not s:
        return jsonify({"ok": False, "error": "session_not_found"}), 404

    trainees = _session_trainees_list(s)
    t = None
    for x in trainees:
        if x.get("id") == trainee_id:
            t = x
            break
    if not t:
        return jsonify({"ok": False, "error": "trainee_not_found"}), 404

    payload = request.get_json(silent=True) or {}
    cnaps_remote_history = payload.pop("statut_cnaps_history", None)
    was_exam_fees_paid = bool(t.get("exam_fees_paid"))
    previous_elearning_link = (t.get("elearning_link") or "").strip()
    previous_cnaps_status = (t.get("cnaps") or "").strip()
    previous_vae_action_dates = t.get("vae_action_dates") if isinstance(t.get("vae_action_dates"), dict) else {}

    # Your template uses:
    # - convention_status, test_fr_status, dossier_status, financement_status, vae_status, comment, cnaps
    allowed = {
        "convention_status",
        "convention_saisie_done",
        "convention_signed_done",
        "test_fr_status",
        "dossier_status",
        "force_dossier_complete",
        "financement_status",
        "vae_status",
        "comment",
        "financement_comment",
        "cash_payment_enabled",
        "cash_payment_amount",
        "cash_payment_installments",
        "cash_payment_settled",
        "cash_payment_settled_date",
        "cash_payment_settled_comment",
        "financement_new_date_seen",
        "vae_status_label",
        "vae_jury_date",
        "vae_action_dates",
        "cnaps",
        "no_permis",
        "no_bac_diploma",
        "public_hide_infos",
        "public_hide_docs",
        "public_hide_suivi",
        "scotia_force_visible",
        "public_hide_popup",
        "last_name",
        "first_name",
        "email",
        "phone",
        "training_price",
        "exclude_from_sales_tracking",
        "sales_tracking_amount",
        "cpf_amount",
        "personal_amount",
        "other_amount",
        "birth_city",
        "ssiap_exam_date",
        "ssiap_exam_status",
        "address",
        "zip_code",
        "city",
        "vtc_cmar_id",
        "vtc_cm_login",
        "vtc_cm_password",
        "vtc_cm_submitted_at",
        "vtc_cm_reminder_auto_disabled",
        "vtc_cm_reminder_auto_disabled_at",
        "exam_fees_paid",
        "vtc_cmar_manual_ok",
        "elearning_link",
        "vtc_elearning_manual_ok",
        "vtc_book_sent_at",
        "vtc_book_manual_ok",
        "vtc_theory_exam_sent_at",
        "vtc_theory_exam_email_ok",
        "vtc_theory_exam_sms_ok",
        "vtc_theory_result",
        "vtc_theory_result_label",
        "vtc_theory_status_manual",
        "vtc_practice_convocation_sent_at",
        "vtc_practice_result",
        "vtc_practice_result_label",
        "vtc_practice_status_manual",
        "vtc_practice_exam_sent_at",
        "vtc_practice_exam_email_ok",
        "vtc_practice_exam_sms_ok",
        "vtc_exam_center",
        "vtc_real_training_dates",
        "aps_elearning_login",
        "aps_elearning_password",

    }

    previous_vae_status = vae_status_view(t.get("vae_status"))["key"]
    vae_fields_changed = any(k in payload for k in ("vae_status", "vae_status_label", "vae_action_dates", "vae_jury_date"))

    send_vae_notification = True if payload.get("send_vae_notification", True) in (True, "true", "1", 1, "yes", "on") else False
    send_exam_fees_notification = True if payload.get("send_exam_fees_notification", True) in (True, "true", "1", 1, "yes", "on") else False
    send_elearning_notification = True if payload.get("send_elearning_notification", True) in (True, "true", "1", 1, "yes", "on") else False
    aps_elearning_fields_enabled = (
        (_session_get(s, "training_type", "") or "").strip().upper().startswith("APS")
        and bool(s.get("aps_elearning_enabled"))
    )

    if "vtc_book_sent_at" in payload:
        vtc_book_sent_payload = payload.get("vtc_book_sent_at")
        if isinstance(vtc_book_sent_payload, str) and vtc_book_sent_payload.strip() and not _is_vtc_book_address_complete(t):
            return jsonify({"ok": False, "error": "vtc_book_address_incomplete"}), 400

    for k, v in payload.items():
        if k in ("send_vae_notification", "send_exam_fees_notification", "send_elearning_notification"):
            continue
        if k not in allowed:
            continue
        if k in ("aps_elearning_login", "aps_elearning_password") and not aps_elearning_fields_enabled:
            continue

        if k == "ssiap_exam_status":
            t[k] = _ssiap_exam_status({"ssiap_exam_status": v})
            continue

        if k == "cash_payment_installments":
            normalized_installments = []
            if isinstance(v, list):
                for item in v:
                    if not isinstance(item, dict):
                        continue
                    try:
                        amount = float(str(item.get("amount") or "").replace(",", ".").strip() or "0")
                    except (TypeError, ValueError):
                        amount = 0.0
                    normalized_installments.append({
                        "amount": round(max(amount, 0.0), 2),
                        "date": str(item.get("date") or "").strip(),
                    })
            t[k] = normalized_installments
            continue

        # bools
        if k in (
            "no_permis",
            "no_bac_diploma",
            "public_hide_infos",
            "public_hide_docs",
            "public_hide_suivi",
            "public_hide_popup",
            "force_dossier_complete",
            "financement_new_date_seen",
            "cash_payment_enabled",
            "cash_payment_settled",
            "exam_fees_paid",
            "vtc_cmar_manual_ok",
            "vtc_elearning_manual_ok",
            "vtc_book_manual_ok",
            "exclude_from_sales_tracking",
        ):
            t[k] = True if v in (True, "true", "1", 1, "yes", "on") else False
            continue

        # strings (statuts / texte)
        if v is None:
            continue

        if isinstance(v, str):
            if k == "cnaps":
                new_val = v.strip()
                if _normalize_cnaps_status(new_val) != _normalize_cnaps_status(t.get(k)):
                    t[k] = new_val
                    record_cnaps_status_change(t, new_val)
                else:
                    t[k] = new_val
                continue
            if k == "last_name":
                t[k] = normalize_last_name(v)
            elif k == "first_name":
                t[k] = normalize_first_name(v)
            elif k == "elearning_link":
                t[k] = v.strip()
            elif k == "vtc_exam_center":
                normalized_center = v.strip().lower()
                t[k] = normalized_center if normalized_center in ("nice", "toulon") else ""
            elif k == "vtc_theory_status_manual":
                normalized_status = v.strip().lower()
                allowed_statuses = ("", "waiting_registration", "waiting_result", "success", "failed")
                t[k] = normalized_status if normalized_status in allowed_statuses else ""
                _apply_vtc_manual_exam_status(t, "theory", t[k])
            elif k == "vtc_practice_status_manual":
                normalized_status = v.strip().lower()
                allowed_statuses = ("", "waiting_registration", "waiting_theory", "waiting_result", "success", "failed")
                t[k] = normalized_status if normalized_status in allowed_statuses else ""
                _apply_vtc_manual_exam_status(t, "practice", t[k])
            else:
                t[k] = v.strip()
        else:
            t[k] = v

    if "vae_status" in payload or "vae_status_label" in payload:
        requested_vae = (payload.get("vae_status") or payload.get("vae_status_label") or "").strip()
        view = vae_status_view(requested_vae)
        t["vae_status"] = view["key"]
        t["vae_status_label"] = view["label"]

    _sync_vae_status_with_actions(t)
    current_vae_status = vae_status_view(t.get("vae_status"))["key"]
    if vae_fields_changed and current_vae_status != previous_vae_status:
        if send_vae_notification:
            _notify_vae_status_change(t, current_vae_status)
        if (_session_get(s, "training_type", "") or "").strip().upper() == "DIRIGEANT VAE":
            current_view = vae_status_view(current_vae_status)
            previous_view = vae_status_view(previous_vae_status)
            _add_vae_live_notification(
                s,
                t,
                current_view["label"],
                actor="integrale",
                details=f"Ancien statut : {previous_view['label']}",
                kind=f"integrale_{current_vae_status}",
            )

    if (payload.get("financement_status") or "").strip() == "validated":
        t["financement_rejected_note"] = ""
        t["financement_new_date_seen"] = False

    if (
        "vtc_cm_login" in payload
        or "vtc_cm_password" in payload
        or "vtc_cm_submitted_at" in payload
        or "vtc_cm_reminder_auto_disabled" in payload
        or "vtc_cm_reminder_auto_disabled_at" in payload
    ):
        _refresh_vtc_cm_reminder_schedule(t)

    t["comment"] = _remove_admin_comment_flag(t.get("comment", ""), "⚠️ Prélèvement rejeté")
    _sync_cash_payment_comment_flags(t)

    if isinstance(cnaps_remote_history, list):
        merge_cnaps_history_entries(t, _normalize_cnaps_remote_history(cnaps_remote_history))

    if "cnaps" in payload:
        new_cnaps_status = (t.get("cnaps") or "").strip()
        if _normalize_cnaps_status(new_cnaps_status) != _normalize_cnaps_status(previous_cnaps_status):
            trainee_display_name = _format_trainee_name(t.get("first_name", ""), t.get("last_name", ""))
            normalized_new = _normalize_cnaps_status(new_cnaps_status)
            icon = "🟠"
            if normalized_new == "ACCEPTE":
                icon = "🟢"
            add_admin_notification(
                data,
                f"{icon}{trainee_display_name} CNAPS {new_cnaps_status.lower()}",
                meta={
                    "type": "cnaps_status_change",
                    "session_id": s.get("id"),
                    "trainee_id": t.get("id"),
                    "old_status": previous_cnaps_status,
                    "new_status": new_cnaps_status,
                    "comment": (t.get("comment") or "").strip(),
                },
            )

    if "exam_fees_paid" in payload:
        now_paid = bool(t.get("exam_fees_paid"))
        if now_paid and not was_exam_fees_paid:
            t["exam_fees_paid_at"] = _now_iso()
            t["vtc_cm_reminder_auto_disabled"] = True
            t["vtc_cm_reminder_auto_disabled_at"] = _now_iso()
            trainee_name = f"{t.get('first_name','').strip()} {t.get('last_name','').strip()}".strip()
            session_name = _session_get(s, "name", "")
            email = (t.get("email") or "").strip()
            phone = (t.get("phone") or "").strip()
            subject = "Frais d'examen réglés"
            message = ("Nous venons de procéder au paiement de vos frais d’examen.\n"
                       "La Chambre des Métiers vous adressera prochainement votre convocation, sous réserve que l’ensemble des documents ait bien été déposé sur votre espace https://www.exament3p.fr/ et qu’ils soient conformes.")
            html = mail_layout(f"""
              <h2>Frais d'examen réglés</h2>
              <p>{message}</p>
              <p><strong>Stagiaire :</strong> {trainee_name or '—'}</p>
              <p><strong>Session :</strong> {session_name or '—'}</p>
            """)
            if send_exam_fees_notification:
                if email:
                    brevo_send_email(email, subject, html, trainee=t)
                if phone:
                    sms_prefix = f"Bonjour {t.get('first_name','').strip()}, " if (t.get("first_name") or "").strip() else "Bonjour, "
                    sms = f"{sms_prefix}{message}"
                    brevo_send_sms(phone, sms)
        elif not now_paid:
            t["exam_fees_paid_at"] = ""

    if "exam_fees_paid" in payload:
        _refresh_vtc_cm_reminder_schedule(t)

    elearning_notifications = {"email_ok": False, "sms_ok": False}
    now_elearning_link = (t.get("elearning_link") or "").strip()
    if now_elearning_link and now_elearning_link != previous_elearning_link:
        if send_elearning_notification:
            elearning_notifications = notify_elearning_access_available(t, s, now_elearning_link)
            t["elearning_link_sent_at"] = _now_iso()
            t["elearning_link_email_ok"] = bool(elearning_notifications.get("email_ok"))
            t["elearning_link_sms_ok"] = bool(elearning_notifications.get("sms_ok"))
        else:
            t["elearning_link_sent_at"] = ""
            t["elearning_link_email_ok"] = False
            t["elearning_link_sms_ok"] = False
    elif not now_elearning_link:
        t["elearning_link_sent_at"] = ""
        t["elearning_link_email_ok"] = False
        t["elearning_link_sms_ok"] = False

    if (_session_get(s, "training_type", "") or "").strip().upper() == "DIRIGEANT VAE":
        ensure_vae_relances_state(t)
        refresh_vae_relance_schedule(t)

    current_vae_action_dates = t.get("vae_action_dates") if isinstance(t.get("vae_action_dates"), dict) else {}
    livret_1_transmitted_now = bool(current_vae_action_dates.get("livret_1_transmitted_scotia"))
    livret_1_transmitted_before = bool(previous_vae_action_dates.get("livret_1_transmitted_scotia"))
    if livret_1_transmitted_now and not livret_1_transmitted_before:
        append_trainee_history_event(t, "Dossier transmis à SCOTIA", "Livret 1", "action")
        _add_vae_live_notification(
            s,
            t,
            "Dossier transmis à SCOTIA",
            actor="integrale",
            details="Livret 1",
            kind="integrale_livret_1_transmitted_scotia",
        )
        first_name = (t.get("first_name") or "").strip()
        last_name = (t.get("last_name") or "").strip()
        trainee_display_name = _format_trainee_name(first_name, last_name)
        dossier_url = f"{PUBLIC_BASE_URL.rstrip('/')}/scotia"
        subject = (
            f"Nouvelle demande de recevabilité déposée pour {trainee_display_name} "
            "- VAE Dirigeant d'entreprise de sécurité privée"
        )
        html = mail_layout(f"""
          <p><strong>{trainee_display_name}</strong>.</p>
          <p>Une nouvelle demande de recevabilité a été déposée pour {trainee_display_name} - VAE Dirigeant d'entreprise de sécurité privée.</p>
          <p style=\"text-align:center;margin:18px 0;\">
            <a href=\"{dossier_url}\" style=\"display:inline-block;background:#1f8f4a;color:#ffffff;text-decoration:none;font-weight:700;padding:12px 18px;border-radius:8px;\">Consulter le dossier</a>
          </p>
        """)
        brevo_send_email(
            "scotiaformation@gmail.com",
            subject,
            html,
            cc_emails=["clement@integraleacademy.com"],
            trainee=t,
        )

    t["updated_at"] = _now_iso()
    s["trainees"] = trainees
    s.pop("stagiaires", None)
    training_type = _session_get(s, "training_type", "")
    dossier_complete = dossier_is_complete_total(t, training_type, _session_get(s, "date_start", ""))
    t["dossier_status"] = "complete" if dossier_complete else "incomplete"
    planned = _docs_relance_planned_date(s)
    t["docs_relance_auto_planned_date"] = "" if dossier_complete else (planned.isoformat() if planned else "")
    if dossier_complete:
        t["docs_relance_auto_sent_at"] = ""

    if "VTC" in ((_session_get(s, "training_type", "") or "").upper()):
        _sync_vtc_book_notification(data, s, t)
    save_data(data)
    return jsonify({
        "ok": True,
        "dossier_status": t.get("dossier_status"),
        "force_dossier_complete": bool(t.get("force_dossier_complete")),
        "docs_relance_auto_planned_date": t.get("docs_relance_auto_planned_date") or "",
        "elearning_link_sent_at": t.get("elearning_link_sent_at") or "",
        "elearning_link_email_ok": bool(t.get("elearning_link_email_ok")),
        "elearning_link_sms_ok": bool(t.get("elearning_link_sms_ok")),
        "vtc_theory_status_manual": t.get("vtc_theory_status_manual") or "",
        "vtc_practice_status_manual": t.get("vtc_practice_status_manual") or "",
    })


@app.post("/api/sessions/<session_id>/stagiaires/<trainee_id>/refresh-external")
@admin_login_required
@admin_write_required
def api_refresh_trainee_external(session_id: str, trainee_id: str):
    data = load_data()
    s = find_session(data, session_id)
    if not s:
        return jsonify({"ok": False, "error": "session_not_found"}), 404

    trainees = _session_trainees_list(s)
    t = next((x for x in trainees if x.get("id") == trainee_id), None)
    if not t:
        return jsonify({"ok": False, "error": "trainee_not_found"}), 404

    ln = normalize_last_name(t.get("last_name") or "")
    fn = normalize_first_name(t.get("first_name") or "")
    if ln:
        t["last_name"] = ln
    if fn:
        t["first_name"] = fn
    email = (t.get("email") or "").strip().lower()

    current_cnaps = (t.get("cnaps") or "").strip() or "INCONNU"
    if ln and fn:
        cn = fetch_cnaps_status_by_name(ln, fn)
        if cn:
            cn_u = str(cn).strip().upper()
            if cn_u not in ("INCONNU", "UNKNOWN", ""):
                if _normalize_cnaps_status(cn_u) != _normalize_cnaps_status(current_cnaps):
                    t["cnaps"] = cn_u
                    record_cnaps_status_change(t, cn_u)
                else:
                    t["cnaps"] = current_cnaps
            else:
                t["cnaps"] = current_cnaps
        else:
            t["cnaps"] = current_cnaps
    else:
        t["cnaps"] = current_cnaps

    training_type = _session_get(s, "training_type", "")
    if training_type == "A3P":
        current_hosting = (t.get("hosting_status") or "unknown").strip().lower() or "unknown"
        _log_charles_hebergement_trace(
            "api_refresh_trainee_external",
            "état local avant refresh API",
            email=email,
            last_name=ln,
            first_name=fn,
            session_name=_session_get(s, "name", ""),
            session_date_start=_session_get(s, "date_start", ""),
            session_date_end=_session_get(s, "date_end", ""),
            current_hosting_status=current_hosting,
        )
        _log_charles_hebergement_trace(
            "api_refresh_trainee_external",
            "appel fetch_hebergement_status depuis l'API",
            email=email,
            last_name=ln,
            first_name=fn,
            session_name=_session_get(s, "name", ""),
            session_date_start=_session_get(s, "date_start", ""),
            session_date_end=_session_get(s, "date_end", ""),
        )
        hb = fetch_hebergement_status(
            email,
            last_name=ln,
            first_name=fn,
            session_name=_session_get(s, "name", ""),
            session_date_start=_session_get(s, "date_start", ""),
            session_date_end=_session_get(s, "date_end", ""),
        )
        _log_charles_hebergement_trace(
            "api_refresh_trainee_external",
            "résultat fetch_hebergement_status depuis l'API",
            email=email,
            last_name=ln,
            first_name=fn,
            session_name=_session_get(s, "name", ""),
            session_date_start=_session_get(s, "date_start", ""),
            session_date_end=_session_get(s, "date_end", ""),
            fetch_result=hb,
            current_hosting_status=current_hosting,
        )
        if hb == "reserved" or current_hosting == "reserved":
            t["hosting_status"] = "reserved"
        else:
            t["hosting_status"] = current_hosting
        _log_charles_hebergement_trace(
            "api_refresh_trainee_external",
            "valeur finale sauvegardée après refresh API",
            email=email,
            last_name=ln,
            first_name=fn,
            session_name=_session_get(s, "name", ""),
            session_date_start=_session_get(s, "date_start", ""),
            session_date_end=_session_get(s, "date_end", ""),
            final_hosting_status=t.get("hosting_status"),
        )
    else:
        t.pop("hosting_status", None)

    t["updated_at"] = _now_iso()
    s["trainees"] = trainees
    s.pop("stagiaires", None)
    save_data(data)

    response_payload = {
        "ok": True,
        "cnaps_status": t.get("cnaps") or "INCONNU",
        "hosting_status": (t.get("hosting_status") or "unknown") if training_type == "A3P" else "",
    }
    _log_charles_hebergement_trace(
        "api_refresh_trainee_external",
        "payload final renvoyé au front",
        email=email,
        last_name=ln,
        first_name=fn,
        session_name=_session_get(s, "name", ""),
        session_date_start=_session_get(s, "date_start", ""),
        session_date_end=_session_get(s, "date_end", ""),
        response_payload=response_payload,
    )
    return jsonify(response_payload)


@app.post("/api/sessions/<session_id>/stagiaires/<trainee_id>/pre-reception")
@admin_login_required
@admin_write_required
def api_admin_pre_reception(session_id: str, trainee_id: str):
    data = load_data()
    s = find_session(data, session_id)
    if not s:
        return jsonify({"ok": False, "error": "session_not_found"}), 404

    trainees = _session_trainees_list(s)
    t = next((x for x in trainees if x.get("id") == trainee_id), None)
    if not t:
        return jsonify({"ok": False, "error": "trainee_not_found"}), 404

    payload = request.get_json(silent=True) or {}
    pre_raw = (payload.get("pre_number") or "").strip()
    if not pre_raw:
        return jsonify({"ok": False, "error": "missing_pre"}), 400

    pre = _normalize_pre_car(pre_raw)
    if not _is_valid_pre_car(pre):
        return jsonify({"ok": False, "error": "invalid_pre"}), 400

    t["pre_number"] = pre
    training_type = _session_get(s, "training_type", "")
    t["dossier_status"] = "complete" if dossier_is_complete_total(t, training_type, _session_get(s, "date_start", "")) else "incomplete"
    t["updated_at"] = _now_iso()

    s["trainees"] = trainees
    s.pop("stagiaires", None)
    save_data(data)

    email = (t.get("email") or "").strip()
    training_name = formation_label(_session_get(s, "training_type", "") or s.get("name") or "formation")
    dstart = fr_date(s.get("date_start") or "")
    dend = fr_date(s.get("date_end") or "")
    date_phrase = f"qui se déroulera du {dstart} au {dend}." if dstart and dend else "qui se déroulera prochainement."

    html = mail_layout(f"""
        <p>Bonjour,</p>
        <p>
          Nous revenons vers vous concernant votre formation <strong>{training_name}</strong>, {date_phrase}
        </p>
        <p>
          Vous nous avez indiqué ne pas avoir reçu par courrier postal votre autorisation préalable du CNAPS
          (Ministère de l'intérieur), alors que votre demande a bien été validée par leurs services.
        </p>
        <p>
          Afin de pouvoir finaliser votre entrée en formation, nous avons donc pris contact avec le CNAPS pour obtenir
          votre numéro d’autorisation.
          Après vérification, le CNAPS nous a confirmé que votre numéro d’autorisation est le suivant :
          <strong>{pre}</strong>
        </p>
        <p>Nous vous informons que votre dossier en ligne a été automatiquement complété avec ce numéro.</p>
        <p>Nous restons à votre disposition si besoin et vous souhaitons une excellente journée.</p>
        <p>Bien cordialement,<br>Intégrale Academy</p>
    """)

    email_ok = brevo_send_email(email, "Votre numéro d’autorisation CNAPS (PRE)", html, trainee=t) if email else False

    return jsonify({"ok": True, "pre_number": pre, "email_ok": bool(email_ok)})

