@app.post("/api/vtc/check/import")
@admin_login_required
@admin_write_required
def api_vtc_check_import():
    mode = (request.args.get("mode") or "theory").strip().lower()
    if mode not in {"theory", "practice"}:
        mode = "theory"

    pdf = request.files.get("file")
    if not pdf:
        return jsonify({"ok": False, "error": "missing_file"}), 400

    filename = (pdf.filename or "").lower()
    if not (filename.endswith(".pdf") or filename.endswith(".xlsx") or filename.endswith(".csv")):
        return jsonify({"ok": False, "error": "invalid_file_type"}), 400

    pdf_bytes = pdf.read() or b""

    try:
        extraction = _extract_vtc_exam_results(filename, pdf_bytes)
        identifiers = extraction.get("all_ids") or []
        admissible_tokens = set(extraction.get("admissible_ids") or [])
        non_admissible_tokens = set(extraction.get("non_admissible_ids") or [])
    except Exception:
        return jsonify({"ok": False, "error": "file_parse_error"}), 400

    file_alnum, file_digits = ("", "")
    if filename.endswith(".pdf"):
        file_alnum, file_digits = _build_pdf_search_haystacks(pdf_bytes)
    else:
        file_alnum, file_digits = _build_excel_search_haystacks(filename, pdf_bytes)

    if not identifiers:
        return jsonify({"ok": True, "matches": [], "count": 0, "message": "aucun stagiaire VTC trouvé"})

    data = load_data()
    wanted = set()
    for identifier in identifiers:
        wanted.update(_cmar_identifier_match_keys(identifier))

    admissible_tokens = {
        key
        for token in admissible_tokens
        for key in _cmar_identifier_match_keys(token)
    }
    non_admissible_tokens = {
        key
        for token in non_admissible_tokens
        for key in _cmar_identifier_match_keys(token)
    }

    admissible_matches = []
    non_admissible_matches = []
    seen = set()

    for sess in data.get("sessions", []):
        if "VTC" not in (_session_get(sess, "training_type", "") or "").upper():
            continue
        trainees = _session_trainees_list(sess)
        for trainee in trainees:
            cmar_id_raw = trainee.get("vtc_cmar_id") or ""
            cmar_id = _canonical_cmar_identifier(cmar_id_raw)
            if not cmar_id:
                continue

            cmar_keys = _cmar_identifier_match_keys(cmar_id)
            token_match = bool(cmar_keys & wanted)

            cmar_digits = re.sub(r"\D", "", cmar_id)
            cmar_digits_stripped = cmar_digits.lstrip("0") or "0"
            fallback_alnum_match = bool(file_alnum and f" {cmar_id} " in file_alnum)
            fallback_digits_match = bool(cmar_digits and len(cmar_digits) >= CMAR_MIN_IDENTIFIER_DIGITS and file_digits and (
                f" {cmar_digits} " in file_digits or (len(cmar_digits_stripped) >= CMAR_MIN_IDENTIFIER_DIGITS and f" {cmar_digits_stripped} " in file_digits)
            ))

            if not (token_match or fallback_alnum_match or fallback_digits_match):
                continue

            key = (sess.get("id"), trainee.get("id"))
            if key in seen:
                continue
            seen.add(key)
            target = admissible_matches
            status = "admissible"
            if cmar_keys & non_admissible_tokens:
                target = non_admissible_matches
                status = "non_admissible"
            elif admissible_tokens and (cmar_keys & admissible_tokens):
                target = admissible_matches
                status = "admissible"

            sent_key = "vtc_practice_exam_sent_at" if mode == "practice" else "vtc_theory_exam_sent_at"
            result_key = "vtc_practice_result" if mode == "practice" else "vtc_theory_result"
            already_notified = bool(trainee.get(sent_key))
            already_marked_non_admissible = (trainee.get(result_key) == "non_admissible")
            already_imported = bool(trainee.get(result_key)) or already_notified or already_marked_non_admissible

            target.append({
                "session_id": sess.get("id") or "",
                "session_name": sess.get("name") or "",
                "trainee_id": trainee.get("id") or "",
                "first_name": (trainee.get("first_name") or "").strip(),
                "last_name": (trainee.get("last_name") or "").strip(),
                "cmar_id": trainee.get("vtc_cmar_id") or "",
                "status": status,
                "already_imported": already_imported,
                "already_notified": already_notified,
                "already_marked_non_admissible": already_marked_non_admissible,
            })

    count_adm = len(admissible_matches)
    count_non_adm = len(non_admissible_matches)
    count = count_adm + count_non_adm
    already_imported_count = sum(1 for it in (admissible_matches + non_admissible_matches) if it.get("already_imported"))
    if count == 0:
        message = "aucun stagiaire VTC trouvé"
    else:
        message = (
            f"{count} stagiaire(s) trouvé(s) • {count_adm} admissible(s) • {count_non_adm} non admissible(s)"
            f" • {already_imported_count} déjà importé(s)"
        )

    return jsonify({
        "ok": True,
        "matches": admissible_matches + non_admissible_matches,
        "admissible_matches": admissible_matches,
        "non_admissible_matches": non_admissible_matches,
        "count": count,
        "admissible_count": count_adm,
        "non_admissible_count": count_non_adm,
        "already_imported_count": already_imported_count,
        "message": message,
    })


@app.post("/api/vtc/check/notify")
@admin_login_required
@admin_write_required
def api_vtc_check_notify():
    mode = (request.args.get("mode") or "theory").strip().lower()
    if mode not in {"theory", "practice"}:
        mode = "theory"

    payload = request.get_json(silent=True) or {}
    items = payload.get("items") or []
    if not isinstance(items, list) or not items:
        return jsonify({"ok": False, "error": "missing_items"}), 400

    data = load_data()
    sent = 0
    failed = 0
    non_admissible_marked = 0
    skipped_already_notified = 0
    skipped_already_marked = 0

    for item in items:
        session_id = str(item.get("session_id") or "").strip()
        session_name = str(item.get("session_name") or "").strip()
        trainee_id = str(item.get("trainee_id") or "").strip()
        cmar_id = _canonical_cmar_identifier(item.get("cmar_id") or "")
        if not trainee_id and not cmar_id:
            failed += 1
            continue

        sess = None
        if session_id:
            sess = find_session(data, session_id)
            if not sess:
                sess = next((s for s in data.get("sessions", []) if str(s.get("id") or "").strip() == session_id), None)

        if not sess:
            candidate_sessions = []
            for candidate in data.get("sessions", []):
                trainees_in_candidate = _session_trainees_list(candidate)
                trainee_match = next(
                    (
                        x
                        for x in trainees_in_candidate
                        if (trainee_id and str(x.get("id") or "").strip() == trainee_id)
                        or (cmar_id and _canonical_cmar_identifier(x.get("vtc_cmar_id") or "") == cmar_id)
                    ),
                    None,
                )
                if trainee_match:
                    candidate_sessions.append(candidate)

            if session_name:
                named_matches = [s for s in candidate_sessions if str(s.get("name") or "").strip() == session_name]
                if len(named_matches) == 1:
                    sess = named_matches[0]
            if not sess and len(candidate_sessions) == 1:
                sess = candidate_sessions[0]

        if not sess:
            failed += 1
            continue

        trainees = _session_trainees_list(sess)
        trainee = next((x for x in trainees if trainee_id and str(x.get("id") or "").strip() == trainee_id), None)
        if not trainee and cmar_id:
            trainee = next(
                (
                    x
                    for x in trainees
                    if _canonical_cmar_identifier(x.get("vtc_cmar_id") or "") == cmar_id
                ),
                None,
            )
        if not trainee:
            if cmar_id:
                trainee = next(
                    (
                        x
                        for x in trainees
                        if _canonical_cmar_identifier(x.get("vtc_cmar_id") or "") == cmar_id
                    ),
                    None,
                )
        if not trainee:
            failed += 1
            continue

        status = str(item.get("status") or "admissible").strip().lower()
        if status == "non_admissible":
            result_key = "vtc_practice_result" if mode == "practice" else "vtc_theory_result"
            if trainee.get(result_key) == "non_admissible":
                skipped_already_marked += 1
                continue
            if mode == "practice":
                trainee["vtc_practice_result"] = "non_admissible"
                trainee["vtc_practice_result_label"] = "échec examen pratique"
                trainee["vtc_practice_failed_at"] = _now_iso()
                add_admin_notification(
                    data,
                    f"🚘 {_format_trainee_name(trainee.get('first_name', ''), trainee.get('last_name', ''))} a échoué à l'examen pratique VTC",
                    {
                        "kind": "vtc_practice_exam_failed",
                        "session_id": sess.get("id") or "",
                        "session_name": sess.get("name") or "",
                        "trainee_id": trainee.get("id") or "",
                        "first_name": trainee.get("first_name") or "",
                        "last_name": trainee.get("last_name") or "",
                    },
                )
            else:
                trainee["vtc_theory_result"] = "non_admissible"
                trainee["vtc_theory_result_label"] = "échec examen théorique"
                trainee["vtc_theory_failed_at"] = _now_iso()
                add_admin_notification(
                    data,
                    f"🚘 {_format_trainee_name(trainee.get('first_name', ''), trainee.get('last_name', ''))} a échoué à l'examen théorique VTC",
                    {
                        "kind": "vtc_theory_exam_failed",
                        "session_id": sess.get("id") or "",
                        "session_name": sess.get("name") or "",
                        "trainee_id": trainee.get("id") or "",
                        "first_name": trainee.get("first_name") or "",
                        "last_name": trainee.get("last_name") or "",
                    },
                )
            non_admissible_marked += 1
        else:
            sent_key = "vtc_practice_exam_sent_at" if mode == "practice" else "vtc_theory_exam_sent_at"
            if trainee.get(sent_key):
                skipped_already_notified += 1
                continue
            try:
                if mode == "practice":
                    _send_vtc_practice_exam_success_notification(sess, trainee)
                else:
                    trainee["vtc_theory_result"] = "admissible"
                    trainee["vtc_theory_result_label"] = "admissible"
                    _send_vtc_theory_exam_notification(sess, trainee, send_notifications=True)
                    _add_vtc_practice_convocation_notification(data, sess, trainee)
                sent += 1
            except Exception:
                failed += 1
                continue

        sess["trainees"] = trainees
        sess.pop("stagiaires", None)

    save_data(data)
    return jsonify({
        "ok": True,
        "sent": sent,
        "failed": failed,
        "non_admissible_marked": non_admissible_marked,
        "skipped_already_notified": skipped_already_notified,
        "skipped_already_marked": skipped_already_marked,
    })

