@app.get("/health/storage")
def health_storage():
    exists = os.path.exists(DATA_FILE)
    stat_result = os.stat(DATA_FILE) if exists else None
    data = load_data()
    trainees_count, sessions_count = _count_loaded_objects(data)
    return jsonify({
        "ok": True,
        "data_path": DATA_FILE,
        "exists": exists,
        "size": stat_result.st_size if stat_result else 0,
        "mtime": int(stat_result.st_mtime) if stat_result else None,
        "count_stagiaires": trainees_count,
        "count_sessions": sessions_count,
    })


@app.post("/api/test-positionnement/submit")
def api_positioning_test_submit():
    payload = request.get_json(silent=True) or {}
    contact = payload.get("contact") or {}
    answers = payload.get("answers") or {}

    contact_data = {
        "last_name": (contact.get("last_name") or "").strip(),
        "first_name": (contact.get("first_name") or "").strip(),
        "email": (contact.get("email") or "").strip(),
        "phone": (contact.get("phone") or "").strip(),
    }
    if not all(contact_data.values()):
        return jsonify({"ok": False, "error": "missing_contact_fields"}), 400

    email_normalized = contact_data["email"].lower()

    score_data = positioning_test_score(answers)

    data = load_data()
    existing_entries = data.get("positioning_tests", [])
    already_submitted = any(
        (entry.get("contact") or {}).get("email", "").strip().lower() == email_normalized
        for entry in existing_entries
    )
    if already_submitted:
        return jsonify({"ok": False, "error": "email_already_submitted"}), 409

    entry = {
        "id": uuid.uuid4().hex,
        "created_at": _now_iso(),
        "contact": contact_data,
        "answers": answers,
        "score": score_data["score"],
        "total": score_data["total"],
        "score_over_20": score_data["score_over_20"],
    }

    data.setdefault("positioning_tests", []).append(entry)
    save_data(data)

    return jsonify(
        {
            "ok": True,
            "score": score_data["score"],
            "total": score_data["total"],
            "score_over_20": score_data["score_over_20"],
        }
    )


@app.post("/api/test-positionnement/<test_id>/delete")
@admin_login_required
@admin_write_required
def api_positioning_test_delete(test_id: str):
    data = load_data()
    _force_backup_snapshot(DATA_FILE)
    entries = list(data.get("positioning_tests", []))
    new_entries = [e for e in entries if e.get("id") != test_id]
    data["positioning_tests"] = new_entries
    save_data(data)
    return jsonify({"ok": True, "deleted": len(entries) - len(new_entries)})


@app.post("/api/test-positionnement/<test_id>/contact")
@admin_login_required
@admin_write_required
def api_positioning_test_update_contact(test_id: str):
    payload = request.get_json(silent=True) or {}
    last_name = normalize_last_name(payload.get("last_name") or "")
    first_name = normalize_first_name(payload.get("first_name") or "")

    if not last_name or not first_name:
        return jsonify({"ok": False, "error": "missing_name_fields"}), 400

    data = load_data()
    entry = next((e for e in data.get("positioning_tests", []) if e.get("id") == test_id), None)
    if not entry:
        return jsonify({"ok": False, "error": "not_found"}), 404

    contact = entry.setdefault("contact", {})
    contact["last_name"] = last_name
    contact["first_name"] = first_name
    entry["updated_at"] = _now_iso()

    save_data(data)
    return jsonify({
        "ok": True,
        "contact": {
            "last_name": contact.get("last_name") or "",
            "first_name": contact.get("first_name") or "",
        },
    })


@app.post("/api/test-positionnement/delete_all")
@admin_login_required
@admin_write_required
def api_positioning_test_delete_all():
    data = load_data()
    _force_backup_snapshot(DATA_FILE)
    deleted = len(data.get("positioning_tests", []))
    data["positioning_tests"] = []
    save_data(data)
    return jsonify({"ok": True, "deleted": deleted})

from werkzeug.utils import secure_filename



# =========================
# Upload helpers
# =========================
ALLOWED_EXT = {".pdf", ".png", ".jpg", ".jpeg", ".doc", ".docx", ".webp", ".zip"}

def _safe_ext(filename: str) -> str:
    return os.path.splitext(filename)[1].lower()

def _store_file(session_id: str, trainee_id: str, folder: str, f) -> str:
    base = trainee_upload_dir(session_id, trainee_id)
    target_dir = os.path.join(base, folder)
    os.makedirs(target_dir, exist_ok=True)

    filename = secure_filename(f.filename or "file")
    ext = _safe_ext(filename)
    if ext and ext not in ALLOWED_EXT:
        raise ValueError("extension_not_allowed")

    name = uuid.uuid4().hex[:10] + (ext or "")
    path = os.path.join(target_dir, name)
    f.save(path)
    return path

def _tokenize_path(path: str) -> str:
    # on ne renvoie pas le chemin réel au template
    # token = path relatif à PERSIST_DIR
    rel = os.path.relpath(path, PERSIST_DIR).replace("\\","/")
    return rel

def _detokenize_path(token: str) -> str:
    token = (token or "").replace("\\", "/").lstrip("/")
    candidate = os.path.realpath(os.path.join(PERSIST_DIR, token))
    root = os.path.realpath(PERSIST_DIR)
    if candidate != root and not candidate.startswith(root + os.sep):
        abort(403)
    return candidate

@app.get("/admin/uploads/<path:path>")
@admin_login_required
def admin_view_upload(path: str):
    full = _detokenize_path(path)
    if not os.path.exists(full):
        abort(404)
    # simple serve
    return send_file(full, as_attachment=False)


@app.get("/admin/uploads/<path:path>/download")
@admin_login_required
def admin_download_upload(path: str):
    full = _detokenize_path(path)
    if not os.path.exists(full):
        abort(404)
    return send_file(full, as_attachment=True)

def _token_belongs_to_trainee(t: dict, file_token: str) -> bool:
    file_token = (file_token or "").strip()
    if not file_token:
        return False

    # Deliverables (diplôme / SST / attestation)
    dv = t.get("deliverables") or {}
    for k in ("diplome", "carte_sst", "attestation_fin_formation", "attestation_recevabilite", "livret_2", "parchemin"):
        if (dv.get(k) or "").strip() == file_token:
            return True

    # Documents (mono + multi fichiers)
    for d in (t.get("documents") or []):
        if (d.get("file") or "").strip() == file_token:
            return True
        files = d.get("files")
        if isinstance(files, list) and file_token in [x.strip() for x in files if isinstance(x, str)]:
            return True

    # Photo identité (optionnel mais utile)
    if (t.get("identity_photo") or "").strip() == file_token:
        return True

    return False


@app.get("/espace/<token>/download/<path:file_token>")
def public_download_file(token: str, file_token: str):
    data = load_data()
    s, t = find_session_and_trainee_by_token(data, token)
    if not s or not t:
        abort(404)

    # Sécurité : le fichier doit appartenir à CE stagiaire
    if not _token_belongs_to_trainee(t, file_token):
        abort(403)

    full = _detokenize_path(file_token)
    if not os.path.exists(full):
        abort(404)

    return send_file(full, as_attachment=False)


def _public_trainee_last_names(trainee: Dict[str, Any]) -> set[str]:
    names = {
        _norm_lastname(trainee.get("last_name", "")),
        _norm_lastname(trainee.get("nom", "")),
        _norm_lastname(trainee.get("birth_name", "")),
        _norm_lastname(trainee.get("nom_naissance", "")),
        _norm_lastname(trainee.get("nom_usage", "")),
        _norm_lastname(trainee.get("name", "")),
    }
    return {name for name in names if name}


def _public_trainee_birth_dates(trainee: Dict[str, Any]) -> set[str]:
    dates = {
        _birth_to_ddmmyyyy(trainee.get("birth_date", "")),
        _birth_to_ddmmyyyy(trainee.get("date_naissance", "")),
        _birth_to_ddmmyyyy(trainee.get("dateNaissance", "")),
        _birth_to_ddmmyyyy(trainee.get("date_de_naissance", "")),
        _birth_to_ddmmyyyy(trainee.get("birthdate", "")),
        _birth_to_ddmmyyyy(trainee.get("dob", "")),
    }
    return {date for date in dates if date}


def _public_trainee_identity_matches(trainee: Dict[str, Any], last_name: str, birth: str) -> bool:
    expected_last = _norm_lastname(last_name)
    expected_birth = _birth_to_ddmmyyyy(birth)
    if not expected_last or not expected_birth:
        return False
    return expected_last in _public_trainee_last_names(trainee) and expected_birth in _public_trainee_birth_dates(trainee)


def _find_public_trainee_matches_by_identity(data: Dict[str, Any], last_name: str, birth: str) -> list[tuple[Dict[str, Any], Dict[str, Any]]]:
    """Retourne toutes les correspondances exactes nom normalisé + date normalisée."""
    expected_last = _norm_lastname(last_name)
    expected_birth = _birth_to_ddmmyyyy(birth)
    if not expected_last or not expected_birth:
        return []

    matches: list[tuple[Dict[str, Any], Dict[str, Any]]] = []
    for session_obj in data.get("sessions", []) or []:
        for trainee in _session_trainees_list(session_obj):
            trainee_token = (trainee.get("public_token") or trainee.get("token") or "").strip()
            if trainee_token and _public_trainee_identity_matches(trainee, last_name, birth):
                matches.append((session_obj, trainee))
    return matches


def _find_public_trainee_by_identity(data: Dict[str, Any], last_name: str, birth: str):
    """Retourne l'unique stagiaire correspondant au nom + date, sinon (None, None)."""
    matches = _find_public_trainee_matches_by_identity(data, last_name, birth)
    if len(matches) == 1:
        return matches[0]
    return None, None

def _public_login_debug_summary(
    data: Dict[str, Any], last_name: str, birth: str, *, limit: int = 8
) -> Dict[str, Any]:
    expected_last = _norm_lastname(last_name)
    expected_birth = _birth_to_ddmmyyyy(birth)
    summary: Dict[str, Any] = {
        "input_last_norm": expected_last,
        "input_birth_norm": expected_birth,
        "sessions_count": len(data.get("sessions", []) or []),
        "trainees_count": 0,
        "name_matches_count": 0,
        "birth_matches_count": 0,
        "name_birth_matches_count": 0,
        "matched_trainee_id": "",
        "matched_session_id": "",
        "matched_token_present": False,
        "near_matches": [],
    }

    near_matches = summary["near_matches"]
    for session_obj in data.get("sessions", []) or []:
        session_id = session_obj.get("id") or session_obj.get("name") or ""
        for trainee in _session_trainees_list(session_obj):
            summary["trainees_count"] += 1
            names = sorted(_public_trainee_last_names(trainee))
            dates = sorted(_public_trainee_birth_dates(trainee))
            name_match = bool(expected_last and expected_last in names)
            birth_match = bool(expected_birth and expected_birth in dates)
            if name_match:
                summary["name_matches_count"] += 1
            if birth_match:
                summary["birth_matches_count"] += 1
            if name_match and birth_match:
                summary["name_birth_matches_count"] += 1
                if not summary["matched_trainee_id"]:
                    summary["matched_trainee_id"] = trainee.get("id") or ""
                    summary["matched_session_id"] = session_id
                    summary["matched_token_present"] = bool((trainee.get("public_token") or trainee.get("token") or "").strip())
            if name_match or birth_match:
                if len(near_matches) < limit:
                    near_matches.append({
                        "session_id": session_id,
                        "trainee_id": trainee.get("id") or "",
                        "token_present": bool((trainee.get("public_token") or trainee.get("token") or "").strip()),
                        "name_match": name_match,
                        "birth_match": birth_match,
                        "names_norm": names,
                        "births_norm": dates,
                        "raw_last_name": trainee.get("last_name") or trainee.get("nom") or "",
                        "raw_birth_date": (
                            trainee.get("birth_date")
                            or trainee.get("date_naissance")
                            or trainee.get("dateNaissance")
                            or ""
                        ),
                    })
    return summary


@app.get("/espacestagiaire")
def public_trainee_global_login():
    if session.get("admin_logged_in"):
        return redirect(url_for("admin_sessions"))

    return render_template(
        "public_trainee_login.html",
        action_url=url_for("public_trainee_global_login_post"),
        error=(request.args.get("error") or "").strip() == "1",
        multiple=(request.args.get("error") or "").strip() == "multiple",
        last_name=request.args.get("last_name", ""),
    )


@app.post("/espacestagiaire")
def public_trainee_global_login_post():
    data = load_data()
    last_in = (request.form.get("last_name") or "").strip()
    birth_in = (request.form.get("birth") or "").strip()

    matches = _find_public_trainee_matches_by_identity(data, last_in, birth_in)
    if len(matches) != 1:
        log_label = "PUBLIC_GLOBAL_LOGIN_AMBIGUOUS" if len(matches) > 1 else "PUBLIC_GLOBAL_LOGIN_FAIL"
        app.logger.warning(
            "[%s] last_name=%r birth_input=%r debug=%s",
            log_label,
            last_in,
            birth_in,
            _public_login_debug_summary(data, last_in, birth_in),
        )
        error_code = "multiple" if len(matches) > 1 else "1"
        return redirect(url_for("public_trainee_global_login", error=error_code, last_name=last_in))

    session_obj, trainee = matches[0]
    token = (trainee.get("public_token") or trainee.get("token") or "").strip()
    app.logger.info(
        "[PUBLIC_GLOBAL_LOGIN_OK] session_id=%s trainee_id=%s last_name=%r birth_norm=%s",
        session_obj.get("id") or session_obj.get("name") or "",
        trainee.get("id") or "",
        last_in,
        _birth_to_ddmmyyyy(birth_in),
    )
    session[f"public_auth_{token}"] = True
    session.permanent = True
    _mark_public_login(data, session_obj, trainee)
    return redirect(url_for("public_trainee_space", token=token))


