@app.post("/admin/sessions/<session_id>/stagiaires/<trainee_id>/identity-photo/upload")
@admin_login_required
@admin_write_required
def admin_upload_identity_photo(session_id: str, trainee_id: str):
    data = load_data()
    s = find_session(data, session_id)
    if not s:
        abort(404)

    trainees = _session_trainees_list(s)
    t = next((x for x in trainees if x.get("id") == trainee_id), None)
    if not t:
        abort(404)

    f = request.files.get("file")
    if not f or not f.filename:
        return redirect(url_for("admin_trainee_page", session_id=session_id, trainee_id=trainee_id))

    # ✅ on limite aux images
    ext = _safe_ext(f.filename)
    if ext not in (".jpg", ".jpeg", ".png", ".webp"):
        return redirect(url_for("admin_trainee_page", session_id=session_id, trainee_id=trainee_id))

    try:
        stored = _store_file(session_id, trainee_id, "identity_photo", f)
    except Exception:
        return redirect(url_for("admin_trainee_page", session_id=session_id, trainee_id=trainee_id))

    token = _tokenize_path(stored)

    # ✅ on sauvegarde le token dans le stagiaire
    t["identity_photo"] = token
    t["updated_at"] = _now_iso()

    s["trainees"] = trainees
    s.pop("stagiaires", None)
    save_data(data)

    return redirect(url_for("admin_trainee_page", session_id=session_id, trainee_id=trainee_id))


@app.post("/espace/<token>/infos/update")
def public_infos_update(token: str):
    data = load_data()
    s, t = find_session_and_trainee_by_token(data, token)
    if not s or not t:
        return jsonify({"ok": False}), 404

    payload = request.get_json(silent=True) or {}

    # champs autorisés (sécurité)
    allowed = {
        "carte_vitale",
        "pre_number",
        "tshirt_size",
        "birth_date",
        "birth_city",
        "birth_country",
        "nationality",
        "address",
        "zip_code",
        "city",
        "no_permis",
    }

    previous_vae_status = vae_status_view(t.get("vae_status"))["key"]

    for k, v in payload.items():
        if k not in allowed:
            continue

        # no_permis = bool
        if k == "no_permis":
            t["no_permis"] = bool(v)
            continue
        if k == "tshirt_size":
            size = str(v or "").strip().upper()
            if size in TSHIRT_SIZES:
                t["tshirt_size"] = size
            continue

        # strings : on n'écrase PAS avec vide
        if v is None:
            continue
        if isinstance(v, str):
            vv = v.strip()
            if vv == "":
                continue
            t[k] = vv
        else:
            # si jamais tu envoies autre chose
            t[k] = v

    training_type = _session_get(s, "training_type", "")
    t["dossier_status"] = "complete" if dossier_is_complete_total(t, training_type, _session_get(s, "date_start", "")) else "incomplete"
    t["updated_at"] = _now_iso()

    # ✅ IMPORTANT : persister la session normalisée comme ailleurs
    s["trainees"] = _session_trainees_list(s)
    s.pop("stagiaires", None)
    save_data(data)

    return jsonify({"ok": True})


@app.post("/espace/<token>/vtc-credentials")
def public_vtc_credentials(token: str):
    data = load_data()
    s, t = find_session_and_trainee_by_token(data, token)
    if not s or not t:
        return jsonify({"ok": False}), 404

    if not _public_is_authed(token):
        return jsonify({"ok": False, "error": "not_authenticated"}), 403

    payload = request.get_json(silent=True) or {}
    login = (payload.get("login") or "").strip()
    password = (payload.get("password") or "").strip()

    if not login or not password:
        return jsonify({"ok": False, "error": "missing_credentials"}), 400

    if not re.match(r"^[^\s@]+@[^\s@]+\.[^\s@]+$", login):
        return jsonify({"ok": False, "error": "invalid_login_email"}), 400

    t["vtc_cm_login"] = login
    t["vtc_cm_password"] = password
    t["vtc_cm_submitted_at"] = _now_iso()
    t["updated_at"] = _now_iso()

    trainee_display_name = _format_trainee_name(t.get("first_name", ""), t.get("last_name", ""))
    add_admin_notification(
        data,
        f"🟢{trainee_display_name} - Identifiants chambre des métiers VTC envoyés",
        meta={
            "type": "vtc_credentials",
            "session_id": s.get("id"),
            "trainee_id": t.get("id"),
            "comment": (t.get("comment") or "").strip(),
        },
    )

    s["trainees"] = _session_trainees_list(s)
    s.pop("stagiaires", None)
    save_data(data)

    trainee_name = f"{t.get('first_name','').strip()} {t.get('last_name','').strip()}".strip()
    session_name = _session_get(s, "name", "")
    subject = "Identifiants examen VTC transmis"
    html = mail_layout(f"""
      <h2>Identifiants VTC transmis</h2>
      <p><strong>Stagiaire :</strong> {trainee_name or '—'}</p>
      <p><strong>Session :</strong> {session_name or '—'}</p>
      <p><strong>Email :</strong> {t.get("email") or "—"}</p>
      <p><strong>Téléphone :</strong> {t.get("phone") or "—"}</p>
      <hr style="margin:16px 0;border:none;border-top:1px solid #e5e7eb">
      <p><strong>Login :</strong> {login}</p>
      <p><strong>Mot de passe :</strong> {password}</p>
    """)
    brevo_send_email(
        "clement@integraleacademy.com",
        subject,
        html,
        cc_emails=["elsaduq83@gmail.com"],
    )

    return jsonify({"ok": True})



@app.post("/espace/<token>/documents/<doc_key>/upload")
def public_doc_upload(token: str, doc_key: str):
    data = load_data()
    s, t = find_session_and_trainee_by_token(data, token)
    if not s or not t:
        abort(404)

    training_type = _session_get(s, "training_type", "")
    _sync_trainee_afc_medical_requirement(t, _session_get(s, "name", ""))
    ensure_documents_schema_for_trainee(t, training_type)
    if (training_type or "").strip().upper() == "DIRIGEANT VAE":
        _ensure_livret2_document_entry(t)
        _ensure_complementary_documents_entry(t)
        _ensure_public_complementary_documents_upload_entry(t)

    # ✅ doc_key doit être dans la liste requise
    if doc_key not in allowed_doc_keys_for_training(training_type, t):
        return redirect(url_for("public_trainee_space", token=token))

    # ✅ retrouver la config du doc (accept)
    docs = t.get("documents") or []
    target = next((d for d in docs if d.get("key") == doc_key), None)
    if not target:
        return redirect(url_for("public_trainee_space", token=token))

    # ✅ 1 fichier par envoi (mais l'ID peut en contenir 2)
    incoming_files = request.files.getlist("files") or request.files.getlist("file")
    incoming_files = [f for f in incoming_files if f and f.filename]
    if not incoming_files:
        if doc_key == "livret_2":
            existing_files = target.get("files") if isinstance(target.get("files"), list) else []
            legacy_file = (target.get("file") or "").strip()
            has_existing_livret_2 = bool(existing_files or legacy_file)
            if has_existing_livret_2:
                if not isinstance(t.get("vae_action_dates"), dict):
                    t["vae_action_dates"] = {}
                t["vae_action_dates"]["livret_2_received"] = datetime.date.today().strftime("%d/%m/%Y")
                view = vae_status_view("livret_2_analysis")
                previous_status = (t.get("vae_status") or "").strip()
                t["vae_status"] = view["key"]
                t["vae_status_label"] = view["label"]
                if previous_status != view["key"]:
                    _notify_vae_status_change(t, "livret_2_analysis")
                    trainee_display_name = _format_trainee_name(t.get("first_name", ""), t.get("last_name", ""))
                    add_admin_notification(
                        data,
                        f"VAE Livret 2️⃣ Déposé par {trainee_display_name}",
                        meta={
                            "type": "vae_livret_2_upload",
                            "session_id": s.get("id"),
                            "trainee_id": t.get("id"),
                        },
                    )
                t["updated_at"] = _now_iso()
                t["dossier_status"] = "complete" if dossier_is_complete_total(t, training_type, _session_get(s, "date_start", "")) else "incomplete"
                s["trainees"] = _session_trainees_list(s)
                s.pop("stagiaires", None)
                save_data(data)
        return redirect(url_for("public_trainee_space", token=token))

    accept = (target.get("accept") or "").lower()

    def _accepts_file(ext: str) -> bool:
        acc = [a.strip().lower() for a in accept.split(",") if a.strip()]
        allowed_exts = set()
        if "application/pdf" in acc:
            allowed_exts.add(".pdf")
        if any(a.startswith("image/") for a in acc) or ("image/jpeg" in acc) or ("image/png" in acc):
            allowed_exts.update({".jpg", ".jpeg", ".png", ".webp"})
        if allowed_exts:
            return ext in allowed_exts
        return ext in ALLOWED_EXT

    # ✅ stockage du fichier
    session_id = s.get("id")
    trainee_id = t.get("id")

    # ✅ MAJ du doc: on APPEND dans files (sans écraser)
    original_name = ""
    for d in docs:
        if d.get("key") == doc_key:
            cur_files = d.get("files")
            if not isinstance(cur_files, list):
                cur_files = []

            # compat: si un ancien "file" existe mais pas dans files, on le garde
            old = (d.get("file") or "").strip()
            if old and old not in cur_files:
                cur_files.append(old)

            cur_status = (d.get("status") or "").strip().upper()
            if cur_status in ("NON CONFORME", "NON_CONFORME"):
                cur_files = []
            max_files = 2 if doc_key == "id" else (-1 if doc_key in {"livret_2", "complementary_documents"} else 1)
            if max_files < 0:
                files_to_store = incoming_files
            else:
                remaining_slots = max(max_files - len(cur_files), 0)
                files_to_store = incoming_files[:remaining_slots] if remaining_slots else []
            if not files_to_store:
                return redirect(url_for("public_trainee_space", token=token))

            for f in files_to_store:
                ext = _safe_ext(f.filename)
                if not _accepts_file(ext):
                    return redirect(url_for("public_trainee_space", token=token))

            for f in files_to_store:
                if not original_name:
                    original_name = secure_filename(f.filename or "document")
                stored = _store_file(session_id, trainee_id, "public_documents", f)
                new_token = _tokenize_path(stored)
                cur_files.append(new_token)

            # on garde le premier fichier dans "file" (pour compat template/admin)
            d["files"] = cur_files
            d["file"] = cur_files[0] if cur_files else ""

            cur = (d.get("status") or "").strip().upper()
            if cur in ("", "NON DÉPOSÉ", "NON DEPOSE", "NON_DEPOSE") or cur_status in ("NON CONFORME", "NON_CONFORME"):
                d["status"] = "A CONTRÔLER"
            if d.get("status") == "A CONTROLER":
                d["status"] = "A CONTRÔLER"
            break

    t["updated_at"] = _now_iso()
    t["dossier_status"] = "complete" if dossier_is_complete_total(t, training_type, _session_get(s, "date_start", "")) else "incomplete"

    # ✅ persistance
    s["trainees"] = _session_trainees_list(s)
    s.pop("stagiaires", None)
    save_data(data)

    if doc_key == "complementary_documents":
        if not isinstance(t.get("vae_action_dates"), dict):
            t["vae_action_dates"] = {}
        t["vae_action_dates"]["complementary_documents_received"] = _now_paris_label()
        _mark_complementary_documents_to_control(t)
        target["status"] = "A CONTRÔLER"
        _sync_complementary_document_tokens_from_document(t, target)
        trainee_display_name = _format_trainee_name(t.get("first_name", ""), t.get("last_name", ""))
        add_admin_notification(
            data,
            f"VAE complément déposé par {trainee_display_name}",
            meta={
                "type": "vae_complementary_documents_upload",
                "session_id": s.get("id"),
                "trainee_id": t.get("id"),
            },
        )
        _notify_scotia_complementary_documents(t, s, len(files_to_store), "l'espace candidat")
        save_data(data)

    if doc_key == "livret_2":
        if not isinstance(t.get("vae_action_dates"), dict):
            t["vae_action_dates"] = {}
        t["vae_action_dates"]["livret_2_received"] = datetime.date.today().strftime("%d/%m/%Y")
        view = vae_status_view("livret_2_analysis")
        t["vae_status"] = view["key"]
        t["vae_status_label"] = view["label"]
        _notify_vae_status_change(t, "livret_2_analysis")
        trainee_display_name = _format_trainee_name(t.get("first_name", ""), t.get("last_name", ""))
        add_admin_notification(
            data,
            f"VAE Livret 2️⃣ Déposé par {trainee_display_name}",
            meta={
                "type": "vae_livret_2_upload",
                "session_id": s.get("id"),
                "trainee_id": t.get("id"),
            },
        )
        save_data(data)

    # ✅ IMPORTANT: on renvoie l’info au GET (pour popup + scroll ensuite)
    return redirect(url_for(
        "public_trainee_space",
        token=token,
        uploaded=doc_key,
        fname=original_name
    ))


@app.post("/espace/<token>/documents/candidate_info_sheet/validate")
def public_candidate_sheet_validate(token: str):
    data = load_data()
    s, t = find_session_and_trainee_by_token(data, token)
    if not s or not t:
        abort(404)

    if not _public_is_authed(token):
        return redirect(url_for("public_trainee_login", token=token))

    training_type = _session_get(s, "training_type", "")
    if not _is_dirigeant_candidate_sheet_training(training_type):
        return redirect(url_for("public_trainee_space", token=token))

    ensure_documents_schema_for_trainee(t, training_type)

    docs = t.get("documents") or []
    target = next((d for d in docs if d.get("key") == "candidate_info_sheet"), None)
    if target:
        target["status"] = "A CONTRÔLER"
        if target.get("status") == "A CONTROLER":
            target["status"] = "A CONTRÔLER"

    t["updated_at"] = _now_iso()
    t["dossier_status"] = "complete" if dossier_is_complete_total(t, training_type, _session_get(s, "date_start", "")) else "incomplete"

    s["trainees"] = _session_trainees_list(s)
    s.pop("stagiaires", None)
    save_data(data)

    return redirect(url_for("public_trainee_space", token=token))



APS_CONVOCATION_CENTER_NAME = "Intégrale Academy"
APS_CONVOCATION_CENTER_ADDRESS = "54 chemin du Carreou"
APS_CONVOCATION_CENTER_ZIP = "83480"
APS_CONVOCATION_CENTER_CITY = "Puget-sur-Argens"
APS_CONVOCATION_DIR = os.path.join(PERSIST_DIR, "generated_documents", "convocations_aps")
os.makedirs(APS_CONVOCATION_DIR, exist_ok=True)
APS_CONVOCATION_VARIABLES = [
    "civilite", "prenom", "nom", "nom_complet", "adresse_ligne1", "adresse_ligne2",
    "adresse_ligne3", "adresse_ligne4", "code_postal", "ville", "formation_nom",
    "nom_pedagogique", "date_convocation", "heure_convocation", "date_debut_formation",
    "date_fin_formation", "periode_formation", "periode_elearning", "periode_presentiel",
    "date_examen", "heure_examen", "date_jour", "lieu_formation", "espace_stagiaire_url",
    "h_elearning", "h_presentiel", "h_total", "duree_exam", "modalites_suivi",
    "date_ouverture", "lieu_examen",
]


def _is_aps_session(session_obj: Dict[str, Any]) -> bool:
    return (_session_get(session_obj, "training_type", "") or "").strip().upper().startswith("APS")


def _safe_filename_part(value: Any) -> str:
    normalized = unicodedata.normalize("NFKD", str(value or "")).encode("ascii", "ignore").decode("ascii")
    normalized = re.sub(r"[^A-Za-z0-9_-]+", "-", normalized).strip("-").lower()
    return normalized or "stagiaire"


def _format_long_fr_date(value: str) -> str:
    value = (value or "").strip()
    if not value:
        return ""
    months = ["", "janvier", "février", "mars", "avril", "mai", "juin", "juillet", "août", "septembre", "octobre", "novembre", "décembre"]
    try:
        dt = datetime.datetime.strptime(value[:10], "%Y-%m-%d").date()
        return f"{dt.day} {months[dt.month]} {dt.year}"
    except Exception:
        return value




def _aps_template_path() -> str:
    return os.path.join(app.root_path, "templates_word", "convocationaps.docx")


def _split_address_lines(address: str, max_lines: int = 4) -> List[str]:
    raw_lines = [line.strip() for line in re.split(r"[\r\n]+", str(address or "")) if line.strip()]
    if not raw_lines and address:
        raw_lines = [str(address).strip()]
    lines = raw_lines[:max_lines]
    while len(lines) < max_lines:
        lines.append("")
    return lines


def _build_aps_convocation_context(session_obj: Dict[str, Any], trainee: Dict[str, Any]) -> Dict[str, str]:
    required = [
        (trainee.get("email"), "email du stagiaire manquant"),
        (trainee.get("first_name") or trainee.get("prenom"), "prénom du stagiaire manquant"),
        (trainee.get("last_name") or trainee.get("nom"), "nom du stagiaire manquant"),
        (_session_get(session_obj, "date_start", ""), "date de début de formation manquante"),
        (_session_get(session_obj, "date_end", ""), "date de fin de formation manquante"),
        (_session_get(session_obj, "exam_date", ""), "date d’examen manquante"),
    ]
    for value, message in required:
        if not str(value or "").strip():
            raise ValueError(f"Impossible de générer la convocation APS : {message}")

    _sync_aps_period_dates(session_obj)
    first_name = str(trainee.get("first_name") or trainee.get("prenom") or "").strip()
    last_name = str(trainee.get("last_name") or trainee.get("nom") or "").strip().upper()
    civility = str(trainee.get("civility") or trainee.get("civilite") or "").strip()
    full_name = f"{civility} {first_name} {last_name}".strip()
    address_lines = _split_address_lines(str(trainee.get("address") or trainee.get("adresse") or "").strip())
    zip_code = str(trainee.get("zip_code") or trainee.get("code_postal") or trainee.get("postal_code") or "").strip()
    city = str(trainee.get("city") or trainee.get("ville") or "").strip().upper()
    training_name = str(_session_get(session_obj, "name", "") or _session_get(session_obj, "training_type", "") or "Formation APS").strip()
    remote_start = str(_session_get(session_obj, "aps_remote_start", "") or _session_get(session_obj, "date_start", "")).strip()
    remote_end = str(_session_get(session_obj, "aps_remote_end", "") or remote_start).strip()
    in_person_start = str(_session_get(session_obj, "aps_in_person_start", "") or _session_get(session_obj, "date_start", "")).strip()
    in_person_end = str(_session_get(session_obj, "aps_in_person_end", "") or _session_get(session_obj, "date_end", "")).strip()
    public_token = (trainee.get("public_token") or trainee.get("token") or "").strip()
    trainee_space_url = f"{PUBLIC_STUDENT_PORTAL_BASE.rstrip('/')}/espace/{public_token}" if public_token else f"{PUBLIC_STUDENT_PORTAL_BASE.rstrip('/')}/espacestagiaire"
    date_start = str(_session_get(session_obj, "date_start", "")).strip()
    date_end = str(_session_get(session_obj, "date_end", "")).strip()
    exam_date = str(_session_get(session_obj, "exam_date", "")).strip()
    convocation_time = str(_session_get(session_obj, "convocation_time", "") or session_obj.get("heure_convocation") or "08h30").strip() or "08h30"
    exam_time = str(_session_get(session_obj, "exam_time", "") or session_obj.get("heure_examen") or "08h00").strip() or "08h00"
    place = f"{APS_CONVOCATION_CENTER_NAME} - {APS_CONVOCATION_CENTER_ADDRESS} - {APS_CONVOCATION_CENTER_ZIP} {APS_CONVOCATION_CENTER_CITY}"
    return {
        "civilite": civility, "prenom": first_name, "nom": last_name, "nom_complet": full_name,
        "adresse_ligne1": address_lines[0], "adresse_ligne2": address_lines[1], "adresse_ligne3": address_lines[2], "adresse_ligne4": address_lines[3],
        "code_postal": zip_code, "ville": city, "formation_nom": training_name,
        "nom_pedagogique": str(_session_get(session_obj, "nom_pedagogique", "") or training_name).strip(),
        "date_convocation": fr_date(date_start), "heure_convocation": convocation_time,
        "date_debut_formation": fr_date(date_start), "date_fin_formation": fr_date(date_end),
        "periode_formation": f"du {fr_date(date_start)} au {fr_date(date_end)}",
        "periode_elearning": f"du {fr_date(remote_start)} au {fr_date(remote_end)}",
        "periode_presentiel": f"du {fr_date(in_person_start)} au {fr_date(in_person_end)}",
        "date_examen": fr_date(exam_date), "heure_examen": exam_time,
        "date_jour": datetime.datetime.utcnow().strftime("%d/%m/%Y"),
        "lieu_formation": place, "lieu_examen": place, "espace_stagiaire_url": trainee_space_url,
        "modalites_suivi": "Suivi pédagogique et administratif assuré par l’équipe Intégrale Academy.",
        "date_ouverture": fr_date(remote_start),
        "h_elearning": "62", "h_presentiel": "113", "h_total": "175", "duree_exam": "07h00",
    }


def _assert_aps_template_contains_expected_variables(template_path: str) -> None:
    placeholders: Set[str] = set()
    pattern = re.compile(r"\{\{\s*([^{}]+?)\s*\}\}")
    with zipfile.ZipFile(template_path) as zf:
        for name in zf.namelist():
            if name.startswith("word/") and name.endswith(".xml"):
                xml_text = zf.read(name).decode("utf-8", errors="ignore")
                placeholders.update(match.strip() for match in pattern.findall(xml_text))
                try:
                    plain_text = "".join(ET.fromstring(xml_text).itertext())
                    placeholders.update(match.strip() for match in pattern.findall(plain_text))
                except Exception:
                    pass
    missing = [name for name in APS_CONVOCATION_VARIABLES if name not in placeholders]
    if missing:
        raise RuntimeError("Le modèle Word templates_word/convocationaps.docx ne contient pas toutes les variables APS attendues : " + ", ".join(missing))


def _find_libreoffice_binary() -> str:
    for binary in ("libreoffice", "soffice"):
        path = shutil.which(binary)
        app.logger.info("[CONVOCATION APS] %s: %s", binary, path)
        print(f"[CONVOCATION APS] {binary}: {path}", flush=True)
        if path:
            return path
    raise RuntimeError("LibreOffice est introuvable sur le serveur : installez libreoffice ou soffice pour convertir la convocation APS en PDF.")


def _assert_docx_has_no_unresolved_variables(docx_path: str) -> None:
    unresolved: Set[str] = set()
    pattern = re.compile(r"\{\{[^{}]+\}\}")
    with zipfile.ZipFile(docx_path) as zf:
        for name in zf.namelist():
            if name.startswith("word/") and name.endswith(".xml"):
                xml_text = zf.read(name).decode("utf-8", errors="ignore")
                unresolved.update(pattern.findall(xml_text))
                try:
                    plain_text = "".join(ET.fromstring(xml_text).itertext())
                    unresolved.update(pattern.findall(plain_text))
                except Exception:
                    pass
    if unresolved:
        raise RuntimeError("Variables non remplacées dans la convocation APS : " + ", ".join(sorted(unresolved)))


def _render_docx_with_python_template(template_path: str, output_docx_path: str, context: Dict[str, str]) -> None:
    if DocxTemplate is None:
        raise RuntimeError("Dépendance Python manquante : docxtpl n’est pas installée. Vérifier requirements.txt et redéployer Render.")
    app_dir = os.path.dirname(os.path.abspath(__file__))
    app.logger.info("[CONVOCATION APS] cwd Python: %s", os.getcwd())
    app.logger.info("[CONVOCATION APS] app dir: %s", app_dir)
    os.makedirs(os.path.dirname(output_docx_path), exist_ok=True)
    doc = DocxTemplate(template_path)
    doc.render(context)
    doc.save(output_docx_path)


def _generate_aps_convocation_files(session_obj: Dict[str, Any], trainee: Dict[str, Any], session_id: str = "", trainee_id: str = "") -> Tuple[str, str]:
    template_path = _aps_template_path()
    app.logger.info("[CONVOCATION APS] Modèle Word utilisé : %s", template_path)
    if not os.path.exists(template_path):
        raise FileNotFoundError("Modèle Word obligatoire manquant : gestionstagiaires/templates_word/convocationaps.docx")
    _assert_aps_template_contains_expected_variables(template_path)
    context = _build_aps_convocation_context(session_obj, trainee)
    app.logger.info("[CONVOCATION APS] Données injectées : stagiaire=%s formation=%s période=%s examen=%s", context.get("nom_complet"), context.get("formation_nom"), context.get("periode_formation"), context.get("date_examen"))
    base = f"convocation_aps_{_safe_filename_part(trainee.get('id') or trainee_id)}"
    final_docx_path = os.path.join(APS_CONVOCATION_DIR, base + ".docx")
    final_pdf_path = os.path.join(APS_CONVOCATION_DIR, base + ".pdf")
    _render_docx_with_python_template(template_path, final_docx_path, context)
    app.logger.info("[CONVOCATION APS] DOCX final généré : %s", final_docx_path)
    if not os.path.exists(final_docx_path) or os.path.getsize(final_docx_path) <= 0:
        raise RuntimeError("Le DOCX final de convocation APS est introuvable ou vide.")
    final_docx_size = os.path.getsize(final_docx_path)
    app.logger.info("[CONVOCATION APS] Taille DOCX final : %s octets", final_docx_size)
    _assert_docx_has_no_unresolved_variables(final_docx_path)
    lo_binary = _find_libreoffice_binary()
    output_dir = APS_CONVOCATION_DIR
    command = [lo_binary, "--headless", "--convert-to", "pdf", "--outdir", output_dir, final_docx_path]
    app.logger.info("[CONVOCATION APS] Binaire LibreOffice trouvé : %s", lo_binary)
    app.logger.info("[CONVOCATION APS] Chemin PDF attendu : %s", final_pdf_path)
    app.logger.info("[CONVOCATION APS] Commande conversion : %s", " ".join(command))
    if os.path.exists(final_pdf_path): os.remove(final_pdf_path)
    try:
        subprocess.run(command, check=True, capture_output=True, text=True, timeout=120)
    except subprocess.CalledProcessError as exc:
        app.logger.error("[CONVOCATION APS] Conversion LibreOffice impossible (code %s)", exc.returncode)
        app.logger.error("[CONVOCATION APS] stdout LibreOffice: %s", (exc.stdout or "").strip())
        app.logger.error("[CONVOCATION APS] stderr LibreOffice: %s", (exc.stderr or "").strip())
        raise RuntimeError(f"Conversion LibreOffice impossible : {(exc.stderr or exc.stdout or '').strip()}") from exc
    app.logger.info("[CONVOCATION APS] PDF final généré : %s", final_pdf_path)
    if not os.path.exists(final_pdf_path) or os.path.getsize(final_pdf_path) <= 0:
        raise RuntimeError("Le PDF final de convocation APS est introuvable ou vide après conversion LibreOffice.")
    return final_docx_path, final_pdf_path


def _generate_aps_convocation_pdf(session_obj: Dict[str, Any], trainee: Dict[str, Any], session_id: str = "", trainee_id: str = "") -> str:
    return _generate_aps_convocation_files(session_obj, trainee, session_id, trainee_id)[1]


def _aps_convocation_allowed_pdf_roots() -> List[str]:
    roots = [APS_CONVOCATION_DIR]
    upload_root = None
    try:
        upload_root = app.config.get("UPLOAD_FOLDER")
    except Exception:
        upload_root = None
    if not upload_root:
        upload_root = os.environ.get("UPLOAD_FOLDER")
    if not upload_root:
        upload_root = os.path.join(os.path.dirname(os.path.abspath(__file__)), "uploads")
    roots.append(os.path.join(upload_root, "convocations_aps"))
    return [os.path.abspath(root) for root in roots if root]


def _aps_convocation_pdf_is_allowed(pdf_path: str) -> bool:
    abs_pdf_path = os.path.abspath(pdf_path)
    return any(abs_pdf_path.startswith(root + os.sep) for root in _aps_convocation_allowed_pdf_roots())


